export interface BasicParams {
  waveform: 'sine' | 'square' | 'sawtooth';
  harmonics: number; // 1 to 32 (Fourier Additive)
  attack: number; // ADSR
  release: number; // ADSR
}

export interface StringParams {
  damping: number; // 0.001 to 0.1
  pluckPosition: number; // 0.1 to 0.5
  tension: number; // Slight frequency offset multiplier
  bodyResonance: number; // 0 to 1
}

export interface GuitarParams {
  distortionType: DistortionType;
  drive: number; // 1 to 100
  tone: number; // 0 to 1 (Low to High)
  active: boolean; // Active pickups vs Passive (higher gain/comp)
  sustain: number; // 0 to 1 - Controls string decay time
  cabinetType: CabinetType;
}

export interface WindParams {
  pressure: number; // Breath pressure
