}

import { 
  DrumType, VowelType, DistortionType, CabinetType, NoiseColor, VocalPreset, VocalMode,
  StringParams, VocalParams, DrumParams, GuitarParams, BasicParams, WindParams, MetalParams, ChaosParams 
} from '../types';

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
  'F#': 23.12, 'G': 24.50, 'G#': 25.96, 'A': 27.50, 'A#': 29.14, 'B': 30.87
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

// Helper: Convert AudioBuffer to WAV Blob
export const bufferToWav = (buffer: AudioBuffer): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  // write fmt sub-chunk
  setUint32(0x20746d66); // "fmt "
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(buffer.sampleRate);
  setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this parser)

  // write data sub-chunk
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      // clamp
      sample = Math.max(-1, Math.min(1, channels[i][pos])); 
      // scale to 16-bit signed int
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
      view.setInt16(44 + offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

/**
 * Convolution Reverb Generator (Space/Resonance Model)
 */
export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  // 1. Generate Impulse Response (Exponential Decay Noise)
  // Model: y(t) = Noise(t) * e^(-t / T)
  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    // White noise * exponential decay
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  // 2. Convolve
  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

// --- SYNTHESIS ENGINES ---

export const renderBasic = async (ctx: OfflineAudioContext, params: BasicParams, duration: number, baseFreq: number): Promise<AudioBuffer> => {
  const osc = ctx.createOscillator();
  osc.type = params.waveform;
  osc.frequency.value = baseFreq;
  const master = ctx.createGain();
  master.connect(ctx.destination);
  const t = ctx.currentTime;
  master.gain.setValueAtTime(0, t);
  master.gain.linearRampToValueAtTime(1.0, t + params.attack);
  master.gain.exponentialRampToValueAtTime(0.001, t + duration - 0.01);
  if (params.harmonics > 1) {
    for(let i=1; i<=params.harmonics; i++) {
      const hOsc = ctx.createOscillator();
      hOsc.type = 'sine';
      hOsc.frequency.value = baseFreq * i;
      const hGain = ctx.createGain();
      hGain.gain.value = 1 / i;
      hOsc.connect(hGain);
      hGain.connect(master);
      hOsc.start(t);
      hOsc.stop(t + duration);
    }
  } else {
    osc.connect(master);
    osc.start(t);
    osc.stop(t + duration);
  }
  return await ctx.startRendering();
}

export const renderWind = async (ctx: OfflineAudioContext, params: WindParams, duration: number, baseFreq: number): Promise<AudioBuffer> => {
  const sampleRate = ctx.sampleRate;
  const f0 = baseFreq;
  const N = Math.round(sampleRate / f0 / 2);
  const buffer = ctx.createBuffer(1, sampleRate * duration, sampleRate);
  const data = buffer.getChannelData(0);
  const delayLine = new Float32Array(N);
  let ptr = 0;
  let lastOut = 0;
  for (let i = 0; i < data.length; i++) {
    const attack = 0.1;
    let env = 1;
    if (i < sampleRate * attack) env = i / (sampleRate * attack);
    else if (i > data.length - (sampleRate * 0.1)) env = (data.length - i) / (sampleRate * 0.1);
    const breath = params.pressure * env;
    const noise = (Math.random() * 2 - 1) * params.noiseLevel * env;
    const feedback = lastOut * 0.95; 
    const delta = breath + feedback;
    const reed = Math.tanh(delta * (1 + params.lipTension)) - (delta * 0.1); 
    const excitation = reed + noise;
    delayLine[ptr] = excitation;
    const delayOut = delayLine[(ptr + 1) % N]; 
    lastOut = (delayOut + lastOut) * 0.5; 
    data[i] = lastOut * 0.5;
    ptr++;
    if (ptr >= N) ptr = 0;
  }
  return buffer;
}

export const renderMetal = async (ctx: OfflineAudioContext, params: MetalParams, duration: number, baseFreq: number): Promise<AudioBuffer> => {
  const master = ctx.createGain();
  master.connect(ctx.destination);
  const t = 0;
  const baseRatios = [1, 1.414, 1.732, 2.0, 2.7, 3.14, 4.5]; 
  const ratios = baseRatios.map(r => 1 + (r - 1) * params.ratios);
  ratios.forEach((r, idx) => {
    const osc = ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = baseFreq * r;
    const gain = ctx.createGain();
    const modeDecay = params.decay / (1 + idx); 
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(1.0 / ratios.length, t + 0.005 * params.impact);
    gain.gain.exponentialRampToValueAtTime(0.001, t + modeDecay);
    osc.connect(gain);
    gain.connect(master);
    osc.start(t);
    osc.stop(t + duration);
  });
  const noiseBuff = ctx.createBuffer(1, ctx.sampleRate * 0.05, ctx.sampleRate);
  const nd = noiseBuff.getChannelData(0);
  for(let i=0; i<nd.length; i++) nd[i] = (Math.random()*2-1) * params.impact;
  const noiseSrc = ctx.createBufferSource();
  noiseSrc.buffer = noiseBuff;
  const nGain = ctx.createGain();
  nGain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
  noiseSrc.connect(nGain);
  nGain.connect(master);
  noiseSrc.start(t);
  return await ctx.startRendering();
}

export const renderChaos = async (ctx: OfflineAudioContext, params: ChaosParams, duration: number, baseFreq: number): Promise<AudioBuffer> => {
  const buffer = ctx.createBuffer(1, ctx.sampleRate * duration, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  let lastOut = 0;
  for (let i = 0; i < data.length; i++) {
    const white = Math.random() * 2 - 1;
    let out = white;
    if (params.color === NoiseColor.BROWN) {
      out = (lastOut + (0.02 * white)) / 1.02;
      lastOut = out;
      out *= 3.5; 
    } else if (params.color === NoiseColor.PINK) {
      const b0 = 0.99765 * lastOut + white * 0.05;
      out = b0;
      lastOut = b0;
      out *= 2.0; 
    }
    const drift = Math.sin(i / ctx.sampleRate * 2 * Math.PI * params.instability) * 0.2;
    data[i] = Math.max(-1, Math.min(1, out + drift));
  }
  return buffer;
}

export const renderStrings = async (ctx: OfflineAudioContext, params: StringParams, duration: number, baseFreq: number): Promise<AudioBuffer> => {
  const buffer = ctx.createBuffer(1, ctx.sampleRate * duration, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  const sampleRate = ctx.sampleRate;
  const f0 = baseFreq * params.tension;
  const N = Math.round(sampleRate / f0);
  const delayLine = new Float32Array(N);
  for (let i = 0; i < N; i++) {
     delayLine[i] = (Math.random() * 2 - 1) * Math.exp(-i / (N * params.pluckPosition));
  }
  let lastVal = 0;
  for (let i = 0; i < data.length; i++) {
    const delayIndex = i % N;
    const val = delayLine[delayIndex];
    const decay = 1 - params.damping;
    const newVal = decay * 0.5 * (val + lastVal);
    delayLine[delayIndex] = newVal;
    lastVal = val;
    data[i] = Math.tanh(newVal * (1 + params.bodyResonance));
  }
  return buffer;
};

export const renderGuitar = async (ctx: OfflineAudioContext, params: GuitarParams, duration: number, baseFreq: number): Promise<AudioBuffer> => {
  const sampleRate = ctx.sampleRate;
  const f0 = baseFreq;
  const N = Math.round(sampleRate / f0);
  const rawBuffer = ctx.createBuffer(1, sampleRate * duration, sampleRate);
  const rawData = rawBuffer.getChannelData(0);
  const delayLine = new Float32Array(N);
  for (let i = 0; i < N; i++) delayLine[i] = (Math.random() * 2 - 1); 
  let lastVal = 0;
  const sustain = params.sustain ?? 0.9;
  const stringDamping = 0.02 * (1 - sustain) + 0.001;
  for (let i = 0; i < rawData.length; i++) {
    const delayIndex = i % N;
    const val = delayLine[delayIndex];
    const newVal = (1 - stringDamping) * 0.5 * (val + lastVal);
    delayLine[delayIndex] = newVal;
    lastVal = val;
    rawData[i] = newVal;
  }
  const ctxPickup = new OfflineAudioContext(1, sampleRate * duration, sampleRate);
  const srcPickup = ctxPickup.createBufferSource();
  srcPickup.buffer = rawBuffer;
  const hpf = ctxPickup.createBiquadFilter();
  hpf.type = 'highpass';
  hpf.frequency.value = 80; 
  const lpf = ctxPickup.createBiquadFilter();
  lpf.type = 'lowpass';
  lpf.frequency.value = params.active ? 8000 : 5000;
  lpf.Q.value = params.active ? 0.5 : 1.5;
  srcPickup.connect(hpf);
  hpf.connect(lpf);
  lpf.connect(ctxPickup.destination);
  srcPickup.start();
  const pickupBuffer = await ctxPickup.startRendering();
  const signal = pickupBuffer.getChannelData(0);
  const drive = params.drive;
  const type = params.distortionType;
  for (let i = 0; i < signal.length; i++) {
    let x = signal[i] * drive;
    if (type === DistortionType.OVERDRIVE) x = Math.tanh(x);
    else if (type === DistortionType.DISTORTION) x = Math.max(-0.8, Math.min(0.8, x)) * 1.25;
    else if (type === DistortionType.FUZZ) {
      x = (2 / Math.PI) * Math.asin(Math.sin(x));
      x = Math.max(-1, Math.min(1, x * 1.5)); 
    }
    signal[i] = x;
  }
  const ctxCab = new OfflineAudioContext(1, sampleRate * duration, sampleRate);
  const srcCab = ctxCab.createBufferSource();
  const processedBuffer = ctxCab.createBuffer(1, signal.length, sampleRate);
  processedBuffer.copyToChannel(signal, 0);
  srcCab.buffer = processedBuffer;
  const toneFilter = ctxCab.createBiquadFilter();
  if (params.tone < 0.5) {
     toneFilter.type = 'lowshelf';
     toneFilter.frequency.value = 400;
     toneFilter.gain.value = (0.5 - params.tone) * 20;
  } else {
     toneFilter.type = 'highshelf';
     toneFilter.frequency.value = 2000;
     toneFilter.gain.value = (params.tone - 0.5) * 20;
  }
  const cabLpf = ctxCab.createBiquadFilter();
  const cabHpf = ctxCab.createBiquadFilter();
  const cabPeak = ctxCab.createBiquadFilter();
  switch (params.cabinetType) {
    case CabinetType.SMALL_1x8:
      cabLpf.type = 'lowpass'; cabLpf.frequency.value = 4500; cabLpf.Q.value = 0.5;
      cabHpf.type = 'highpass'; cabHpf.frequency.value = 150;
      cabPeak.type = 'peaking'; cabPeak.frequency.value = 800; cabPeak.gain.value = 3; cabPeak.Q.value = 1;
      break;
    case CabinetType.MEDIUM_2x12:
      cabLpf.type = 'lowpass'; cabLpf.frequency.value = 5000; cabLpf.Q.value = 0.7;
      cabHpf.type = 'highpass'; cabHpf.frequency.value = 90;
      cabPeak.type = 'peaking'; cabPeak.frequency.value = 400; cabPeak.gain.value = -2; cabPeak.Q.value = 0.5; 
      break;
    case CabinetType.LARGE_4x12:
      cabLpf.type = 'lowpass'; cabLpf.frequency.value = 4000; cabLpf.Q.value = 0.8;
      cabHpf.type = 'highpass'; cabHpf.frequency.value = 75; cabHpf.Q.value = 1.1; 
      cabPeak.type = 'peaking'; cabPeak.frequency.value = 110; cabPeak.gain.value = 2; cabPeak.Q.value = 2;
      break;
    case CabinetType.DIRECT:
    default:
      cabLpf.type = 'lowpass'; cabLpf.frequency.value = 18000;
      cabHpf.type = 'highpass'; cabHpf.frequency.value = 30;
      cabPeak.gain.value = 0;
      break;
  }
  const micPeak = ctxCab.createBiquadFilter();
  if (params.cabinetType !== CabinetType.DIRECT) {
    micPeak.type = 'peaking';
    micPeak.frequency.value = 3500; 
    micPeak.gain.value = 4;
  } else {
    micPeak.gain.value = 0;
  }
  srcCab.connect(toneFilter);
  toneFilter.connect(cabLpf);
  cabLpf.connect(cabHpf);
  cabHpf.connect(cabPeak);
  cabPeak.connect(micPeak);
  micPeak.connect(ctxCab.destination);
  srcCab.start();
  return await ctxCab.startRendering();
};


// --- VOCAL SYNTHESIS ENGINE (PT-BR) ---

// PHONETIC DEFINITIONS
interface PhonemeDef {
  formants: number[];
  gain: number;
  noise: number; // 0 to 1 mix of noise
  noiseType?: 'white' | 'pink' | 'highpass';
  durationScale: number; // 1.0 = standard, 0.5 = fast (consonant)
}

// 1. Dictionary of Phonemes (Oral, Nasal, Consonant Approximations)
const PHONEME_LIB: Record<string, PhonemeDef> = {
