        </div>

        {/* Dynamic Controls based on Tab */}
        <div className="space-y-4">

          {activeTab === InstrumentType.BASIC && (
            <>
              <div className="text-xs text-slate-500 uppercase tracking-widest font-bold ml-1 mb-2">Additive Synthesis</div>
               <div className="flex gap-2 mb-4 p-1 bg-synth-panel rounded-lg border border-synth-grid">
