import { SequencerNote } from '../types';

/**
 * Simple MIDI Parser to convert ArrayBuffer to SequencerNote[]
 * Supports basic NoteOn/NoteOff events.
 */
export const parseMidiFile = (arrayBuffer: ArrayBuffer): SequencerNote[] => {
  const data = new DataView(arrayBuffer);
  let offset = 0;

  // Header Chunk
  const headerChunkType = getText(data, offset, 4);
  offset += 4;
  if (headerChunkType !== 'MThd') throw new Error('Invalid MIDI Header');

  const headerLength = data.getUint32(offset);
  offset += 4;

  const format = data.getUint16(offset);
  offset += 2;
  const numTracks = data.getUint16(offset);
  offset += 2;
  const timeDivision = data.getUint16(offset);
  offset += 2;

  let notes: SequencerNote[] = [];

  // Calculate seconds per tick (assuming 120 BPM if no tempo event found, standard MIDI logic)
  let microsecondsPerBeat = 500000; // 120 BPM default

  // Iterate Tracks
  for (let t = 0; t < numTracks; t++) {
    // Track Chunk
    if (offset >= data.byteLength) break;
    const trackChunkType = getText(data, offset, 4);
    offset += 4;

    if (trackChunkType !== 'MTrk') break;

    const trackLength = data.getUint32(offset);
    offset += 4;

    const trackEnd = offset + trackLength;
    let currentTime = 0; // Ticks
    let runningStatus = 0;

    // Map to track active notes: key = midiNote, value = { startTimeTick }
    const activeNotes: Record<number, number> = {};

    while (offset < trackEnd) {
      // Read Delta Time (Variable Length Quantity)
      let deltaTime = 0;
      let byte = data.getUint8(offset++);
      deltaTime = byte & 0x7F;
      while (byte & 0x80) {
        byte = data.getUint8(offset++);
        deltaTime = (deltaTime << 7) | (byte & 0x7F);
      }

      currentTime += deltaTime;

      // Read Event Type
      let eventType = data.getUint8(offset);

      if (eventType & 0x80) {
        runningStatus = eventType;
        offset++;
      } else {
        eventType = runningStatus;
      }

      const channel = eventType & 0x0F;
      const type = eventType & 0xF0;

      if (type === 0x80 || type === 0x90) { // Note Off (0x80) or Note On (0x90)
        const note = data.getUint8(offset++);
        const velocity = data.getUint8(offset++);

        if (type === 0x90 && velocity > 0) {
          // Note On
          activeNotes[note] = currentTime;
        } else {
          // Note Off (or Note On with vel 0)
          if (activeNotes[note] !== undefined) {
            const startTick = activeNotes[note];
            const durationTicks = currentTime - startTick;

            // Convert ticks to seconds
            // Time = (ticks * microsecondsPerBeat) / timeDivision / 1000000
            const startSeconds = (startTick * microsecondsPerBeat) / (timeDivision * 1000000);
            const durationSeconds = (durationTicks * microsecondsPerBeat) / (timeDivision * 1000000);

            notes.push({
              id: Math.random().toString(36).substr(2, 9),
              midi: note,
              startTime: startSeconds,
              duration: durationSeconds,
              lyric: "la" // Default lyric
            });

            delete activeNotes[note];
          }
        }
      } else if (type === 0xFF) { // Meta Event
        const metaType = data.getUint8(offset++);
        // Read VLQ Length
        let len = 0;
        let b = data.getUint8(offset++);
        len = b & 0x7F;
        while (b & 0x80) {
            b = data.getUint8(offset++);
            len = (len << 7) | (b & 0x7F);
        }

        if (metaType === 0x51) { // Set Tempo
            const t1 = data.getUint8(offset);
            const t2 = data.getUint8(offset+1);
            const t3 = data.getUint8(offset+2);
            microsecondsPerBeat = (t1 << 16) | (t2 << 8) | t3;
        }

        offset += len;
      } else if (type === 0xC0 || type === 0xD0) {
        offset += 1; // Program Change or Channel Pressure (1 byte data)
      } else if (type === 0xB0 || type === 0xE0 || type === 0xA0) {
        offset += 2; // Control Change, Pitch Bend, Poly Pressure (2 bytes data)
      } else if (type === 0xF0) { // Sysex
          // Skip until F7
          while (offset < trackEnd) {
             if (data.getUint8(offset++) === 0xF7) break;
          }
      }
    }
  }

  return notes.sort((a, b) => a.startTime - b.startTime);
};

function getText(data: DataView, offset: number, length: number) {
  let str = '';
  for (let i = 0; i < length; i++) {
    str += String.fromCharCode(data.getUint8(offset + i));
  }
  return str;
}

import { 
  VocalPreset, VocalMode, VocalParams, SequencerNote
} from '../types';

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
  'F#': 23.12, 'G': 24.50, 'G#': 25.96, 'A': 27.50, 'A#': 29.14, 'B': 30.87
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

export const midiToFreq = (midi: number): number => {
  return 440 * Math.pow(2, (midi - 69) / 12);
};

// Helper: Convert AudioBuffer to WAV Blob
export const bufferToWav = (buffer: AudioBuffer): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  // write fmt sub-chunk
  setUint32(0x20746d66); // "fmt "
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(buffer.sampleRate);
  setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this parser)

  // write data sub-chunk
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      // clamp
      sample = Math.max(-1, Math.min(1, channels[i][pos])); 
      // scale to 16-bit signed int
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
      view.setInt16(44 + offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

/**
 * Convolution Reverb Generator (Space/Resonance Model)
 */
export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  // 1. Generate Impulse Response (Exponential Decay Noise)
  // Model: y(t) = Noise(t) * e^(-t / T)
  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    // White noise * exponential decay
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  // 2. Convolve
  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

