import React, { useRef, useState, useEffect } from 'react';
import { SequencerNote } from '../types';

interface PianoRollProps {
  notes: SequencerNote[];
  setNotes: React.Dispatch<React.SetStateAction<SequencerNote[]>>;
  duration: number; // Total seq duration
}

const NOTE_HEIGHT = 24; // px
const PIXELS_PER_SECOND = 100; // Zoom level
const MIDI_MIN = 48; // C3
const MIDI_MAX = 84; // C6

export const PianoRoll: React.FC<PianoRollProps> = ({ notes, setNotes, duration }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);

  // Resizing State
  const resizingNoteRef = useRef<{ id: string, startX: number, initialDuration: number } | null>(null);

  // Generate grid background keys
  const keys = [];
  for (let i = MIDI_MAX; i >= MIDI_MIN; i--) {
    const isBlack = [1, 3, 6, 8, 10].includes(i % 12);
    keys.push({ midi: i, isBlack });
  }

  // --- Handlers ---

  const handleGridClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (resizingNoteRef.current) return; // Don't create note if resizing
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left + containerRef.current.scrollLeft;
    const y = e.clientY - rect.top + containerRef.current.scrollTop;

    const clickTime = Math.max(0, x / PIXELS_PER_SECOND);
    const clickMidi = MIDI_MAX - Math.floor(y / NOTE_HEIGHT);

    // Create new note
    const newNote: SequencerNote = {
      id: Math.random().toString(36).substr(2, 9),
      midi: clickMidi,
      startTime: Math.floor(clickTime * 4) / 4, // Snap to 0.25s
      duration: 0.5,
      lyric: 'la'
    };

    setNotes([...notes, newNote]);
    setSelectedNoteId(newNote.id);
  };

  const handleNoteClick = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (resizingNoteRef.current) return;
    setSelectedNoteId(id);
  };

  const updateNoteLyric = (id: string, newLyric: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, lyric: newLyric } : n));
  };

  const deleteNote = (id: string) => {
      setNotes(notes.filter(n => n.id !== id));
      setSelectedNoteId(null);
  };

  // --- Resizing Logic ---

  const handleResizeStart = (e: React.MouseEvent, note: SequencerNote) => {
    e.stopPropagation();
    e.preventDefault();
    resizingNoteRef.current = {
        id: note.id,
        startX: e.clientX,
        initialDuration: note.duration
    };
    setSelectedNoteId(note.id);

    // Add global listeners
    window.addEventListener('mousemove', handleResizeMove);
    window.addEventListener('mouseup', handleResizeEnd);
  };

  const handleResizeMove = (e: MouseEvent) => {
    if (!resizingNoteRef.current) return;

    const { id, startX, initialDuration } = resizingNoteRef.current;
    const deltaPixels = e.clientX - startX;
    const deltaSeconds = deltaPixels / PIXELS_PER_SECOND;

    const newDuration = Math.max(0.1, Math.round((initialDuration + deltaSeconds) * 100) / 100); // Min 0.1s

    setNotes(prev => prev.map(n => n.id === id ? { ...n, duration: newDuration } : n));
  };

  const handleResizeEnd = () => {
    resizingNoteRef.current = null;
    window.removeEventListener('mousemove', handleResizeMove);
    window.removeEventListener('mouseup', handleResizeEnd);
  };

  useEffect(() => {
    return () => {
        window.removeEventListener('mousemove', handleResizeMove);
        window.removeEventListener('mouseup', handleResizeEnd);
    }
  }, []);

  return (
    <div className="flex flex-col h-96 bg-gray-900 border border-synth-grid rounded-xl overflow-hidden select-none">

      {/* Editor Toolbar */}
      <div className="bg-synth-panel p-2 flex gap-4 items-center border-b border-synth-grid h-12">
        <span className="text-xs font-bold text-synth-accent">PIANO ROLL</span>
        {selectedNoteId ? (
            <div className="flex items-center gap-2 flex-1 animate-in fade-in duration-200">
                <input 
                    type="text" 
                    className="bg-synth-dark border border-synth-grid rounded px-2 py-1 text-xs text-white w-24 focus:border-synth-pop outline-none"
                    value={notes.find(n => n.id === selectedNoteId)?.lyric || ''}
                    onChange={(e) => updateNoteLyric(selectedNoteId, e.target.value)}
                    placeholder="Lyric..."
                />
                <button 
                    onClick={() => deleteNote(selectedNoteId)}
                    className="text-[10px] bg-red-500/20 text-red-400 px-2 py-1.5 rounded hover:bg-red-500 hover:text-white font-bold transition-colors"
                >
                    DELETE
                </button>
                <span className="text-[9px] text-slate-500 ml-2">
                    Dur: {notes.find(n => n.id === selectedNoteId)?.duration.toFixed(2)}s
                </span>
            </div>
        ) : (
            <span className="text-[10px] text-slate-500">Tap grid to add. Drag right edge to resize.</span>
        )}
      </div>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Piano Keys Column */}
        <div className="w-12 bg-white flex-shrink-0 flex flex-col overflow-hidden relative z-20 shadow-lg">
           <div className="absolute top-0 left-0 w-full" style={{ transform: `translateY(-${containerRef.current?.scrollTop || 0}px)` }}>
               {keys.map(k => (
                   <div 
                    key={k.midi} 
                    className={`h-[24px] border-b border-gray-300 flex items-center justify-end pr-1 text-[9px] font-bold ${k.isBlack ? 'bg-black text-white' : 'bg-white text-black'}`}
                   >
                       {k.midi % 12 === 0 ? `C${Math.floor(k.midi/12)-1}` : ''}
                   </div>
               ))}
           </div>
        </div>

        {/* Grid Scroll Area */}
        <div 
            ref={containerRef}
            className="flex-1 overflow-auto bg-synth-dark relative cursor-crosshair"
            onClick={handleGridClick}
        >
            <div 
                className="relative" 
                style={{ width: `${Math.max(duration * PIXELS_PER_SECOND, 600)}px`, height: `${keys.length * NOTE_HEIGHT}px` }}
            >
                {/* Grid Lines */}
                {/* Horizontal */}
                {keys.map((k, i) => (
                    <div 
                        key={k.midi} 
                        className={`absolute w-full h-px bg-synth-grid/20`} 
                        style={{ top: i * NOTE_HEIGHT }}
                    />
                ))}
                {/* Vertical (Seconds) */}
                {Array.from({ length: Math.ceil(duration) + 1 }).map((_, i) => (
                    <div 
                        key={i} 
                        className="absolute h-full w-px bg-synth-grid/50" 
                        style={{ left: i * PIXELS_PER_SECOND }}
                    >
                         <span className="absolute top-0 left-1 text-[9px] text-slate-600">{i}s</span>
                    </div>
                ))}

                {/* Notes */}
                {notes.map(note => {
                    // Calculate Position
                    // Y = (MAX - note.midi) * HEIGHT
                    const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                    const left = note.startTime * PIXELS_PER_SECOND;
                    const width = note.duration * PIXELS_PER_SECOND;
                    const isSelected = selectedNoteId === note.id;

                    return (
                        <div
                            key={note.id}
                            onMouseDown={(e) => handleNoteClick(e, note.id)}
                            className={`absolute rounded-sm border text-[10px] flex items-center pl-1 overflow-hidden whitespace-nowrap shadow-sm transition-colors group
                                ${isSelected 
                                    ? 'bg-synth-pop border-white text-white z-10' 
                                    : 'bg-synth-accent/90 border-synth-accent text-synth-dark hover:bg-synth-accent'}`
                            }
                            style={{
                                top: `${top + 1}px`,
                                left: `${left}px`,
                                width: `${Math.max(width - 1, 5)}px`, // minimum visual width
                                height: `${NOTE_HEIGHT - 2}px`
                            }}
                        >
                            <span className="truncate w-full pointer-events-none">{note.lyric}</span>

                            {/* Resize Handle */}
                            <div 
                                className={`absolute right-0 top-0 bottom-0 w-3 cursor-ew-resize z-20 flex items-center justify-center
                                    ${isSelected ? 'bg-white/30 hover:bg-white/50' : 'bg-black/10 hover:bg-black/30 opacity-0 group-hover:opacity-100'}`}
                                onMouseDown={(e) => handleResizeStart(e, note)}
                            >
                                <div className="w-0.5 h-3 bg-white/50 rounded-full" />
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
      </div>
    </div>
  );
};

import { 
  VocalPreset, VocalMode, VocalParams, SequencerNote
} from '../types';

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
  'F#': 23.12, 'G': 24.50, 'G#': 25.96, 'A': 27.50, 'A#': 29.14, 'B': 30.87
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

export const midiToFreq = (midi: number): number => {
  return 440 * Math.pow(2, (midi - 69) / 12);
};

// Helper: Convert AudioBuffer to WAV Blob
export const bufferToWav = (buffer: AudioBuffer): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  // write fmt sub-chunk
  setUint32(0x20746d66); // "fmt "
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(buffer.sampleRate);
  setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this parser)

  // write data sub-chunk
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      // clamp
      sample = Math.max(-1, Math.min(1, channels[i][pos])); 
      // scale to 16-bit signed int
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
      view.setInt16(44 + offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

/**
 * Convolution Reverb Generator (Space/Resonance Model)
 */
export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  // 1. Generate Impulse Response (Exponential Decay Noise)
  // Model: y(t) = Noise(t) * e^(-t / T)
  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    // White noise * exponential decay
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  // 2. Convolve
  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

// --- VOCAL SYNTHESIS ENGINE (PT-BR) ---

// PHONETIC DEFINITIONS
interface PhonemeDef {
  formants: number[];
  gain: number;
  noise: number; // 0 to 1 mix of noise
  noiseType?: 'white' | 'pink' | 'highpass';
  durationScale: number; // 1.0 = standard, 0.5 = fast (consonant)
}

// 1. Dictionary of Phonemes (Oral, Nasal, Consonant Approximations)
