  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedBuffer(null);

    setTimeout(async () => {
      try {
        const sampleRate = 44100;
        // In Sequencer mode, duration depends on the last note
        let duration = globalParams.duration;
        if (mode === 'SEQUENCER' && notes.length > 0) {
            const lastNote = notes.reduce((prev, curr) => (curr.startTime + curr.duration > prev.startTime + prev.duration) ? curr : prev);
            duration = Math.max(globalParams.duration, lastNote.startTime + lastNote.duration + 1.0); // Add tail
        }

        const ctx = new OfflineAudioContext(1, sampleRate * duration, sampleRate);

        let buffer: AudioBuffer;

        if (mode === 'LIVE') {
            const baseFreq = getFrequency(selectedNote, selectedOctave);
            buffer = await renderVocals(ctx, vocalParams, duration, baseFreq);
        } else {
            // Sequencer Mode
            buffer = await renderSequence(ctx, notes, vocalParams);
        }

        // Apply Global Reverb
        if (globalParams.reverbMix > 0) {
            buffer = await applyReverb(ctx, buffer, globalParams.reverbMix, globalParams.reverbDecay);
        }

        setGeneratedBuffer(buffer);
        drawWaveform(buffer);
      } catch (e) {
        console.error(e);
        alert("Error generating audio");
      } finally {
        setIsGenerating(false);
      }
    }, 50);
  };

  const handleMidiUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                const parsedNotes = parseMidiFile(ev.target.result as ArrayBuffer);
                setNotes(parsedNotes);
                setMode('SEQUENCER'); // Auto switch
                alert(`Imported ${parsedNotes.length} notes!`);
            } catch (err) {
                console.error(err);
                alert("Failed to parse MIDI file.");
            }
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportJson = () => {
    const data = {
        version: 1,
        timestamp: Date.now(),
        notes: notes,
        vocalParams: vocalParams,
        globalParams: globalParams
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `project_${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                const data = JSON.parse(ev.target.result as string);
