                if (data.vocalParams) setVocalParams(data.vocalParams);
                if (data.globalParams) setGlobalParams(data.globalParams);
                setMode('SEQUENCER');
                alert("Project loaded!");
            } catch (err) {
                console.error(err);
                alert("Invalid project file.");
            }
        }
    };
    reader.readAsText(file);
  };


  const handlePlay = () => {
    if (!generatedBuffer) return;

    if (!audioContextRef.current) {
      audioContextRef.current = new AudioContext();
    }

    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') ctx.resume();

    const source = ctx.createBufferSource();
    source.buffer = generatedBuffer;
    source.connect(ctx.destination);

    source.onended = () => setIsPlaying(false);

    setIsPlaying(true);
    source.start();
  };

  const handleDownload = () => {
    if (!generatedBuffer) return;
    const blob = bufferToWav(generatedBuffer);
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;

    const name = `vocalstudio_${mode.toLowerCase()}_${Date.now()}.wav`;

    a.download = name;
    document.body.appendChild(a);
    a.click();

    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  };

  const drawWaveform = (buffer: AudioBuffer) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp = height / 2;

    ctx.clearRect(0, 0, width, height);
    ctx.beginPath();
    ctx.moveTo(0, amp);

    // Draw visual styling
    ctx.strokeStyle = '#38bdf8'; // Sky blue
    ctx.lineWidth = 2;

    for (let i = 0; i < width; i++) {
      let min = 1.0;
      let max = -1.0;
      for (let j = 0; j < step; j++) {
        const datum = data[(i * step) + j];
        if (datum < min) min = datum;
        if (datum > max) max = datum;
      }
      ctx.lineTo(i, (1 + min) * amp);
      ctx.lineTo(i, (1 + max) * amp);
    }

    ctx.stroke();
  };

  return (
    <div className="min-h-screen bg-synth-dark text-slate-200 pb-40 font-sans selection:bg-synth-pop selection:text-white">

      {/* Header */}
      <header className="p-4 bg-synth-dark/90 backdrop-blur sticky top-0 z-10 border-b border-synth-grid flex justify-between items-center shadow-lg">
