            <Mic size={24} className="text-synth-accent" />
            VocalStudio
          </h1>
          <p className="text-[10px] text-slate-500 tracking-wide font-mono">DSP VOCAL WORKSTATION</p>
        </div>

        {/* Mode Switcher */}
        <div className="flex bg-synth-panel rounded-lg p-1 border border-synth-grid gap-1">
            <button
                onClick={() => setMode('LIVE')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'LIVE' ? 'bg-synth-accent text-synth-dark' : 'text-slate-500'}`}
            >
                <Music size={12} />
                LIVE
            </button>
            <button
                onClick={() => setMode('SEQUENCER')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'SEQUENCER' ? 'bg-synth-pop text-white' : 'text-slate-500'}`}
            >
                <Piano size={12} />
                SEQ
            </button>
        </div>
      </header>

      <main className="p-4 max-w-lg mx-auto w-full space-y-5">

        {/* Visualization Area */}
        <div className="bg-black/40 rounded-2xl border border-synth-grid p-4 h-24 flex items-center justify-center relative overflow-hidden group">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-synth-panel/50 to-transparent opacity-50" />
          <canvas 
            ref={canvasRef} 
            width={600} 
            height={200} 
            className="w-full h-full relative z-10 opacity-90"
          />
        </div>

        {/* --- SEQUENCER MODE UI --- */}
        {mode === 'SEQUENCER' && (
             <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex justify-between items-center">
                    <h2 className="text-sm font-bold text-synth-pop flex items-center gap-2">
                        <Piano size={16} />
                        VOCAL PIANO ROLL
                    </h2>
                    <div className="flex gap-2">
                         <input 
                            type="file" 
                            accept=".mid,.midi" 
                            className="hidden" 
                            ref={fileInputRef}
                            onChange={handleMidiUpload}
                        />
                         <input 
                            type="file" 
                            accept=".json" 
                            className="hidden" 
                            ref={jsonInputRef}
                            onChange={handleImportJson}
                        />
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700"
                        >
                            <Upload size={10} />
                            MIDI
                        </button>
                    </div>
                </div>

                <PianoRoll 
                    notes={notes}
                    setNotes={setNotes}
                    duration={globalParams.duration}
                />

                <div className="text-[10px] text-slate-500 text-center">
                    Tap to add note (la). Tap note to select. Edit lyric above.
                </div>
             </div>
        )}

        {/* --- LIVE MODE UI --- */}
        {mode === 'LIVE' && (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="bg-synth-panel p-4 rounded-xl border border-synth-grid flex justify-between items-center">
                    <span className="text-xs font-bold text-synth-accent uppercase">Base Pitch</span>
                    <div className="flex gap-2 items-center bg-synth-dark rounded-lg p-1 border border-synth-grid/50">
