                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Export Project"
                >
                    <Save size={16} />
                </button>
                 <button
                    onClick={() => jsonInputRef.current?.click()}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Import Project"
                >
                    <FileJson size={16} />
                </button>
            </div>

          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="flex-1 bg-synth-panel hover:bg-slate-700 text-white font-bold py-2 px-4 rounded-2xl border border-synth-grid shadow-lg active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
          >
            <Activity className={isGenerating ? "animate-spin" : ""} size={20} />
            <span className="text-[10px] uppercase tracking-wider">{isGenerating ? "Wait..." : (mode === 'SEQUENCER' ? "RENDER SEQ" : "RENDER")}</span>
          </button>

          {generatedBuffer && (
            <>
              <button
                onClick={handlePlay}
                className={`w-14 bg-synth-accent text-synth-dark font-bold rounded-2xl flex items-center justify-center shadow-[0_0_15px_rgba(56,189,248,0.3)] active:scale-95 transition-transform ${isPlaying ? 'opacity-80' : ''}`}
              >
                <Play fill={isPlaying ? "currentColor" : "none"} size={24} />
              </button>

              <button
                onClick={handleDownload}
                className="flex-1 bg-synth-pop hover:bg-pink-500 text-white font-bold py-2 px-4 rounded-2xl shadow-[0_0_15px_rgba(244,114,182,0.3)] active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
              >
                <Download size={20} />
                 <span className="text-[10px] uppercase tracking-wider">SAVE WAV</span>
              </button>
            </>
          )}
        </div>
      </footer>

    </div>
  );
};

