import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  VowelType, 
  VocalMode, 
  VocalPreset,
  VocalParams, 
  GlobalParams,
  SequencerNote
} from './types';
import { 
  renderVocals, 
  renderSequence,
  applyReverb,
  bufferToWav,
