        let duration = globalParams.duration;
        if (mode === 'SEQUENCER' && notes.length > 0) {
            const lastNote = notes.reduce((prev, curr) => (curr.startTime + curr.duration > prev.startTime + prev.duration) ? curr : prev);
            duration = Math.max(globalParams.duration, lastNote.startTime + lastNote.duration + 1.0); // Add tail
        }

        const ctx = new OfflineAudioContext(1, sampleRate * duration, sampleRate);

        let buffer: AudioBuffer;

        if (mode === 'LIVE') {
            const baseFreq = getFrequency(selectedNote, selectedOctave);
            buffer = await renderVocals(ctx, vocalParams, duration, baseFreq);
        } else {
            // Sequencer Mode
            buffer = await renderSequence(ctx, notes, vocalParams);
        }

