                        className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-lg font-mono tracking-widest text-white focus:border-synth-pop outline-none h-24"
                        placeholder="Type phonemes..."
                    />
                </div>
            </div>
        )}

        {/* Global Config (Shared) */}
        <div className="bg-synth-panel/30 p-4 rounded-xl border border-synth-grid/50">
          <div className="flex items-center gap-2 mb-3 text-synth-accent">
            <Settings size={16} />
            <span className="text-xs font-bold uppercase">Voice Parameters</span>
          </div>

           <div className="mb-4">
              <select
                value={vocalParams.preset}
                onChange={(e) => setVocalParams(p => ({ ...p, preset: e.target.value as VocalPreset }))}
                className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-sm text-white focus:border-synth-pop outline-none appearance-none"
              >
                {Object.values(VocalPreset).map(preset => (
                  <option key={preset} value={preset}>{preset}</option>
