export default App;

import React, { useRef, useState, useEffect } from 'react';
import { SequencerNote } from '../types';
import { Pencil, Eraser, Undo, Redo, Trash2, MousePointer2, Hand, ArrowLeftRight } from 'lucide-react';

interface PianoRollProps {
  notes: SequencerNote[];
  setNotes: React.Dispatch<React.SetStateAction<SequencerNote[]>>;
  durationBeats: number; // Total beats
  onUndo: () => void;
  onRedo: () => void;
  addToHistory: () => void;
  canUndo: boolean;
  canRedo: boolean;
}

const NOTE_HEIGHT = 20; // Compact height
const PIXELS_PER_BEAT = 60; // Zoom level
const MIDI_MIN = 36; // C2
const MIDI_MAX = 84; // C6
const TOTAL_KEYS = MIDI_MAX - MIDI_MIN + 1;

type ToolType = 'POINTER' | 'PENCIL' | 'ERASER' | 'HAND';

export const PianoRoll: React.FC<PianoRollProps> = ({ 
  notes, setNotes, durationBeats, onUndo, onRedo, addToHistory, canUndo, canRedo 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>('POINTER');

  // Interaction State
  const dragRef = useRef<{ 
    type: 'MOVE' | 'RESIZE' | 'PAN' | 'CREATE', 
    noteId?: string, 
    startX: number, 
    startY: number, 
    initialStart?: number, 
    initialMidi?: number, 
    initialDuration?: number,
    initialScrollX?: number,
    initialScrollY?: number
  } | null>(null);

  // Generate Keys Data
  const keys = [];
  for (let i = MIDI_MAX; i >= MIDI_MIN; i--) {
    const isBlack = [1, 3, 6, 8, 10].includes(i % 12);
    keys.push({ midi: i, isBlack, label: i % 12 === 0 ? `C${(i/12)-1}` : '' });
  }

  // --- Helpers ---
  const getNoteAt = (midi: number, beat: number) => {
    return notes.find(n => 
      n.midi === midi && 
      beat >= n.startTime && 
      beat < n.startTime + n.duration
    );
  };

  const snapToGrid = (val: number, step = 0.25) => {
      return Math.round(val / step) * step;
  };

  // --- Handlers ---

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    // Coordinates relative to the scroll container content
    // We must account for the sticky header (keys width)
    const KEYS_WIDTH = 48;
    const rawX = e.clientX - rect.left;
    const scrollX = containerRef.current.scrollLeft;
    const scrollY = containerRef.current.scrollTop;

    // Effective Grid Coordinates
    const gridX = rawX + scrollX - KEYS_WIDTH;
    const gridY = e.clientY - rect.top + scrollY;

    // Check bounds (don't click on keys column)
    if (rawX < KEYS_WIDTH && tool !== 'HAND') return;

    const beat = Math.max(0, gridX / PIXELS_PER_BEAT);
    const midi = MIDI_MAX - Math.floor(gridY / NOTE_HEIGHT);

    // --- TOOL LOGIC ---

    if (tool === 'HAND' || (e.button === 1)) { // Middle click or Hand tool
        dragRef.current = {
            type: 'PAN',
            startX: e.clientX,
            startY: e.clientY,
            initialScrollX: scrollX,
            initialScrollY: scrollY
        };
        return;
    }

    if (tool === 'ERASER') {
        const clickedNote = getNoteAt(midi, beat);
        if (clickedNote) {
            addToHistory();
            setNotes(prev => prev.filter(n => n.id !== clickedNote.id));
        }
        return;
    }

    if (tool === 'PENCIL') {
        const existing = getNoteAt(midi, beat);
        if (existing) {
            setSelectedNoteId(existing.id);
        } else {
            // Create
            addToHistory();
            const newNote: SequencerNote = {
                id: Math.random().toString(36).substr(2, 9),
                midi: midi,
                startTime: Math.floor(beat * 4) / 4, // Snap 1/4
                duration: 1.0,
                lyric: 'la'
            };
            setNotes(prev => [...prev, newNote]);
            setSelectedNoteId(newNote.id);
            // Immediately start moving/resizing? Maybe just creation for now.
        }
        return;
    }

    if (tool === 'POINTER') {
        // We handle Note Click separately in onMouseDown on the Note element itself usually,
        // but if we clicked Empty Space, Deselect.
        const existing = getNoteAt(midi, beat);
        if (!existing) {
            setSelectedNoteId(null);
        }
    }
  };

  const handleNoteMouseDown = (e: React.MouseEvent, note: SequencerNote, type: 'MOVE' | 'RESIZE') => {
    e.stopPropagation();
    if (tool !== 'POINTER') return; // Only pointer modifies existing notes logic here

    addToHistory();
    setSelectedNoteId(note.id);

    dragRef.current = {
        type: type,
        noteId: note.id,
        startX: e.clientX,
        startY: e.clientY,
        initialStart: note.startTime,
        initialMidi: note.midi,
        initialDuration: note.duration
    };
  };

  const handleGlobalMove = (e: MouseEvent) => {
    if (!dragRef.current) return;
    const { type, startX, startY, noteId, initialStart, initialMidi, initialDuration, initialScrollX, initialScrollY } = dragRef.current;

    if (type === 'PAN' && containerRef.current) {
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        containerRef.current.scrollLeft = (initialScrollX || 0) - dx;
        containerRef.current.scrollTop = (initialScrollY || 0) - dy;
        return;
    }

    const deltaX = (e.clientX - startX) / PIXELS_PER_BEAT;
    const deltaY = (e.clientY - startY) / NOTE_HEIGHT;

    if (type === 'MOVE') {
        const newStart = Math.max(0, snapToGrid((initialStart || 0) + deltaX));
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, Math.round((initialMidi || 0) - deltaY)));

        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, startTime: newStart, midi: newMidi } : n));
    }

    if (type === 'RESIZE') {
        const newDur = Math.max(0.125, snapToGrid((initialDuration || 0) + deltaX, 0.125));
        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, duration: newDur } : n));
    }
  };

  const handleGlobalUp = () => {
    dragRef.current = null;
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleGlobalMove);
    window.addEventListener('mouseup', handleGlobalUp);
    return () => {
        window.removeEventListener('mousemove', handleGlobalMove);
        window.removeEventListener('mouseup', handleGlobalUp);
    };
  }, []);

  const updateNoteLyric = (id: string, newLyric: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, lyric: newLyric } : n));
  };

  const updateNoteDuration = (id: string, newDuration: number) => {
    if (isNaN(newDuration)) return;
    const d = Math.max(0.125, newDuration);
    setNotes(notes.map(n => n.id === id ? { ...n, duration: d } : n));
  };

  const deleteNote = (id: string) => {
      addToHistory();
      setNotes(notes.filter(n => n.id !== id));
      setSelectedNoteId(null);
  };

  return (
    <div className="flex flex-col h-[500px] bg-gray-900 border border-synth-grid rounded-xl overflow-hidden select-none shadow-2xl">

      {/* Toolbar */}
      <div className="bg-synth-panel p-2 flex gap-2 items-center border-b border-synth-grid h-12 shrink-0 z-30 relative">
        <span className="text-xs font-bold text-synth-accent mr-2 hidden sm:block">TOOLS</span>

        <div className="flex bg-synth-dark rounded-lg p-0.5 border border-synth-grid">
            <button onClick={() => setTool('POINTER')} className={`p-1.5 rounded-md ${tool === 'POINTER' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Select/Move/Resize">
                <MousePointer2 size={14} />
            </button>
            <button onClick={() => setTool('PENCIL')} className={`p-1.5 rounded-md ${tool === 'PENCIL' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Create">
                <Pencil size={14} />
            </button>
            <button onClick={() => setTool('HAND')} className={`p-1.5 rounded-md ${tool === 'HAND' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Navigate">
                <Hand size={14} />
            </button>
             <button onClick={() => setTool('ERASER')} className={`p-1.5 rounded-md ${tool === 'ERASER' ? 'bg-synth-pop text-white' : 'text-slate-400'}`} title="Erase">
                <Eraser size={14} />
            </button>
        </div>

        <div className="w-px h-6 bg-synth-grid mx-1"></div>

        <div className="flex gap-1">
             <button onClick={onUndo} disabled={!canUndo} className={`p-1.5 rounded-md ${canUndo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Undo size={14} /></button>
            <button onClick={onRedo} disabled={!canRedo} className={`p-1.5 rounded-md ${canRedo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Redo size={14} /></button>
        </div>

        {selectedNoteId && (
            <div className="flex items-center gap-2 ml-auto animate-in fade-in duration-200 border-l border-synth-grid pl-2">
                <input 
                    type="text" 
                    className="bg-synth-dark border border-synth-grid rounded px-2 py-1 text-xs text-white w-20 focus:border-synth-pop outline-none text-center"
                    value={notes.find(n => n.id === selectedNoteId)?.lyric || ''}
                    onChange={(e) => updateNoteLyric(selectedNoteId, e.target.value)}
                    onFocus={addToHistory}
                    placeholder="Lyric"
                    title="Lyric"
                />

                {/* Manual Duration Control */}
                <div className="flex items-center bg-synth-dark border border-synth-grid rounded px-1" title="Duration (Beats)">
                    <ArrowLeftRight size={10} className="text-slate-500 mr-1" />
                    <input 
                        type="number"
                        step={0.25}
                        min={0.125}
                        className="bg-transparent text-xs text-white w-10 focus:outline-none text-center font-mono appearance-none"
                        value={notes.find(n => n.id === selectedNoteId)?.duration || 0}
                        onChange={(e) => updateNoteDuration(selectedNoteId, parseFloat(e.target.value))}
                        onFocus={addToHistory}
                    />
                </div>

                <button onClick={() => deleteNote(selectedNoteId)} className="p-1.5 text-red-400 hover:bg-red-500/20 rounded"><Trash2 size={14} /></button>
            </div>
        )}
      </div>

      {/* Main Scroll Container */}
      <div 
        ref={containerRef}
        className={`flex-1 overflow-auto bg-synth-dark relative scroll-smooth ${tool === 'HAND' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default'}`}
        onMouseDown={handleMouseDown}
      >
        <div 
            className="relative flex" 
            style={{ 
                height: `${TOTAL_KEYS * NOTE_HEIGHT}px`, 
                width: `${Math.max(durationBeats * PIXELS_PER_BEAT + 48, 1000)}px` // +48 for keys width
            }}
        >

            {/* STICKY KEYS COLUMN */}
            <div className="w-12 sticky left-0 z-20 bg-white border-r border-gray-300 flex flex-col shrink-0 shadow-lg">
                {keys.map((k) => (
                    <div 
                        key={k.midi} 
                        className={`h-[20px] border-b border-gray-300 text-[9px] flex items-center justify-end pr-1 font-bold ${k.isBlack ? 'bg-black text-white' : 'bg-white text-gray-800'}`}
                        style={{ height: NOTE_HEIGHT }}
                    >
                        {k.label}
                    </div>
                ))}
            </div>

            {/* GRID AREA */}
            <div className="flex-1 relative">

                {/* Background Rows */}
                {keys.map((k, i) => (
                    <div 
                        key={k.midi}
                        className={`absolute w-full border-b border-synth-grid/10 ${k.isBlack ? 'bg-synth-grid/5' : ''}`}
                        style={{ top: i * NOTE_HEIGHT, height: NOTE_HEIGHT }}
                    />
                ))}

                {/* Vertical Beat Lines */}
                {Array.from({ length: Math.ceil(durationBeats) + 1 }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`absolute top-0 bottom-0 w-px ${i % 4 === 0 ? 'bg-synth-grid/60' : 'bg-synth-grid/20'}`}
                        style={{ left: i * PIXELS_PER_BEAT }}
                    >
                        {i % 4 === 0 && <span className="absolute top-0 left-1 text-[8px] text-slate-500 font-mono">{i}</span>}
                    </div>
                ))}

                {/* NOTES */}
                {notes.map(note => {
                    const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                    const left = note.startTime * PIXELS_PER_BEAT;
                    const width = note.duration * PIXELS_PER_BEAT;
                    const isSelected = selectedNoteId === note.id;

                    return (
                        <div
                            key={note.id}
                            onMouseDown={(e) => handleNoteMouseDown(e, note, 'MOVE')}
                            className={`absolute rounded-sm border text-[10px] flex items-center pl-1 overflow-hidden shadow-sm group
                                ${isSelected 
                                    ? 'bg-synth-pop border-white text-white z-10 shadow-lg ring-1 ring-white' 
                                    : 'bg-synth-accent/90 border-synth-accent text-synth-dark hover:bg-synth-accent'
                                }`}
                            style={{
                                top: top + 1,
                                left: left,
                                width: Math.max(width - 1, 4),
                                height: NOTE_HEIGHT - 2,
                                cursor: tool === 'POINTER' ? 'move' : 'default'
                            }}
                        >
                            <span className="truncate w-full pointer-events-none select-none">{note.lyric}</span>

                            {/* Resize Handle */}
                            {tool === 'POINTER' && (
                                <div 
                                    className={`absolute right-0 top-0 bottom-0 w-4 cursor-ew-resize z-20 flex items-center justify-center opacity-0 hover:opacity-100 ${isSelected ? 'opacity-100' : ''}`}
                                    onMouseDown={(e) => handleNoteMouseDown(e, note, 'RESIZE')}
                                >
                                    <div className="w-1 h-3 bg-white/60 rounded-full" />
                                </div>
                            )}
                        </div>
                    );
                })}

            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { SequencerNote } from '../types';
import { 
  Pencil, Eraser, Undo, Redo, Trash2, MousePointer2, Hand, 
  ArrowLeftRight, ArrowUp, ArrowDown, ArrowLeft, ArrowRight 
} from 'lucide-react';

interface PianoRollProps {
  notes: SequencerNote[];
  setNotes: React.Dispatch<React.SetStateAction<SequencerNote[]>>;
  durationBeats: number; // Total beats
  onUndo: () => void;
  onRedo: () => void;
  addToHistory: () => void;
  canUndo: boolean;
  canRedo: boolean;
}

const NOTE_HEIGHT = 20; // Compact height
const PIXELS_PER_BEAT = 60; // Zoom level
const MIDI_MIN = 36; // C2
const MIDI_MAX = 84; // C6
const TOTAL_KEYS = MIDI_MAX - MIDI_MIN + 1;

type ToolType = 'POINTER' | 'PENCIL' | 'ERASER' | 'HAND';

export const PianoRoll: React.FC<PianoRollProps> = ({ 
  notes, setNotes, durationBeats, onUndo, onRedo, addToHistory, canUndo, canRedo 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>('POINTER');

  // Interaction State
  const dragRef = useRef<{ 
    type: 'MOVE' | 'RESIZE' | 'PAN' | 'CREATE', 
    noteId?: string, 
    startX: number, 
    startY: number, 
    initialStart?: number, 
    initialMidi?: number, 
    initialDuration?: number,
    initialScrollX?: number,
    initialScrollY?: number
  } | null>(null);

  // Generate Keys Data
  const keys = [];
  for (let i = MIDI_MAX; i >= MIDI_MIN; i--) {
    const isBlack = [1, 3, 6, 8, 10].includes(i % 12);
    keys.push({ midi: i, isBlack, label: i % 12 === 0 ? `C${(i/12)-1}` : '' });
  }

  // --- Helpers ---
  const getNoteAt = (midi: number, beat: number) => {
    return notes.find(n => 
      n.midi === midi && 
      beat >= n.startTime && 
      beat < n.startTime + n.duration
    );
  };

  const snapToGrid = (val: number, step = 0.25) => {
      return Math.round(val / step) * step;
  };

  // --- Handlers ---

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    // Coordinates relative to the scroll container content
    // We must account for the sticky header (keys width)
    const KEYS_WIDTH = 48;
    const rawX = e.clientX - rect.left;
    const scrollX = containerRef.current.scrollLeft;
    const scrollY = containerRef.current.scrollTop;

    // Effective Grid Coordinates
    const gridX = rawX + scrollX - KEYS_WIDTH;
    const gridY = e.clientY - rect.top + scrollY;

    // Check bounds (don't click on keys column)
    if (rawX < KEYS_WIDTH && tool !== 'HAND') return;

    const beat = Math.max(0, gridX / PIXELS_PER_BEAT);
    const midi = MIDI_MAX - Math.floor(gridY / NOTE_HEIGHT);

    // --- TOOL LOGIC ---

    if (tool === 'HAND' || (e.button === 1)) { // Middle click or Hand tool
        dragRef.current = {
            type: 'PAN',
            startX: e.clientX,
            startY: e.clientY,
            initialScrollX: scrollX,
            initialScrollY: scrollY
        };
        return;
    }

    if (tool === 'ERASER') {
        const clickedNote = getNoteAt(midi, beat);
        if (clickedNote) {
            addToHistory();
            setNotes(prev => prev.filter(n => n.id !== clickedNote.id));
        }
        return;
    }

    if (tool === 'PENCIL') {
        const existing = getNoteAt(midi, beat);
        if (existing) {
            setSelectedNoteId(existing.id);
        } else {
            // Create
            addToHistory();
            const newNote: SequencerNote = {
                id: Math.random().toString(36).substr(2, 9),
                midi: midi,
                startTime: Math.floor(beat * 4) / 4, // Snap 1/4
                duration: 1.0,
                lyric: 'la'
            };
            setNotes(prev => [...prev, newNote]);
            setSelectedNoteId(newNote.id);
            // Immediately start moving/resizing? Maybe just creation for now.
        }
        return;
    }

    if (tool === 'POINTER') {
        // We handle Note Click separately in onMouseDown on the Note element itself usually,
        // but if we clicked Empty Space, Deselect.
        const existing = getNoteAt(midi, beat);
        if (!existing) {
            setSelectedNoteId(null);
        }
    }
  };

  const handleNoteMouseDown = (e: React.MouseEvent, note: SequencerNote, type: 'MOVE' | 'RESIZE') => {
    e.stopPropagation();
    if (tool !== 'POINTER') return; // Only pointer modifies existing notes logic here

    addToHistory();
    setSelectedNoteId(note.id);

    dragRef.current = {
        type: type,
        noteId: note.id,
        startX: e.clientX,
        startY: e.clientY,
        initialStart: note.startTime,
        initialMidi: note.midi,
        initialDuration: note.duration
    };
  };

  const handleGlobalMove = (e: MouseEvent) => {
    if (!dragRef.current) return;
    const { type, startX, startY, noteId, initialStart, initialMidi, initialDuration, initialScrollX, initialScrollY } = dragRef.current;

    if (type === 'PAN' && containerRef.current) {
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        containerRef.current.scrollLeft = (initialScrollX || 0) - dx;
        containerRef.current.scrollTop = (initialScrollY || 0) - dy;
        return;
    }

    const deltaX = (e.clientX - startX) / PIXELS_PER_BEAT;
    const deltaY = (e.clientY - startY) / NOTE_HEIGHT;

    if (type === 'MOVE') {
        const newStart = Math.max(0, snapToGrid((initialStart || 0) + deltaX));
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, Math.round((initialMidi || 0) - deltaY)));

        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, startTime: newStart, midi: newMidi } : n));
    }

    if (type === 'RESIZE') {
        const newDur = Math.max(0.125, snapToGrid((initialDuration || 0) + deltaX, 0.125));
        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, duration: newDur } : n));
    }
  };

  const handleGlobalUp = () => {
    dragRef.current = null;
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleGlobalMove);
    window.addEventListener('mouseup', handleGlobalUp);
    return () => {
        window.removeEventListener('mousemove', handleGlobalMove);
        window.removeEventListener('mouseup', handleGlobalUp);
    };
  }, []);

  const updateNoteLyric = (id: string, newLyric: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, lyric: newLyric } : n));
  };

  const updateNoteDuration = (id: string, newDuration: number) => {
    if (isNaN(newDuration)) return;
    const d = Math.max(0.125, newDuration);
    setNotes(notes.map(n => n.id === id ? { ...n, duration: d } : n));
  };

  const deleteNote = (id: string) => {
      addToHistory();
      setNotes(notes.filter(n => n.id !== id));
      setSelectedNoteId(null);
  };

  const moveSelectedNote = (dt: number, dMidi: number) => {
    if (!selectedNoteId) return;
    addToHistory();
    setNotes(prev => prev.map(n => {
        if (n.id !== selectedNoteId) return n;
        const newStart = Math.max(0, n.startTime + dt);
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, n.midi + dMidi));
        return { ...n, startTime: newStart, midi: newMidi };
    }));
  };

  return (
    <div className="flex flex-col h-[500px] bg-gray-900 border border-synth-grid rounded-xl overflow-hidden select-none shadow-2xl relative group">

      {/* Toolbar */}
      <div className="bg-synth-panel p-2 flex gap-2 items-center border-b border-synth-grid h-12 shrink-0 z-30 relative">
        <span className="text-xs font-bold text-synth-accent mr-2 hidden sm:block">TOOLS</span>

        <div className="flex bg-synth-dark rounded-lg p-0.5 border border-synth-grid">
            <button onClick={() => setTool('POINTER')} className={`p-1.5 rounded-md ${tool === 'POINTER' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Select/Move/Resize">
                <MousePointer2 size={14} />
            </button>
            <button onClick={() => setTool('PENCIL')} className={`p-1.5 rounded-md ${tool === 'PENCIL' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Create">
                <Pencil size={14} />
            </button>
            <button onClick={() => setTool('HAND')} className={`p-1.5 rounded-md ${tool === 'HAND' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Navigate">
                <Hand size={14} />
            </button>
             <button onClick={() => setTool('ERASER')} className={`p-1.5 rounded-md ${tool === 'ERASER' ? 'bg-synth-pop text-white' : 'text-slate-400'}`} title="Erase">
                <Eraser size={14} />
            </button>
        </div>

        <div className="w-px h-6 bg-synth-grid mx-1"></div>

        <div className="flex gap-1">
             <button onClick={onUndo} disabled={!canUndo} className={`p-1.5 rounded-md ${canUndo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Undo size={14} /></button>
            <button onClick={onRedo} disabled={!canRedo} className={`p-1.5 rounded-md ${canRedo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Redo size={14} /></button>
        </div>

        {selectedNoteId && (
            <div className="flex items-center gap-2 ml-auto animate-in fade-in duration-200 border-l border-synth-grid pl-2">
                <input 
                    type="text" 
                    className="bg-synth-dark border border-synth-grid rounded px-2 py-1 text-xs text-white w-20 focus:border-synth-pop outline-none text-center"
                    value={notes.find(n => n.id === selectedNoteId)?.lyric || ''}
                    onChange={(e) => updateNoteLyric(selectedNoteId, e.target.value)}
                    onFocus={addToHistory}
                    placeholder="Lyric"
                    title="Lyric"
                />

                {/* Manual Duration Control */}
                <div className="flex items-center bg-synth-dark border border-synth-grid rounded px-1" title="Duration (Beats)">
                    <ArrowLeftRight size={10} className="text-slate-500 mr-1" />
                    <input 
                        type="number"
                        step={0.25}
                        min={0.125}
                        className="bg-transparent text-xs text-white w-10 focus:outline-none text-center font-mono appearance-none"
                        value={notes.find(n => n.id === selectedNoteId)?.duration || 0}
                        onChange={(e) => updateNoteDuration(selectedNoteId, parseFloat(e.target.value))}
                        onFocus={addToHistory}
                    />
                </div>
            </div>
        )}
      </div>

      {/* Main Scroll Container */}
      <div 
        ref={containerRef}
        className={`flex-1 overflow-auto bg-synth-dark relative scroll-smooth ${tool === 'HAND' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default'}`}
        onMouseDown={handleMouseDown}
      >
        <div 
            className="relative flex" 
            style={{ 
                height: `${TOTAL_KEYS * NOTE_HEIGHT}px`, 
                width: `${Math.max(durationBeats * PIXELS_PER_BEAT + 48, 1000)}px` // +48 for keys width
            }}
        >

            {/* STICKY KEYS COLUMN */}
            <div className="w-12 sticky left-0 z-20 bg-white border-r border-gray-300 flex flex-col shrink-0 shadow-lg">
                {keys.map((k) => (
                    <div 
                        key={k.midi} 
                        className={`h-[20px] border-b border-gray-300 text-[9px] flex items-center justify-end pr-1 font-bold ${k.isBlack ? 'bg-black text-white' : 'bg-white text-gray-800'}`}
                        style={{ height: NOTE_HEIGHT }}
                    >
                        {k.label}
                    </div>
                ))}
            </div>

            {/* GRID AREA */}
            <div className="flex-1 relative">

                {/* Background Rows */}
                {keys.map((k, i) => (
                    <div 
                        key={k.midi}
                        className={`absolute w-full border-b border-synth-grid/10 ${k.isBlack ? 'bg-synth-grid/5' : ''}`}
                        style={{ top: i * NOTE_HEIGHT, height: NOTE_HEIGHT }}
                    />
                ))}

                {/* Vertical Beat Lines */}
                {Array.from({ length: Math.ceil(durationBeats) + 1 }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`absolute top-0 bottom-0 w-px ${i % 4 === 0 ? 'bg-synth-grid/60' : 'bg-synth-grid/20'}`}
                        style={{ left: i * PIXELS_PER_BEAT }}
                    >
                        {i % 4 === 0 && <span className="absolute top-0 left-1 text-[8px] text-slate-500 font-mono">{i}</span>}
                    </div>
                ))}

                {/* NOTES */}
                {notes.map(note => {
                    const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                    const left = note.startTime * PIXELS_PER_BEAT;
                    const width = note.duration * PIXELS_PER_BEAT;
                    const isSelected = selectedNoteId === note.id;

                    return (
                        <div
                            key={note.id}
                            onMouseDown={(e) => handleNoteMouseDown(e, note, 'MOVE')}
                            className={`absolute rounded-sm border text-[10px] flex items-center pl-1 overflow-hidden shadow-sm group
                                ${isSelected 
                                    ? 'bg-synth-pop border-white text-white z-10 shadow-lg ring-1 ring-white' 
                                    : 'bg-synth-accent/90 border-synth-accent text-synth-dark hover:bg-synth-accent'
                                }`}
                            style={{
                                top: top + 1,
                                left: left,
                                width: Math.max(width - 1, 4),
                                height: NOTE_HEIGHT - 2,
                                cursor: tool === 'POINTER' ? 'move' : 'default'
                            }}
                        >
                            <span className="truncate w-full pointer-events-none select-none">{note.lyric}</span>

                            {/* Resize Handle */}
                            {tool === 'POINTER' && (
                                <div 
                                    className={`absolute right-0 top-0 bottom-0 w-4 cursor-ew-resize z-20 flex items-center justify-center opacity-0 hover:opacity-100 ${isSelected ? 'opacity-100' : ''}`}
                                    onMouseDown={(e) => handleNoteMouseDown(e, note, 'RESIZE')}
                                >
                                    <div className="w-1 h-3 bg-white/60 rounded-full" />
                                </div>
                            )}
                        </div>
                    );
                })}

            </div>
        </div>
      </div>

       {/* Floating Action Controls (Bottom Right) */}
       {selectedNoteId && (
        <div className="absolute bottom-4 right-4 z-50 flex items-end gap-3 animate-in fade-in slide-in-from-bottom-4 duration-200 pointer-events-auto">

            {/* D-Pad for Movement */}
            <div className="bg-synth-panel/95 backdrop-blur border border-synth-grid rounded-2xl p-2 shadow-2xl flex flex-col items-center gap-1">
                <button 
                    onClick={() => moveSelectedNote(0, 1)}
                    className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"
                    title="Pitch Up"
                >
                    <ArrowUp size={20} />
                </button>
                <div className="flex gap-1">
                     <button 
                        onClick={() => moveSelectedNote(-0.25, 0)}
                        className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"
                        title="Move Left"
                    >
                        <ArrowLeft size={20} />
                    </button>
                     <button 
                        onClick={() => moveSelectedNote(0, -1)}
                        className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"
                        title="Pitch Down"
                    >
                        <ArrowDown size={20} />
                    </button>
                     <button 
                        onClick={() => moveSelectedNote(0.25, 0)}
                        className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"
                        title="Move Right"
                    >
                        <ArrowRight size={20} />
                    </button>
                </div>
            </div>

            {/* Big Delete Button */}
            <button 
                onClick={() => deleteNote(selectedNoteId)}
                className="bg-red-500 hover:bg-red-600 text-white p-4 rounded-2xl shadow-xl shadow-red-900/20 active:scale-90 transition-all border border-red-400/50"
                title="Delete Note"
            >
                <Trash2 size={24} />
            </button>
        </div>
      )}

    </div>
  );
};

import { SequencerNote } from '../types';

/**
 * Parses RTTTL (Ring Tone Text Transfer Language) / RTX string
 */
function parseRtttl(text: string): SequencerNote[] {
  const parts = text.trim().split(':');
  if (parts.length < 3) throw new Error("Invalid RTTTL/RTX format");

  // Parse Defaults (e.g., d=4,o=5,b=63)
  const defaults = parts[1].toLowerCase().split(',').reduce((acc, curr) => {
     const [k, v] = curr.split('=');
     if (k && v) acc[k.trim()] = parseInt(v.trim());
     return acc;
  }, { d: 4, o: 5, b: 63 } as any);

  const notesStr = parts[2];
  const tokens = notesStr.split(',');

  const notes: SequencerNote[] = [];
  let currentTime = 0; // In Beats

  // RTTTL "beat" logic:
  // Duration 4 = Quarter Note = 1 Beat
  // Duration 8 = Eighth Note = 0.5 Beat

  tokens.forEach(token => {
      let t = token.trim().toLowerCase();
      if (!t) return;

      // Parse Duration
      let durStr = '';
      while (t.length > 0 && /\d/.test(t[0])) {
          durStr += t[0];
          t = t.slice(1);
      }
      let durationVal = durStr ? parseInt(durStr) : defaults.d;

      // Calculate beats: 4 / durationVal (e.g. 4/4 = 1 beat, 4/8 = 0.5 beat)
      let beats = 4.0 / durationVal;

      // Parse Note
      let noteChar = t[0];
      t = t.slice(1);

      let sharp = false;
      if (t.length > 0 && t[0] === '#') {
          sharp = true;
          t = t.slice(1);
      }

      let dot = false;
      if (t.includes('.')) {
          dot = true;
          t = t.replace('.', '');
      }

      // Parse Octave
      let octave = defaults.o;
      if (t.length > 0 && /\d/.test(t)) {
          octave = parseInt(t);
      }

      if (dot) beats *= 1.5;

      if (noteChar === 'p') {
          // Rest
          currentTime += beats;
      } else {
          // Note Conversion
          const baseMap: any = { c:0, d:2, e:4, f:5, g:7, a:9, b:11 };
          let midi = (octave + 1) * 12 + baseMap[noteChar];
          if (sharp) midi++;

          notes.push({
              id: Math.random().toString(36).substr(2, 9),
              midi: midi,
              startTime: currentTime,
              duration: beats,
              lyric: 'la'
          });

          currentTime += beats;
      }
  });

  return notes;
}

/**
 * Universal Parser (MIDI & RTTTL)
 */
export const parseMidiFile = (arrayBuffer: ArrayBuffer): SequencerNote[] => {
  const data = new DataView(arrayBuffer);

  // 1. Check for MIDI Header
  let isMidi = false;
  try {
      if (getText(data, 0, 4) === 'MThd') isMidi = true;
  } catch (e) {}

  // 2. Fallback to RTTTL if not MIDI
  if (!isMidi) {
      const decoder = new TextDecoder('utf-8');
      const text = decoder.decode(arrayBuffer);
      if (text.includes(':')) {
          return parseRtttl(text);
      }
      throw new Error("Unknown file format (Not MIDI or RTX/RTTTL)");
  }

  // 3. Parse MIDI
  let offset = 0;

  // Header Chunk
  const headerChunkType = getText(data, offset, 4);
  offset += 4;

  const headerLength = data.getUint32(offset);
  offset += 4;

  const format = data.getUint16(offset);
  offset += 2;
  const numTracks = data.getUint16(offset);
  offset += 2;
  const timeDivision = data.getUint16(offset); // Ticks per Quarter Note (PPQ)
  offset += 2;

  let notes: SequencerNote[] = [];

  for (let t = 0; t < numTracks; t++) {
    if (offset >= data.byteLength) break;
    const trackChunkType = getText(data, offset, 4);
    offset += 4;

    if (trackChunkType !== 'MTrk') break;

    const trackLength = data.getUint32(offset);
    offset += 4;

    const trackEnd = offset + trackLength;
    let currentTimeTicks = 0;
    let runningStatus = 0;

    const activeNotes: Record<number, number> = {};

    while (offset < trackEnd) {
      // Read Delta Time
      let deltaTime = 0;
      let byte = data.getUint8(offset++);
      deltaTime = byte & 0x7F;
      while (byte & 0x80) {
        byte = data.getUint8(offset++);
        deltaTime = (deltaTime << 7) | (byte & 0x7F);
      }

      currentTimeTicks += deltaTime;

      // Read Event Status
      let nextByte = data.getUint8(offset);
      let eventType = 0;

      if (nextByte & 0x80) {
        eventType = nextByte;
        offset++;
        // System Common/Realtime (0xF0-0xFF) usually do NOT affect Running Status for Voice messages
        if (eventType < 0xF0) runningStatus = eventType;
      } else {
        eventType = runningStatus;
      }

      // Process Event
      if (eventType === 0xFF) { 
        // Meta Event (FF <type> <len> <data>)
        const metaType = data.getUint8(offset++);
        const len = readVarLength();
        offset += len;
      } 
      else if (eventType === 0xF0 || eventType === 0xF7) {
        // Sysex (F0 <len> <data>) or Escape (F7 <len> <data>)
        // Note: In SMF, F0/F7 events are followed by VLQ length
        const len = readVarLength();
        offset += len;
      }
      else {
        // Voice Message
        const type = eventType & 0xF0;

        if (type === 0x80 || type === 0x90) { // Note Off / On
           const note = data.getUint8(offset++);
           const velocity = data.getUint8(offset++);

           if (type === 0x90 && velocity > 0) {
               // Note On
               activeNotes[note] = currentTimeTicks;
           } else {
               // Note Off
               if (activeNotes[note] !== undefined) {
                   const startTick = activeNotes[note];
                   const durationTicks = currentTimeTicks - startTick;
                   notes.push({
                      id: Math.random().toString(36).substr(2, 9),
                      midi: note,
                      startTime: startTick / timeDivision,
                      duration: durationTicks / timeDivision,
                      lyric: "la"
                   });
                   delete activeNotes[note];
               }
           }
        } 
        else if (type === 0xC0 || type === 0xD0) {
           offset += 1; 
        } 
        else if (type === 0xB0 || type === 0xE0 || type === 0xA0) {
           offset += 2; 
        }
      }
    }

    // Helper to read VLQ inside loop
    function readVarLength() {
        let len = 0;
        let b = data.getUint8(offset++);
        len = b & 0x7F;
        while (b & 0x80) {
            b = data.getUint8(offset++);
            len = (len << 7) | (b & 0x7F);
        }
        return len;
    }
  }

  return notes.sort((a, b) => a.startTime - b.startTime);
};

function getText(data: DataView, offset: number, length: number) {
  let str = '';
  for (let i = 0; i < length; i++) {
    str += String.fromCharCode(data.getUint8(offset + i));
  }
  return str;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  VowelType, 
  VocalMode, 
  VocalPreset,
  VocalParams, 
  GlobalParams,
  SequencerNote
} from './types';
import { 
  renderVocals, 
  renderSequence,
  applyReverb,
  bufferToWav,
  getFrequency,
  NOTE_FREQUENCIES
} from './services/audioEngine';
import { parseMidiFile } from './services/midiLoader';
import { ControlSlider } from './components/Knob';
import { PianoRoll } from './components/PianoRoll';
import { 
  Play, 
  Download, 
  Mic, 
  Activity,
  Settings,
  Music,
  Piano,
  Upload,
  Save,
  FileJson
} from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  const [mode, setMode] = useState<'LIVE' | 'SEQUENCER'>('LIVE');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedBuffer, setGeneratedBuffer] = useState<AudioBuffer | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Global State
  const [globalParams, setGlobalParams] = useState<GlobalParams>({
    bpm: 120,
    duration: 8.0, // Default duration in beats (approx) or seconds depending on mode, let's treat as Manual Duration Limit in Live, and Viewport in Seq
    reverbMix: 0.1,
    reverbDecay: 2.0
  });

  const [selectedNote, setSelectedNote] = useState<string>('C');
  const [selectedOctave, setSelectedOctave] = useState<number>(4);

  // Sequencer Data & History (Time is in BEATS)
  const [notes, setNotes] = useState<SequencerNote[]>([
      { id: '1', midi: 60, startTime: 0, duration: 1.0, lyric: 'o' },
      { id: '2', midi: 62, startTime: 1.0, duration: 1.0, lyric: 'i' },
      { id: '3', midi: 64, startTime: 2.0, duration: 2.0, lyric: 'e' }
  ]);

  // History Stacks
  const [history, setHistory] = useState<SequencerNote[][]>([]);
  const [future, setFuture] = useState<SequencerNote[][]>([]);

  // Function to capture state BEFORE a change (passed to child)
  const addToHistory = useCallback(() => {
    setHistory(prev => [...prev, notes]);
    setFuture([]); // Clear redo stack on new action
  }, [notes]);

  const handleUndo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);

    setFuture(prev => [notes, ...prev]);
    setNotes(previous);
    setHistory(newHistory);
  }, [history, notes]);

  const handleRedo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);

    setHistory(prev => [...prev, notes]);
    setNotes(next);
    setFuture(newFuture);
  }, [future, notes]);

  // Keyboard shortcuts for Undo/Redo
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        if (e.shiftKey) {
          handleRedo();
        } else {
          handleUndo();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo]);


  const [vocalParams, setVocalParams] = useState<VocalParams>({
    text: "OIE",
    preset: VocalPreset.MALE_BR,
    mode: VocalMode.SINGING,
    vowel: VowelType.A, // Legacy fallback
    jitter: 0.1,
    humanize: 0.1,
    breathiness: 0.2,
    formantShift: 1.0,
    speed: 1.0,
    pitch: 1.0,
    wordGap: 0.05 // Default slight pause
  });

  // Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedBuffer(null);

    setTimeout(async () => {
      try {
        const sampleRate = 44100;

        let buffer: AudioBuffer;

        if (mode === 'LIVE') {
             // Live mode uses direct seconds duration
             const ctx = new OfflineAudioContext(1, sampleRate * globalParams.duration, sampleRate);
             const baseFreq = getFrequency(selectedNote, selectedOctave);
             buffer = await renderVocals(ctx, vocalParams, globalParams.duration, baseFreq);
        } else {
            // Sequencer Mode: Convert Beats to Seconds
            const secondsPerBeat = 60 / globalParams.bpm;

            // Calculate total duration in seconds based on last note + tail
            let totalBeats = 16; // Minimum
            if (notes.length > 0) {
                const lastNote = notes.reduce((prev, curr) => (curr.startTime + curr.duration > prev.startTime + prev.duration) ? curr : prev);
                totalBeats = Math.max(16, lastNote.startTime + lastNote.duration + 4);
            }
            const totalSeconds = totalBeats * secondsPerBeat;

            const ctx = new OfflineAudioContext(1, sampleRate * totalSeconds, sampleRate);

            // Convert Notes Data to Seconds for Engine
            const secondsNotes = notes.map(n => ({
                ...n,
                startTime: n.startTime * secondsPerBeat,
                duration: n.duration * secondsPerBeat
            }));

            buffer = await renderSequence(ctx, secondsNotes, vocalParams);
        }

        // Apply Global Reverb
        if (globalParams.reverbMix > 0) {
            // Re-create context for reverb or use existing logic (engine handles it)
            // The current engine applies reverb to the passed buffer using a new context inside applyReverb
            const reverbCtx = new OfflineAudioContext(1, buffer.length, sampleRate);
            buffer = await applyReverb(reverbCtx, buffer, globalParams.reverbMix, globalParams.reverbDecay);
        }

        setGeneratedBuffer(buffer);
        drawWaveform(buffer);
      } catch (e) {
        console.error(e);
        alert("Error generating audio");
      } finally {
        setIsGenerating(false);
      }
    }, 50);
  };

  const handleMidiUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                addToHistory(); // Save current state before overwrite
                const parsedNotes = parseMidiFile(ev.target.result as ArrayBuffer);
                setNotes(parsedNotes);
                setMode('SEQUENCER'); // Auto switch
                alert(`Imported ${parsedNotes.length} notes!`);
            } catch (err) {
                console.error(err);
                alert("Failed to parse file. Make sure it is a valid MIDI (.mid) or RTX/RTTTL file.");
            }
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportJson = () => {
    const data = {
        version: 1,
        timestamp: Date.now(),
        notes: notes,
        vocalParams: vocalParams,
        globalParams: globalParams
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `project_${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                const data = JSON.parse(ev.target.result as string);
                addToHistory();
                if (data.notes) setNotes(data.notes);
                if (data.vocalParams) setVocalParams(data.vocalParams);
                if (data.globalParams) setGlobalParams(data.globalParams);
                setMode('SEQUENCER');
                alert("Project loaded!");
            } catch (err) {
                console.error(err);
                alert("Invalid project file.");
            }
        }
    };
    reader.readAsText(file);
  };


  const handlePlay = () => {
    if (!generatedBuffer) return;

    if (!audioContextRef.current) {
      audioContextRef.current = new AudioContext();
    }

    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') ctx.resume();

    const source = ctx.createBufferSource();
    source.buffer = generatedBuffer;
    source.connect(ctx.destination);

    source.onended = () => setIsPlaying(false);

    setIsPlaying(true);
    source.start();
  };

  const handleDownload = () => {
    if (!generatedBuffer) return;
    const blob = bufferToWav(generatedBuffer);
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;

    const name = `vocalstudio_${mode.toLowerCase()}_${Date.now()}.wav`;

    a.download = name;
    document.body.appendChild(a);
    a.click();

    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  };

  const drawWaveform = (buffer: AudioBuffer) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp = height / 2;

    ctx.clearRect(0, 0, width, height);
    ctx.beginPath();
    ctx.moveTo(0, amp);

    // Draw visual styling
    ctx.strokeStyle = '#38bdf8'; // Sky blue
    ctx.lineWidth = 2;

    for (let i = 0; i < width; i++) {
      let min = 1.0;
      let max = -1.0;
      for (let j = 0; j < step; j++) {
        const datum = data[(i * step) + j];
        if (datum < min) min = datum;
        if (datum > max) max = datum;
      }
      ctx.lineTo(i, (1 + min) * amp);
      ctx.lineTo(i, (1 + max) * amp);
    }

    ctx.stroke();
  };

  // Determine viewport duration for PianoRoll based on notes
  const seqDurationBeats = notes.length > 0 
    ? notes.reduce((max, n) => Math.max(max, n.startTime + n.duration), 0) + 8 
    : 32;

  return (
    <div className="min-h-screen bg-synth-dark text-slate-200 pb-40 font-sans selection:bg-synth-pop selection:text-white">

      {/* Header */}
      <header className="p-4 bg-synth-dark/90 backdrop-blur sticky top-0 z-10 border-b border-synth-grid flex justify-between items-center shadow-lg">
        <div>
          <h1 className="text-xl font-bold bg-gradient-to-r from-synth-accent to-synth-pop bg-clip-text text-transparent flex items-center gap-2">
            <Mic size={24} className="text-synth-accent" />
            VocalStudio
          </h1>
          <p className="text-[10px] text-slate-500 tracking-wide font-mono">DSP VOCAL WORKSTATION</p>
        </div>

        {/* Mode Switcher */}
        <div className="flex bg-synth-panel rounded-lg p-1 border border-synth-grid gap-1">
            <button
                onClick={() => setMode('LIVE')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'LIVE' ? 'bg-synth-accent text-synth-dark' : 'text-slate-500'}`}
            >
                <Music size={12} />
                LIVE
            </button>
            <button
                onClick={() => setMode('SEQUENCER')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'SEQUENCER' ? 'bg-synth-pop text-white' : 'text-slate-500'}`}
            >
                <Piano size={12} />
                SEQ
            </button>
        </div>
      </header>

      <main className="p-4 max-w-lg mx-auto w-full space-y-5">

        {/* Visualization Area */}
        <div className="bg-black/40 rounded-2xl border border-synth-grid p-4 h-24 flex items-center justify-center relative overflow-hidden group">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-synth-panel/50 to-transparent opacity-50" />
          <canvas 
            ref={canvasRef} 
            width={600} 
            height={200} 
            className="w-full h-full relative z-10 opacity-90"
          />
        </div>

        {/* --- SEQUENCER MODE UI --- */}
        {mode === 'SEQUENCER' && (
             <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex justify-between items-center">
                    <h2 className="text-sm font-bold text-synth-pop flex items-center gap-2">
                        <Piano size={16} />
                        PIANO ROLL
                    </h2>
                    <div className="flex gap-2">
                         <input 
                            type="file" 
                            accept=".mid,.midi,.rtx,.txt" 
                            className="hidden" 
                            ref={fileInputRef}
                            onChange={handleMidiUpload}
                        />
                         <input 
                            type="file" 
                            accept=".json" 
                            className="hidden" 
                            ref={jsonInputRef}
                            onChange={handleImportJson}
                        />
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700"
                        >
                            <Upload size={10} />
                            MIDI/RTX
                        </button>
                    </div>
                </div>

                <PianoRoll 
                    notes={notes}
                    setNotes={setNotes}
                    durationBeats={seqDurationBeats}
                    onUndo={handleUndo}
                    onRedo={handleRedo}
                    addToHistory={addToHistory}
                    canUndo={history.length > 0}
                    canRedo={future.length > 0}
                />
             </div>
        )}

        {/* --- LIVE MODE UI --- */}
        {mode === 'LIVE' && (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="bg-synth-panel p-4 rounded-xl border border-synth-grid flex justify-between items-center">
                    <span className="text-xs font-bold text-synth-accent uppercase">Base Pitch</span>
                    <div className="flex gap-2 items-center bg-synth-dark rounded-lg p-1 border border-synth-grid/50">
                        <select 
                            value={selectedNote}
                            onChange={(e) => setSelectedNote(e.target.value)}
                            className="bg-transparent text-white font-mono text-xs font-bold outline-none"
                        >
                            {Object.keys(NOTE_FREQUENCIES).map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                        <div className="w-px h-4 bg-synth-grid"></div>
                        <select 
                            value={selectedOctave}
                            onChange={(e) => setSelectedOctave(parseInt(e.target.value))}
                            className="bg-transparent text-synth-accent font-mono text-xs font-bold outline-none"
                        >
                            {[1,2,3,4,5,6].map(o => <option key={o} value={o}>{o}</option>)}
                        </select>
                    </div>
                </div>

                <div className="mb-4">
                    <label className="text-[10px] font-bold text-synth-accent uppercase mb-1 block">Sequencer Text</label>
                    <textarea
                        value={vocalParams.text}
                        onChange={(e) => setVocalParams(p => ({ ...p, text: e.target.value }))}
                        className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-lg font-mono tracking-widest text-white focus:border-synth-pop outline-none h-24"
                        placeholder="Type phonemes..."
                    />
                </div>
            </div>
        )}

        {/* Global Config (Shared) */}
        <div className="bg-synth-panel/30 p-4 rounded-xl border border-synth-grid/50">
          <div className="flex items-center gap-2 mb-3 text-synth-accent">
            <Settings size={16} />
            <span className="text-xs font-bold uppercase">Voice Parameters</span>
          </div>

           <div className="mb-4">
              <select
                value={vocalParams.preset}
                onChange={(e) => setVocalParams(p => ({ ...p, preset: e.target.value as VocalPreset }))}
                className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-sm text-white focus:border-synth-pop outline-none appearance-none"
              >
                {Object.values(VocalPreset).map(preset => (
                  <option key={preset} value={preset}>{preset}</option>
                ))}
              </select>
            </div>

            <div className="mb-4 flex bg-synth-panel rounded-xl border border-synth-grid p-1">
                  {Object.values(VocalMode).map(m => (
                    <button
                      key={m}
                      onClick={() => setVocalParams(p => ({...p, mode: m as VocalMode}))}
                      className={`flex-1 py-2 text-xs font-bold rounded-lg uppercase transition-all ${
                          vocalParams.mode === m 
                          ? 'bg-synth-pop text-white shadow-md' 
                          : 'text-slate-400'
                      }`}
                    >
                      {m}
                    </button>
                  ))}
            </div>

          <div className="space-y-4">
            <div className="flex gap-2">
                <ControlSlider
                    label="BPM"
                    value={globalParams.bpm}
                    min={60}
                    max={200}
                    step={1}
                    onChange={(v) => setGlobalParams(p => ({...p, bpm: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                <ControlSlider
                    label={mode === 'LIVE' ? 'Duration (s)' : 'View Size'}
                    value={globalParams.duration}
                    min={1.0}
                    max={30.0}
                    step={1.0}
                    unit=""
                    onChange={(v) => setGlobalParams(p => ({...p, duration: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>

            <div className="flex gap-2">
                <ControlSlider
                    label="Humanize"
                    value={vocalParams.humanize}
                    min={0}
                    max={1.0}
                    onChange={(v) => setVocalParams(p => ({...p, humanize: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                 <ControlSlider
                    label="Reverb"
                    value={globalParams.reverbMix}
                    min={0}
                    max={0.8}
                    onChange={(v) => setGlobalParams(p => ({...p, reverbMix: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>
          </div>
        </div>

      </main>

      {/* Sticky Action Footer */}
      <footer className="fixed bottom-0 left-0 right-0 bg-synth-dark/95 backdrop-blur border-t border-synth-grid p-4 z-50 safe-area-bottom shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
        <div className="max-w-lg mx-auto flex gap-4">
            {/* Project Buttons */}
            <div className="flex flex-col gap-1">
                <button
                    onClick={handleExportJson}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Export Project"
                >
                    <Save size={16} />
                </button>
                 <button
                    onClick={() => jsonInputRef.current?.click()}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Import Project"
                >
                    <FileJson size={16} />
                </button>
            </div>

          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="flex-1 bg-synth-panel hover:bg-slate-700 text-white font-bold py-2 px-4 rounded-2xl border border-synth-grid shadow-lg active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
          >
            <Activity className={isGenerating ? "animate-spin" : ""} size={20} />
            <span className="text-[10px] uppercase tracking-wider">{isGenerating ? "Wait..." : (mode === 'SEQUENCER' ? "RENDER SEQ" : "RENDER")}</span>
          </button>

          {generatedBuffer && (
            <>
              <button
                onClick={handlePlay}
                className={`w-14 bg-synth-accent text-synth-dark font-bold rounded-2xl flex items-center justify-center shadow-[0_0_15px_rgba(56,189,248,0.3)] active:scale-95 transition-transform ${isPlaying ? 'opacity-80' : ''}`}
              >
                <Play fill={isPlaying ? "currentColor" : "none"} size={24} />
              </button>

              <button
                onClick={handleDownload}
                className="flex-1 bg-synth-pop hover:bg-pink-500 text-white font-bold py-2 px-4 rounded-2xl shadow-[0_0_15px_rgba(244,114,182,0.3)] active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
              >
                <Download size={20} />
                 <span className="text-[10px] uppercase tracking-wider">SAVE WAV</span>
              </button>
            </>
          )}
        </div>
      </footer>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  VowelType, 
  VocalMode, 
  VocalPreset,
  VocalParams, 
  GlobalParams,
  SequencerNote
} from './types';
import { 
  renderVocals, 
  renderSequence,
  applyReverb,
  bufferToWav,
  getFrequency,
  NOTE_FREQUENCIES
} from './services/audioEngine';
import { parseMidiFile } from './services/midiLoader';
import { ControlSlider } from './components/Knob';
import { PianoRoll } from './components/PianoRoll';
import { 
  Play, 
  Download, 
  Mic, 
  Activity,
  Settings,
  Music,
  Piano,
  Upload,
  Save,
  FileJson,
  Type,
  X,
