} from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  const [mode, setMode] = useState<'LIVE' | 'SEQUENCER'>('LIVE');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedBuffer, setGeneratedBuffer] = useState<AudioBuffer | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Global State
  const [globalParams, setGlobalParams] = useState<GlobalParams>({
    bpm: 120,
    duration: 8.0, // Default duration in beats (approx) or seconds depending on mode, let's treat as Manual Duration Limit in Live, and Viewport in Seq
    reverbMix: 0.1,
    reverbDecay: 2.0
  });

  const [selectedNote, setSelectedNote] = useState<string>('C');
  const [selectedOctave, setSelectedOctave] = useState<number>(4);

  // Sequencer Data & History (Time is in BEATS)
  const [notes, setNotes] = useState<SequencerNote[]>([
      { id: '1', midi: 60, startTime: 0, duration: 1.0, lyric: 'o' },
      { id: '2', midi: 62, startTime: 1.0, duration: 1.0, lyric: 'i' },
      { id: '3', midi: 64, startTime: 2.0, duration: 2.0, lyric: 'e' }
  ]);

  // History Stacks
  const [history, setHistory] = useState<SequencerNote[][]>([]);
  const [future, setFuture] = useState<SequencerNote[][]>([]);

  // Lyrics Adapter State
  const [showLyricsModal, setShowLyricsModal] = useState(false);
  const [lyricsInput, setLyricsInput] = useState("");

  // Function to capture state BEFORE a change (passed to child)
  const addToHistory = useCallback(() => {
    setHistory(prev => [...prev, notes]);
    setFuture([]); // Clear redo stack on new action
  }, [notes]);

  const handleUndo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);

    setFuture(prev => [notes, ...prev]);
    setNotes(previous);
    setHistory(newHistory);
  }, [history, notes]);

  const handleRedo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);

    setHistory(prev => [...prev, notes]);
    setNotes(next);
    setFuture(newFuture);
  }, [future, notes]);

  // Keyboard shortcuts for Undo/Redo
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        if (e.shiftKey) {
          handleRedo();
        } else {
          handleUndo();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo]);


  const [vocalParams, setVocalParams] = useState<VocalParams>({
    text: "OIE",
    preset: VocalPreset.MALE_BR,
    mode: VocalMode.SINGING,
    vowel: VowelType.A, // Legacy fallback
    jitter: 0.1,
    humanize: 0.1,
    breathiness: 0.2,
    formantShift: 1.0,
    speed: 1.0,
    pitch: 1.0,
    wordGap: 0.05 // Default slight pause
  });

  // Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedBuffer(null);

    setTimeout(async () => {
      try {
        const sampleRate = 44100;

        let buffer: AudioBuffer;

        if (mode === 'LIVE') {
             // Live mode uses direct seconds duration
             const ctx = new OfflineAudioContext(1, sampleRate * globalParams.duration, sampleRate);
             const baseFreq = getFrequency(selectedNote, selectedOctave);
             buffer = await renderVocals(ctx, vocalParams, globalParams.duration, baseFreq);
        } else {
            // Sequencer Mode: Convert Beats to Seconds
            const secondsPerBeat = 60 / globalParams.bpm;

            // Calculate total duration in seconds based on last note + tail
            let totalBeats = 16; // Minimum
            if (notes.length > 0) {
                const lastNote = notes.reduce((prev, curr) => (curr.startTime + curr.duration > prev.startTime + prev.duration) ? curr : prev);
                totalBeats = Math.max(16, lastNote.startTime + lastNote.duration + 4);
            }
            const totalSeconds = totalBeats * secondsPerBeat;

            const ctx = new OfflineAudioContext(1, sampleRate * totalSeconds, sampleRate);

            // Convert Notes Data to Seconds for Engine
            const secondsNotes = notes.map(n => ({
                ...n,
                startTime: n.startTime * secondsPerBeat,
                duration: n.duration * secondsPerBeat
            }));

            buffer = await renderSequence(ctx, secondsNotes, vocalParams);
        }

        // Apply Global Reverb
        if (globalParams.reverbMix > 0) {
            // Re-create context for reverb or use existing logic (engine handles it)
            // The current engine applies reverb to the passed buffer using a new context inside applyReverb
            const reverbCtx = new OfflineAudioContext(1, buffer.length, sampleRate);
            buffer = await applyReverb(reverbCtx, buffer, globalParams.reverbMix, globalParams.reverbDecay);
        }

        setGeneratedBuffer(buffer);
        drawWaveform(buffer);
      } catch (e) {
        console.error(e);
        alert("Error generating audio");
      } finally {
        setIsGenerating(false);
      }
    }, 50);
  };

  const handleApplyLyrics = () => {
      if (!lyricsInput.trim()) {
          setShowLyricsModal(false);
          return;
      }

      addToHistory();

      // 1. Parse Syllables (Split by Space, Hyphen or Newline)
      // Removes empty strings
      const syllables = lyricsInput
          .replace(/[\n\r]/g, ' ') // Convert newlines to space
          .split(/[\s-]+/) // Split by space or hyphen
          .filter(s => s.length > 0);

      if (syllables.length === 0) return;

      // 2. Clone and Sort Notes
      let tempNotes = [...notes].sort((a, b) => a.startTime - b.startTime);

      // 3. Smart Split Logic: Ensure we have enough notes
      // While we have more syllables than notes, split the longest notes
      let iterations = 0;
      const MAX_ITERATIONS = 500; // Safety break

      while (syllables.length > tempNotes.length && iterations < MAX_ITERATIONS) {
          // Find the note with the maximum duration
          let maxDur = 0;
          let maxIdx = -1;

          for (let i = 0; i < tempNotes.length; i++) {
              if (tempNotes[i].duration > maxDur) {
                  maxDur = tempNotes[i].duration;
                  maxIdx = i;
              }
          }

          if (maxIdx !== -1) {
              const target = tempNotes[maxIdx];
              const halfDur = target.duration / 2;

              // Only split if resulting note is reasonably sized (e.g. > 1/16th)
              // Or force it if we really need space. Let's force down to 1/32.
              if (halfDur >= 0.03125) {
                   // Create two notes from one
                   const noteA = { ...target, duration: halfDur };
                   const noteB = { 
                       ...target, 
                       id: Math.random().toString(36).substr(2, 9),
                       startTime: target.startTime + halfDur,
                       duration: halfDur,
                       lyric: '' // Will be filled later
                   };

                   // Replace original with two new ones
                   tempNotes.splice(maxIdx, 1, noteA, noteB);

                   // Re-sorting technically not needed if we insert in place but good for safety
                   // Since we insert at maxIdx, order is preserved relative to others
              } else {
                  // If we can't split anymore (notes too small), break to avoid infinite loop
                  break; 
              }
          } else {
              break;
          }
          iterations++;
      }

      // 4. Assign Syllables
      const finalNotes = tempNotes.map((note, index) => {
          if (index < syllables.length) {
              return { ...note, lyric: syllables[index] };
          }
          return note; // Keep existing or empty? Keep existing is safer usually, or maybe clear.
      });

      setNotes(finalNotes);
      setLyricsInput("");
      setShowLyricsModal(false);
  };

  const handleMidiUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                addToHistory(); // Save current state before overwrite
                const parsedNotes = parseMidiFile(ev.target.result as ArrayBuffer);
                setNotes(parsedNotes);
                setMode('SEQUENCER'); // Auto switch
                alert(`Imported ${parsedNotes.length} notes!`);
            } catch (err) {
                console.error(err);
                alert("Failed to parse file. Make sure it is a valid MIDI (.mid) or RTX/RTTTL file.");
            }
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportJson = () => {
    const data = {
        version: 1,
        timestamp: Date.now(),
        notes: notes,
        vocalParams: vocalParams,
        globalParams: globalParams
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `project_${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                const data = JSON.parse(ev.target.result as string);
                addToHistory();
                if (data.notes) setNotes(data.notes);
                if (data.vocalParams) setVocalParams(data.vocalParams);
                if (data.globalParams) setGlobalParams(data.globalParams);
                setMode('SEQUENCER');
                alert("Project loaded!");
            } catch (err) {
                console.error(err);
                alert("Invalid project file.");
            }
        }
    };
    reader.readAsText(file);
  };


  const handlePlay = () => {
    if (!generatedBuffer) return;

    if (!audioContextRef.current) {
      audioContextRef.current = new AudioContext();
    }

    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') ctx.resume();

    const source = ctx.createBufferSource();
    source.buffer = generatedBuffer;
    source.connect(ctx.destination);

    source.onended = () => setIsPlaying(false);

    setIsPlaying(true);
    source.start();
  };

  const handleDownload = () => {
    if (!generatedBuffer) return;
    const blob = bufferToWav(generatedBuffer);
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;

    const name = `vocalstudio_${mode.toLowerCase()}_${Date.now()}.wav`;

    a.download = name;
    document.body.appendChild(a);
    a.click();

    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  };

  const drawWaveform = (buffer: AudioBuffer) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp = height / 2;

    ctx.clearRect(0, 0, width, height);
    ctx.beginPath();
    ctx.moveTo(0, amp);

    // Draw visual styling
    ctx.strokeStyle = '#38bdf8'; // Sky blue
    ctx.lineWidth = 2;

    for (let i = 0; i < width; i++) {
      let min = 1.0;
      let max = -1.0;
      for (let j = 0; j < step; j++) {
        const datum = data[(i * step) + j];
        if (datum < min) min = datum;
        if (datum > max) max = datum;
      }
      ctx.lineTo(i, (1 + min) * amp);
      ctx.lineTo(i, (1 + max) * amp);
    }

    ctx.stroke();
  };

  // Determine viewport duration for PianoRoll based on notes
  const seqDurationBeats = notes.length > 0 
    ? notes.reduce((max, n) => Math.max(max, n.startTime + n.duration), 0) + 8 
    : 32;

  return (
    <div className="min-h-screen bg-synth-dark text-slate-200 pb-40 font-sans selection:bg-synth-pop selection:text-white">

      {/* Header */}
      <header className="p-4 bg-synth-dark/90 backdrop-blur sticky top-0 z-10 border-b border-synth-grid flex justify-between items-center shadow-lg">
        <div>
          <h1 className="text-xl font-bold bg-gradient-to-r from-synth-accent to-synth-pop bg-clip-text text-transparent flex items-center gap-2">
            <Mic size={24} className="text-synth-accent" />
            VocalStudio
          </h1>
          <p className="text-[10px] text-slate-500 tracking-wide font-mono">DSP VOCAL WORKSTATION</p>
        </div>

        {/* Mode Switcher */}
        <div className="flex bg-synth-panel rounded-lg p-1 border border-synth-grid gap-1">
            <button
                onClick={() => setMode('LIVE')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'LIVE' ? 'bg-synth-accent text-synth-dark' : 'text-slate-500'}`}
            >
                <Music size={12} />
                LIVE
            </button>
            <button
                onClick={() => setMode('SEQUENCER')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'SEQUENCER' ? 'bg-synth-pop text-white' : 'text-slate-500'}`}
            >
                <Piano size={12} />
                SEQ
            </button>
        </div>
      </header>

      <main className="p-4 max-w-lg mx-auto w-full space-y-5 relative">

        {/* Visualization Area */}
        <div className="bg-black/40 rounded-2xl border border-synth-grid p-4 h-24 flex items-center justify-center relative overflow-hidden group">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-synth-panel/50 to-transparent opacity-50" />
          <canvas 
            ref={canvasRef} 
            width={600} 
            height={200} 
            className="w-full h-full relative z-10 opacity-90"
          />
        </div>

        {/* --- SEQUENCER MODE UI --- */}
        {mode === 'SEQUENCER' && (
             <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex justify-between items-center">
                    <h2 className="text-sm font-bold text-synth-pop flex items-center gap-2">
                        <Piano size={16} />
                        PIANO ROLL
                    </h2>
                    <div className="flex gap-2">
                         <input 
                            type="file" 
                            accept=".mid,.midi,.rtx,.txt" 
                            className="hidden" 
                            ref={fileInputRef}
                            onChange={handleMidiUpload}
                        />
                         <input 
                            type="file" 
                            accept=".json" 
                            className="hidden" 
                            ref={jsonInputRef}
                            onChange={handleImportJson}
                        />
                        <button 
                            onClick={() => setShowLyricsModal(true)}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700 text-synth-accent font-bold"
                        >
                            <Type size={12} />
                            LYRICS
                        </button>
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700"
                        >
                            <Upload size={10} />
                            MIDI
                        </button>
                    </div>
                </div>

                <PianoRoll 
                    notes={notes}
                    setNotes={setNotes}
                    durationBeats={seqDurationBeats}
                    onUndo={handleUndo}
                    onRedo={handleRedo}
                    addToHistory={addToHistory}
                    canUndo={history.length > 0}
                    canRedo={future.length > 0}
                />
             </div>
        )}

        {/* --- LIVE MODE UI --- */}
        {mode === 'LIVE' && (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="bg-synth-panel p-4 rounded-xl border border-synth-grid flex justify-between items-center">
                    <span className="text-xs font-bold text-synth-accent uppercase">Base Pitch</span>
                    <div className="flex gap-2 items-center bg-synth-dark rounded-lg p-1 border border-synth-grid/50">
                        <select 
                            value={selectedNote}
                            onChange={(e) => setSelectedNote(e.target.value)}
                            className="bg-transparent text-white font-mono text-xs font-bold outline-none"
                        >
                            {Object.keys(NOTE_FREQUENCIES).map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                        <div className="w-px h-4 bg-synth-grid"></div>
                        <select 
                            value={selectedOctave}
                            onChange={(e) => setSelectedOctave(parseInt(e.target.value))}
                            className="bg-transparent text-synth-accent font-mono text-xs font-bold outline-none"
                        >
                            {[1,2,3,4,5,6].map(o => <option key={o} value={o}>{o}</option>)}
                        </select>
                    </div>
                </div>

                <div className="mb-4">
                    <label className="text-[10px] font-bold text-synth-accent uppercase mb-1 block">Sequencer Text</label>
                    <textarea
                        value={vocalParams.text}
                        onChange={(e) => setVocalParams(p => ({ ...p, text: e.target.value }))}
                        className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-lg font-mono tracking-widest text-white focus:border-synth-pop outline-none h-24"
                        placeholder="Type phonemes..."
                    />
                </div>
            </div>
        )}

        {/* Global Config (Shared) */}
        <div className="bg-synth-panel/30 p-4 rounded-xl border border-synth-grid/50">
          <div className="flex items-center gap-2 mb-3 text-synth-accent">
            <Settings size={16} />
            <span className="text-xs font-bold uppercase">Voice Parameters</span>
          </div>

           <div className="mb-4">
              <select
                value={vocalParams.preset}
                onChange={(e) => setVocalParams(p => ({ ...p, preset: e.target.value as VocalPreset }))}
                className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-sm text-white focus:border-synth-pop outline-none appearance-none"
              >
                {Object.values(VocalPreset).map(preset => (
                  <option key={preset} value={preset}>{preset}</option>
                ))}
              </select>
            </div>

            <div className="mb-4 flex bg-synth-panel rounded-xl border border-synth-grid p-1">
                  {Object.values(VocalMode).map(m => (
                    <button
                      key={m}
                      onClick={() => setVocalParams(p => ({...p, mode: m as VocalMode}))}
                      className={`flex-1 py-2 text-xs font-bold rounded-lg uppercase transition-all ${
                          vocalParams.mode === m 
                          ? 'bg-synth-pop text-white shadow-md' 
                          : 'text-slate-400'
                      }`}
                    >
                      {m}
                    </button>
                  ))}
            </div>

          <div className="space-y-4">
            <div className="flex gap-2">
                <ControlSlider
                    label="BPM"
                    value={globalParams.bpm}
                    min={60}
                    max={200}
                    step={1}
                    onChange={(v) => setGlobalParams(p => ({...p, bpm: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                <ControlSlider
                    label={mode === 'LIVE' ? 'Duration (s)' : 'View Size'}
                    value={globalParams.duration}
                    min={1.0}
                    max={30.0}
                    step={1.0}
                    unit=""
                    onChange={(v) => setGlobalParams(p => ({...p, duration: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>

            <div className="flex gap-2">
                <ControlSlider
                    label="Humanize"
                    value={vocalParams.humanize}
                    min={0}
                    max={1.0}
                    onChange={(v) => setVocalParams(p => ({...p, humanize: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                 <ControlSlider
                    label="Reverb"
                    value={globalParams.reverbMix}
                    min={0}
                    max={0.8}
                    onChange={(v) => setGlobalParams(p => ({...p, reverbMix: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>
          </div>
        </div>

        {/* LYRICS MODAL */}
        {showLyricsModal && (
            <div className="absolute inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                <div className="bg-synth-panel border border-synth-grid rounded-2xl w-full max-w-sm p-4 shadow-2xl flex flex-col gap-3">
                    <div className="flex justify-between items-center border-b border-synth-grid pb-2">
                        <h3 className="text-sm font-bold text-white flex items-center gap-2">
                            <Type size={16} className="text-synth-accent" />
                            ADAPT LYRICS TO NOTES
                        </h3>
                        <button onClick={() => setShowLyricsModal(false)} className="text-slate-400 hover:text-white">
                            <X size={18} />
                        </button>
                    </div>
                    <p className="text-[10px] text-slate-400">
                        Paste your lyrics here. The app will auto-split notes if there are more syllables than notes.
                    </p>
                    <textarea 
                        className="w-full h-32 bg-synth-dark border border-synth-grid rounded-xl p-3 text-white focus:border-synth-accent outline-none font-mono text-sm"
                        placeholder="Paste lyrics (space or hyphen separated)..."
                        value={lyricsInput}
                        onChange={(e) => setLyricsInput(e.target.value)}
                    />
                    <div className="flex gap-2">
                         <button 
                            onClick={() => setShowLyricsModal(false)}
                            className="flex-1 py-2 rounded-xl text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600"
                        >
                            CANCEL
                        </button>
                        <button 
                            onClick={handleApplyLyrics}
                            className="flex-1 py-2 rounded-xl text-xs font-bold bg-synth-accent text-synth-dark hover:bg-sky-300 flex items-center justify-center gap-2"
                        >
                            <Check size={14} />
                            APPLY
                        </button>
                    </div>
                </div>
            </div>
        )}

      </main>

      {/* Sticky Action Footer */}
      <footer className="fixed bottom-0 left-0 right-0 bg-synth-dark/95 backdrop-blur border-t border-synth-grid p-4 z-50 safe-area-bottom shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
        <div className="max-w-lg mx-auto flex gap-4">
            {/* Project Buttons */}
            <div className="flex flex-col gap-1">
                <button
                    onClick={handleExportJson}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Export Project"
                >
                    <Save size={16} />
                </button>
                 <button
                    onClick={() => jsonInputRef.current?.click()}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Import Project"
                >
                    <FileJson size={16} />
                </button>
            </div>

          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="flex-1 bg-synth-panel hover:bg-slate-700 text-white font-bold py-2 px-4 rounded-2xl border border-synth-grid shadow-lg active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
          >
            <Activity className={isGenerating ? "animate-spin" : ""} size={20} />
            <span className="text-[10px] uppercase tracking-wider">{isGenerating ? "Wait..." : (mode === 'SEQUENCER' ? "RENDER SEQ" : "RENDER")}</span>
          </button>

          {generatedBuffer && (
            <>
              <button
                onClick={handlePlay}
                className={`w-14 bg-synth-accent text-synth-dark font-bold rounded-2xl flex items-center justify-center shadow-[0_0_15px_rgba(56,189,248,0.3)] active:scale-95 transition-transform ${isPlaying ? 'opacity-80' : ''}`}
              >
                <Play fill={isPlaying ? "currentColor" : "none"} size={24} />
              </button>

              <button
                onClick={handleDownload}
                className="flex-1 bg-synth-pop hover:bg-pink-500 text-white font-bold py-2 px-4 rounded-2xl shadow-[0_0_15px_rgba(244,114,182,0.3)] active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
              >
                <Download size={20} />
                 <span className="text-[10px] uppercase tracking-wider">SAVE WAV</span>
              </button>
            </>
          )}
        </div>
      </footer>

    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  VowelType, 
  VocalMode, 
  VocalPreset,
  VocalParams, 
  GlobalParams,
  SequencerNote
} from './types';
import { 
  renderVocals, 
  renderSequence,
  applyReverb,
  bufferToWav,
  getFrequency,
  NOTE_FREQUENCIES
} from './services/audioEngine';
import { parseMidiFile } from './services/midiLoader';
import { ControlSlider } from './components/Knob';
import { PianoRoll } from './components/PianoRoll';
import { 
  Play, 
  Download, 
  Mic, 
  Activity,
  Settings,
  Music,
  Piano,
  Upload,
  Save,
  FileJson,
  Type,
  X,
  Check
} from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  const [mode, setMode] = useState<'LIVE' | 'SEQUENCER'>('LIVE');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedBuffer, setGeneratedBuffer] = useState<AudioBuffer | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Global State
  const [globalParams, setGlobalParams] = useState<GlobalParams>({
    bpm: 120,
    duration: 8.0, // Default duration in beats (approx) or seconds depending on mode, let's treat as Manual Duration Limit in Live, and Viewport in Seq
    reverbMix: 0.1,
    reverbDecay: 2.0
  });

  const [selectedNote, setSelectedNote] = useState<string>('C');
  const [selectedOctave, setSelectedOctave] = useState<number>(4);

  // Sequencer Data & History (Time is in BEATS)
  const [notes, setNotes] = useState<SequencerNote[]>([
      { id: '1', midi: 60, startTime: 0, duration: 1.0, lyric: 'o' },
      { id: '2', midi: 62, startTime: 1.0, duration: 1.0, lyric: 'i' },
      { id: '3', midi: 64, startTime: 2.0, duration: 2.0, lyric: 'e' }
  ]);

  // History Stacks
  const [history, setHistory] = useState<SequencerNote[][]>([]);
  const [future, setFuture] = useState<SequencerNote[][]>([]);

  // Lyrics Adapter State
  const [showLyricsModal, setShowLyricsModal] = useState(false);
  const [lyricsInput, setLyricsInput] = useState("");

  // Function to capture state BEFORE a change (passed to child)
  const addToHistory = useCallback(() => {
    setHistory(prev => [...prev, notes]);
    setFuture([]); // Clear redo stack on new action
  }, [notes]);

  const handleUndo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);

    setFuture(prev => [notes, ...prev]);
    setNotes(previous);
    setHistory(newHistory);
  }, [history, notes]);

  const handleRedo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);

    setHistory(prev => [...prev, notes]);
    setNotes(next);
    setFuture(newFuture);
  }, [future, notes]);

  // Keyboard shortcuts for Undo/Redo
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        if (e.shiftKey) {
          handleRedo();
        } else {
          handleUndo();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo]);


  const [vocalParams, setVocalParams] = useState<VocalParams>({
    text: "OIE",
    preset: VocalPreset.MALE_BR,
    mode: VocalMode.SINGING,
    vowel: VowelType.A, // Legacy fallback
    jitter: 0.1,
    humanize: 0.1,
    breathiness: 0.2,
    formantShift: 1.0,
    speed: 1.0,
    pitch: 1.0,
    wordGap: 0.05 // Default slight pause
  });

  // Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedBuffer(null);

    setTimeout(async () => {
      try {
        const sampleRate = 44100;

        let buffer: AudioBuffer;

        if (mode === 'LIVE') {
             // Live mode uses direct seconds duration
             const ctx = new OfflineAudioContext(1, sampleRate * globalParams.duration, sampleRate);
             const baseFreq = getFrequency(selectedNote, selectedOctave);
             buffer = await renderVocals(ctx, vocalParams, globalParams.duration, baseFreq);
        } else {
            // Sequencer Mode: Convert Beats to Seconds
            const secondsPerBeat = 60 / globalParams.bpm;

            // Calculate total duration in seconds based on last note + tail
            let totalBeats = 16; // Minimum
            if (notes.length > 0) {
                const lastNote = notes.reduce((prev, curr) => (curr.startTime + curr.duration > prev.startTime + prev.duration) ? curr : prev);
                totalBeats = Math.max(16, lastNote.startTime + lastNote.duration + 4);
            }
            const totalSeconds = totalBeats * secondsPerBeat;

            const ctx = new OfflineAudioContext(1, sampleRate * totalSeconds, sampleRate);

            // Convert Notes Data to Seconds for Engine
            const secondsNotes = notes.map(n => ({
                ...n,
                startTime: n.startTime * secondsPerBeat,
                duration: n.duration * secondsPerBeat
            }));

            buffer = await renderSequence(ctx, secondsNotes, vocalParams);
        }

        // Apply Global Reverb
        if (globalParams.reverbMix > 0) {
            // Re-create context for reverb or use existing logic (engine handles it)
            // The current engine applies reverb to the passed buffer using a new context inside applyReverb
            const reverbCtx = new OfflineAudioContext(1, buffer.length, sampleRate);
            buffer = await applyReverb(reverbCtx, buffer, globalParams.reverbMix, globalParams.reverbDecay);
        }

        setGeneratedBuffer(buffer);
        drawWaveform(buffer);
      } catch (e) {
        console.error(e);
        alert("Error generating audio");
      } finally {
        setIsGenerating(false);
      }
    }, 50);
  };

  // Improved Syllabifier (Heuristic for Latin/PT/EN languages)
  const syllabify = (text: string) => {
      // Logic: 
      // 1. Match optional consonants
      // 2. Match strict vowel group
      // 3. Match optional coda (consonants at end or before another consonant)
      const regex = /[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]*[aeiouyáéíóúãõâêîôûàèìòùäëïöü]+(?:[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]*$|[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ](?=[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]))?/gi;
      const match = text.match(regex);
      return match || [text];
  };

  const handleApplyLyrics = () => {
      if (!lyricsInput.trim()) {
          setShowLyricsModal(false);
          return;
      }

      addToHistory();

      // 1. Initial split by delimiters to get "words"
      const rawWords = lyricsInput
          .replace(/[\n\r]/g, ' ')
          .split(/[\s-]+/)
          .filter(s => s.length > 0);

      // 2. Auto-Syllabify words to ensure they fit well
      let syllables: string[] = [];
      rawWords.forEach(word => {
          // If word is longer than 2 chars, try to split it
          if (word.length > 2) {
              syllables.push(...syllabify(word));
          } else {
              syllables.push(word);
          }
      });

      if (syllables.length === 0) return;

      // 3. Clone and Sort Notes
      let tempNotes = [...notes].sort((a, b) => a.startTime - b.startTime);

      // 4. Smart Split Logic
      // Distribute these syllables across notes. 
      // If we need more notes, split the biggest ones.
      let iterations = 0;
      const MAX_ITERATIONS = 500; 

      while (syllables.length > tempNotes.length && iterations < MAX_ITERATIONS) {
          let maxDur = 0;
          let maxIdx = -1;

          // Find largest note to split
          for (let i = 0; i < tempNotes.length; i++) {
              if (tempNotes[i].duration > maxDur) {
                  maxDur = tempNotes[i].duration;
                  maxIdx = i;
              }
          }

          if (maxIdx !== -1) {
              const target = tempNotes[maxIdx];
              const halfDur = target.duration / 2;

              // Only split if resulting note is usable (> 1/64th usually, here stricter)
              // But if we REALLY need space for text, we might push it.
              if (halfDur >= 0.03125) {
                   const noteA = { ...target, duration: halfDur };
                   const noteB = { 
                       ...target, 
                       id: Math.random().toString(36).substr(2, 9),
                       startTime: target.startTime + halfDur,
                       duration: halfDur,
                       lyric: '' 
                   };
                   tempNotes.splice(maxIdx, 1, noteA, noteB);
              } else {
                  // Cannot split notes any smaller
                  break; 
              }
          } else {
              break;
          }
          iterations++;
      }

      // 5. Assign Syllables
      const finalNotes = tempNotes.map((note, index) => {
          if (index < syllables.length) {
              return { ...note, lyric: syllables[index] };
          }
          return { ...note, lyric: '' }; // Clear excess notes or keep previous? Clearing is cleaner for "Apply"
      });

      setNotes(finalNotes);
      setLyricsInput("");
      setShowLyricsModal(false);
  };

  const handleMidiUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                addToHistory(); // Save current state before overwrite
                const parsedNotes = parseMidiFile(ev.target.result as ArrayBuffer);
                setNotes(parsedNotes);
                setMode('SEQUENCER'); // Auto switch
                alert(`Imported ${parsedNotes.length} notes!`);
            } catch (err) {
                console.error(err);
                alert("Failed to parse file. Make sure it is a valid MIDI (.mid) or RTX/RTTTL file.");
            }
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportJson = () => {
    const data = {
        version: 1,
        timestamp: Date.now(),
        notes: notes,
        vocalParams: vocalParams,
        globalParams: globalParams
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `project_${Date.now()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                const data = JSON.parse(ev.target.result as string);
                addToHistory();
                if (data.notes) setNotes(data.notes);
                if (data.vocalParams) setVocalParams(data.vocalParams);
                if (data.globalParams) setGlobalParams(data.globalParams);
                setMode('SEQUENCER');
                alert("Project loaded!");
            } catch (err) {
                console.error(err);
                alert("Invalid project file.");
            }
        }
    };
    reader.readAsText(file);
  };


  const handlePlay = () => {
    if (!generatedBuffer) return;

    if (!audioContextRef.current) {
      audioContextRef.current = new AudioContext();
    }

    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') ctx.resume();

    const source = ctx.createBufferSource();
    source.buffer = generatedBuffer;
    source.connect(ctx.destination);

    source.onended = () => setIsPlaying(false);

    setIsPlaying(true);
    source.start();
  };

  const handleDownload = () => {
    if (!generatedBuffer) return;
    const blob = bufferToWav(generatedBuffer);
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.style.display = 'none';
    a.href = url;

    const name = `vocalstudio_${mode.toLowerCase()}_${Date.now()}.wav`;

    a.download = name;
    document.body.appendChild(a);
    a.click();

    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  };

  const drawWaveform = (buffer: AudioBuffer) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / width);
    const amp = height / 2;

    ctx.clearRect(0, 0, width, height);
    ctx.beginPath();
    ctx.moveTo(0, amp);

    // Draw visual styling
    ctx.strokeStyle = '#38bdf8'; // Sky blue
    ctx.lineWidth = 2;

    for (let i = 0; i < width; i++) {
      let min = 1.0;
      let max = -1.0;
      for (let j = 0; j < step; j++) {
        const datum = data[(i * step) + j];
        if (datum < min) min = datum;
        if (datum > max) max = datum;
      }
      ctx.lineTo(i, (1 + min) * amp);
      ctx.lineTo(i, (1 + max) * amp);
    }

    ctx.stroke();
  };

  // Determine viewport duration for PianoRoll based on notes
  const seqDurationBeats = notes.length > 0 
    ? notes.reduce((max, n) => Math.max(max, n.startTime + n.duration), 0) + 8 
    : 32;

  return (
    <div className="min-h-screen bg-synth-dark text-slate-200 pb-40 font-sans selection:bg-synth-pop selection:text-white">

      {/* Header */}
      <header className="p-4 bg-synth-dark/90 backdrop-blur sticky top-0 z-10 border-b border-synth-grid flex justify-between items-center shadow-lg">
        <div>
          <h1 className="text-xl font-bold bg-gradient-to-r from-synth-accent to-synth-pop bg-clip-text text-transparent flex items-center gap-2">
            <Mic size={24} className="text-synth-accent" />
            VocalStudio
          </h1>
          <p className="text-[10px] text-slate-500 tracking-wide font-mono">DSP VOCAL WORKSTATION</p>
        </div>

        {/* Mode Switcher */}
        <div className="flex bg-synth-panel rounded-lg p-1 border border-synth-grid gap-1">
            <button
                onClick={() => setMode('LIVE')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'LIVE' ? 'bg-synth-accent text-synth-dark' : 'text-slate-500'}`}
            >
                <Music size={12} />
                LIVE
            </button>
            <button
                onClick={() => setMode('SEQUENCER')}
                className={`px-3 py-1 rounded text-[10px] font-bold flex items-center gap-1 ${mode === 'SEQUENCER' ? 'bg-synth-pop text-white' : 'text-slate-500'}`}
            >
                <Piano size={12} />
                SEQ
            </button>
        </div>
      </header>

      <main className="p-4 max-w-lg mx-auto w-full space-y-5 relative">

        {/* Visualization Area */}
        <div className="bg-black/40 rounded-2xl border border-synth-grid p-4 h-24 flex items-center justify-center relative overflow-hidden group">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-synth-panel/50 to-transparent opacity-50" />
          <canvas 
            ref={canvasRef} 
            width={600} 
            height={200} 
            className="w-full h-full relative z-10 opacity-90"
          />
        </div>

        {/* --- SEQUENCER MODE UI --- */}
        {mode === 'SEQUENCER' && (
             <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex justify-between items-center">
                    <h2 className="text-sm font-bold text-synth-pop flex items-center gap-2">
                        <Piano size={16} />
                        PIANO ROLL
                    </h2>
                    <div className="flex gap-2">
                         <input 
                            type="file" 
                            accept=".mid,.midi,.rtx,.txt" 
                            className="hidden" 
                            ref={fileInputRef}
                            onChange={handleMidiUpload}
                        />
                         <input 
                            type="file" 
                            accept=".json" 
                            className="hidden" 
                            ref={jsonInputRef}
                            onChange={handleImportJson}
                        />
                        <button 
                            onClick={() => setShowLyricsModal(true)}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700 text-synth-accent font-bold"
                        >
                            <Type size={12} />
                            LYRICS
                        </button>
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700"
                        >
                            <Upload size={10} />
                            MIDI
                        </button>
                    </div>
                </div>

                <PianoRoll 
                    notes={notes}
                    setNotes={setNotes}
                    durationBeats={seqDurationBeats}
                    onUndo={handleUndo}
                    onRedo={handleRedo}
                    addToHistory={addToHistory}
                    canUndo={history.length > 0}
                    canRedo={future.length > 0}
                />
             </div>
        )}

        {/* --- LIVE MODE UI --- */}
        {mode === 'LIVE' && (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="bg-synth-panel p-4 rounded-xl border border-synth-grid flex justify-between items-center">
                    <span className="text-xs font-bold text-synth-accent uppercase">Base Pitch</span>
                    <div className="flex gap-2 items-center bg-synth-dark rounded-lg p-1 border border-synth-grid/50">
                        <select 
                            value={selectedNote}
                            onChange={(e) => setSelectedNote(e.target.value)}
                            className="bg-transparent text-white font-mono text-xs font-bold outline-none"
                        >
                            {Object.keys(NOTE_FREQUENCIES).map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                        <div className="w-px h-4 bg-synth-grid"></div>
                        <select 
                            value={selectedOctave}
                            onChange={(e) => setSelectedOctave(parseInt(e.target.value))}
                            className="bg-transparent text-synth-accent font-mono text-xs font-bold outline-none"
                        >
                            {[1,2,3,4,5,6].map(o => <option key={o} value={o}>{o}</option>)}
                        </select>
                    </div>
                </div>

                <div className="mb-4">
                    <label className="text-[10px] font-bold text-synth-accent uppercase mb-1 block">Sequencer Text</label>
                    <textarea
                        value={vocalParams.text}
                        onChange={(e) => setVocalParams(p => ({ ...p, text: e.target.value }))}
                        className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-lg font-mono tracking-widest text-white focus:border-synth-pop outline-none h-24"
                        placeholder="Type phonemes..."
                    />
                </div>
            </div>
        )}

        {/* Global Config (Shared) */}
        <div className="bg-synth-panel/30 p-4 rounded-xl border border-synth-grid/50">
          <div className="flex items-center gap-2 mb-3 text-synth-accent">
            <Settings size={16} />
            <span className="text-xs font-bold uppercase">Voice Parameters</span>
          </div>

           <div className="mb-4">
              <select
                value={vocalParams.preset}
                onChange={(e) => setVocalParams(p => ({ ...p, preset: e.target.value as VocalPreset }))}
                className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-sm text-white focus:border-synth-pop outline-none appearance-none"
              >
                {Object.values(VocalPreset).map(preset => (
                  <option key={preset} value={preset}>{preset}</option>
                ))}
              </select>
            </div>

            <div className="mb-4 flex bg-synth-panel rounded-xl border border-synth-grid p-1">
                  {Object.values(VocalMode).map(m => (
                    <button
                      key={m}
                      onClick={() => setVocalParams(p => ({...p, mode: m as VocalMode}))}
                      className={`flex-1 py-2 text-xs font-bold rounded-lg uppercase transition-all ${
                          vocalParams.mode === m 
                          ? 'bg-synth-pop text-white shadow-md' 
                          : 'text-slate-400'
                      }`}
                    >
                      {m}
                    </button>
                  ))}
            </div>

          <div className="space-y-4">
            <div className="flex gap-2">
                <ControlSlider
                    label="BPM"
                    value={globalParams.bpm}
                    min={60}
                    max={200}
                    step={1}
                    onChange={(v) => setGlobalParams(p => ({...p, bpm: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                <ControlSlider
                    label={mode === 'LIVE' ? 'Duration (s)' : 'View Size'}
                    value={globalParams.duration}
                    min={1.0}
                    max={30.0}
                    step={1.0}
                    unit=""
                    onChange={(v) => setGlobalParams(p => ({...p, duration: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>

            <div className="flex gap-2">
                <ControlSlider
                    label="Humanize"
                    value={vocalParams.humanize}
                    min={0}
                    max={1.0}
                    onChange={(v) => setVocalParams(p => ({...p, humanize: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                 <ControlSlider
                    label="Reverb"
                    value={globalParams.reverbMix}
                    min={0}
                    max={0.8}
                    onChange={(v) => setGlobalParams(p => ({...p, reverbMix: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>
          </div>
        </div>

        {/* LYRICS MODAL */}
        {showLyricsModal && (
            <div className="absolute inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                <div className="bg-synth-panel border border-synth-grid rounded-2xl w-full max-w-sm p-4 shadow-2xl flex flex-col gap-3">
                    <div className="flex justify-between items-center border-b border-synth-grid pb-2">
                        <h3 className="text-sm font-bold text-white flex items-center gap-2">
                            <Type size={16} className="text-synth-accent" />
                            ADAPT LYRICS TO NOTES
                        </h3>
                        <button onClick={() => setShowLyricsModal(false)} className="text-slate-400 hover:text-white">
                            <X size={18} />
                        </button>
                    </div>
                    <p className="text-[10px] text-slate-400">
                        Paste your lyrics here. The app will auto-split long words and notes to ensure better intelligibility.
                    </p>
                    <textarea 
                        className="w-full h-32 bg-synth-dark border border-synth-grid rounded-xl p-3 text-white focus:border-synth-accent outline-none font-mono text-sm"
                        placeholder="Paste lyrics (e.g. 'Eu quero comer batata')..."
                        value={lyricsInput}
                        onChange={(e) => setLyricsInput(e.target.value)}
                    />
                    <div className="flex gap-2">
                         <button 
                            onClick={() => setShowLyricsModal(false)}
                            className="flex-1 py-2 rounded-xl text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600"
                        >
                            CANCEL
                        </button>
                        <button 
                            onClick={handleApplyLyrics}
                            className="flex-1 py-2 rounded-xl text-xs font-bold bg-synth-accent text-synth-dark hover:bg-sky-300 flex items-center justify-center gap-2"
                        >
                            <Check size={14} />
                            APPLY
                        </button>
                    </div>
                </div>
            </div>
        )}

      </main>

      {/* Sticky Action Footer */}
      <footer className="fixed bottom-0 left-0 right-0 bg-synth-dark/95 backdrop-blur border-t border-synth-grid p-4 z-50 safe-area-bottom shadow-[0_-5px_20px_rgba(0,0,0,0.5)]">
        <div className="max-w-lg mx-auto flex gap-4">
            {/* Project Buttons */}
            <div className="flex flex-col gap-1">
                <button
                    onClick={handleExportJson}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Export Project"
                >
                    <Save size={16} />
                </button>
                 <button
                    onClick={() => jsonInputRef.current?.click()}
                    className="bg-synth-panel/80 p-2 rounded-lg border border-synth-grid text-slate-400 hover:text-white"
                    title="Import Project"
                >
                    <FileJson size={16} />
                </button>
            </div>

          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className="flex-1 bg-synth-panel hover:bg-slate-700 text-white font-bold py-2 px-4 rounded-2xl border border-synth-grid shadow-lg active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
          >
            <Activity className={isGenerating ? "animate-spin" : ""} size={20} />
            <span className="text-[10px] uppercase tracking-wider">{isGenerating ? "Wait..." : (mode === 'SEQUENCER' ? "RENDER SEQ" : "RENDER")}</span>
          </button>

          {generatedBuffer && (
            <>
              <button
                onClick={handlePlay}
                className={`w-14 bg-synth-accent text-synth-dark font-bold rounded-2xl flex items-center justify-center shadow-[0_0_15px_rgba(56,189,248,0.3)] active:scale-95 transition-transform ${isPlaying ? 'opacity-80' : ''}`}
              >
                <Play fill={isPlaying ? "currentColor" : "none"} size={24} />
              </button>

              <button
                onClick={handleDownload}
                className="flex-1 bg-synth-pop hover:bg-pink-500 text-white font-bold py-2 px-4 rounded-2xl shadow-[0_0_15px_rgba(244,114,182,0.3)] active:scale-95 transition-transform flex flex-col justify-center items-center gap-1"
              >
                <Download size={20} />
                 <span className="text-[10px] uppercase tracking-wider">SAVE WAV</span>
              </button>
            </>
          )}
        </div>
      </footer>

    </div>
  );
};

export default App;

import { 
  VocalPreset, VocalMode, VocalParams, SequencerNote
} from '../types';

// Constants
export const NOTE_FREQUENCIES: Record<string, number> = {
  'C': 16.35, 'C#': 17.32, 'D': 18.35, 'D#': 19.45, 'E': 20.60, 'F': 21.83,
  'F#': 23.12, 'G': 24.50, 'G#': 25.96, 'A': 27.50, 'A#': 29.14, 'B': 30.87
};

export const getFrequency = (note: string, octave: number): number => {
  const base = NOTE_FREQUENCIES[note] || 16.35;
  return base * Math.pow(2, octave);
};

export const midiToFreq = (midi: number): number => {
  return 440 * Math.pow(2, (midi - 69) / 12);
};

// Helper: Convert AudioBuffer to WAV Blob
export const bufferToWav = (buffer: AudioBuffer): Blob => {
  const numOfChan = buffer.numberOfChannels;
  const length = buffer.length * numOfChan * 2 + 44;
  const bufferArr = new ArrayBuffer(length);
  const view = new DataView(bufferArr);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write RIFF chunk descriptor
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  // write fmt sub-chunk
  setUint32(0x20746d66); // "fmt "
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(buffer.sampleRate);
  setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this parser)

  // write data sub-chunk
  setUint32(0x61746164); // "data"
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for (i = 0; i < buffer.numberOfChannels; i++)
    channels.push(buffer.getChannelData(i));

  while (pos < buffer.length) {
    for (i = 0; i < numOfChan; i++) {
      // clamp
      sample = Math.max(-1, Math.min(1, channels[i][pos])); 
      // scale to 16-bit signed int
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; 
      view.setInt16(44 + offset, sample, true);
      offset += 2;
    }
    pos++;
  }

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }

  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }

  return new Blob([bufferArr], { type: 'audio/wav' });
};

/**
 * Convolution Reverb Generator (Space/Resonance Model)
 */
export const applyReverb = async (ctx: OfflineAudioContext, inputBuffer: AudioBuffer, mix: number, decayTime: number): Promise<AudioBuffer> => {
  if (mix <= 0) return inputBuffer;

  const sampleRate = ctx.sampleRate;
  const length = inputBuffer.length;

  // 1. Generate Impulse Response (Exponential Decay Noise)
  // Model: y(t) = Noise(t) * e^(-t / T)
  const irLength = sampleRate * decayTime;
  const irBuffer = ctx.createBuffer(1, irLength, sampleRate);
  const irData = irBuffer.getChannelData(0);

  for (let i = 0; i < irLength; i++) {
    // White noise * exponential decay
    irData[i] = (Math.random() * 2 - 1) * Math.pow(1 - (i / irLength), 4);
  }

  // 2. Convolve
  const convCtx = new OfflineAudioContext(1, length, sampleRate);
  const source = convCtx.createBufferSource();
  source.buffer = inputBuffer;

  const convolver = convCtx.createConvolver();
  convolver.buffer = irBuffer;
  convolver.normalize = true;

  const dryGain = convCtx.createGain();
  const wetGain = convCtx.createGain();

  dryGain.gain.value = 1 - (mix * 0.5);
  wetGain.gain.value = mix;

  source.connect(dryGain);
  dryGain.connect(convCtx.destination);

  source.connect(convolver);
  convolver.connect(wetGain);
  wetGain.connect(convCtx.destination);

  source.start();
  return await convCtx.startRendering();
};

