// PHONETIC DEFINITIONS
interface PhonemeDef {
  formants: number[];
  gain: number;
  noise: number; // 0 to 1 mix of noise
  noiseType?: 'white' | 'pink' | 'highpass';
  durationScale: number; // 1.0 = standard, 0.5 = fast (consonant)
}

// 1. Dictionary of Phonemes (Oral, Nasal, Consonant Approximations)
const PHONEME_LIB: Record<string, PhonemeDef> = {
