                           <span className="text-[9px] text-synth-accent font-bold uppercase">Slide</span>
                           <input 
                              type="range" 
                              min="0" max="1" step="0.05"
                              value={vocalParams.glide} 
                              onChange={(e) => setVocalParams(p => ({...p, glide: parseFloat(e.target.value)}))}
                              className="w-16 h-1 bg-synth-dark rounded-lg appearance-none cursor-pointer accent-synth-pop"
                              title={`Glide: ${vocalParams.glide}`}
                           />
                        </div>
                    </div>

                    <div className="flex gap-2">
                         <input 
                            type="file" 
                            accept=".mid,.midi,.rtx,.txt" 
                            className="hidden" 
                            ref={fileInputRef}
                            onChange={handleMidiUpload}
                        />
                         <input 
                            type="file" 
                            accept=".json" 
                            className="hidden" 
                            ref={jsonInputRef}
                            onChange={handleImportJson}
                        />
                        <button 
                            onClick={() => setShowLyricsModal(true)}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700 text-synth-accent font-bold"
                        >
                            <Type size={12} />
                            LYRICS
                        </button>
                        <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="text-[10px] bg-synth-panel border border-synth-grid px-3 py-1 rounded flex items-center gap-1 hover:bg-slate-700"
                        >
                            <Upload size={10} />
                            MIDI
                        </button>
                    </div>
                </div>

                <PianoRoll 
                    notes={notes}
                    setNotes={setNotes}
                    durationBeats={seqDurationBeats}
                    onUndo={handleUndo}
                    onRedo={handleRedo}
                    addToHistory={addToHistory}
                    canUndo={history.length > 0}
                    canRedo={future.length > 0}
                    onEditPitch={handleOpenPitchEditor}
                />
             </div>
        )}

        {mode === 'LIVE' && (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="bg-synth-panel p-4 rounded-xl border border-synth-grid flex justify-between items-center">
                    <span className="text-xs font-bold text-synth-accent uppercase">Base Pitch</span>
                    <div className="flex gap-2 items-center bg-synth-dark rounded-lg p-1 border border-synth-grid/50">
                        <select 
                            value={selectedNote}
                            onChange={(e) => setSelectedNote(e.target.value)}
                            className="bg-transparent text-white font-mono text-xs font-bold outline-none"
                        >
                            {Object.keys(NOTE_FREQUENCIES).map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                        <div className="w-px h-4 bg-synth-grid"></div>
                        <select 
                            value={selectedOctave}
                            onChange={(e) => setSelectedOctave(parseInt(e.target.value))}
                            className="bg-transparent text-synth-accent font-mono text-xs font-bold outline-none"
                        >
                            {[1,2,3,4,5,6].map(o => <option key={o} value={o}>{o}</option>)}
                        </select>
                    </div>
                </div>

                <div className="mb-4">
                    <label className="text-[10px] font-bold text-synth-accent uppercase mb-1 block">Sequencer Text</label>
                    <textarea
                        value={vocalParams.text}
                        onChange={(e) => setVocalParams(p => ({ ...p, text: e.target.value }))}
                        className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-lg font-mono tracking-widest text-white focus:border-synth-pop outline-none h-24"
                        placeholder="Type phonemes..."
                    />
                </div>
            </div>
        )}

        <div className="bg-synth-panel/30 p-4 rounded-xl border border-synth-grid/50">
          <div className="flex items-center gap-2 mb-3 text-synth-accent">
            <Settings size={16} />
            <span className="text-xs font-bold uppercase">Voice Parameters</span>
          </div>

           <div className="mb-4">
              <select
                value={vocalParams.preset}
                onChange={(e) => setVocalParams(p => ({ ...p, preset: e.target.value as VocalPreset }))}
                className="w-full bg-synth-panel border border-synth-grid rounded-xl p-3 text-sm text-white focus:border-synth-pop outline-none appearance-none"
              >
                {Object.values(VocalPreset).map(preset => (
                  <option key={preset} value={preset}>{preset}</option>
                ))}
              </select>
            </div>

            <div className="mb-4 flex bg-synth-panel rounded-xl border border-synth-grid p-1">
                  {Object.values(VocalMode).map(m => (
                    <button
                      key={m}
                      onClick={() => setVocalParams(p => ({...p, mode: m as VocalMode}))}
                      className={`flex-1 py-2 text-xs font-bold rounded-lg uppercase transition-all ${
                          vocalParams.mode === m 
                          ? 'bg-synth-pop text-white shadow-md' 
                          : 'text-slate-400'
                      }`}
                    >
                      {m}
                    </button>
                  ))}
            </div>

          <div className="space-y-4">
            <div className="flex gap-2">
                <ControlSlider
                    label="BPM"
                    value={globalParams.bpm}
                    min={60}
                    max={200}
                    step={1}
                    onChange={(v) => setGlobalParams(p => ({...p, bpm: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                <ControlSlider
                    label={mode === 'LIVE' ? 'Duration (s)' : 'View Size'}
                    value={globalParams.duration}
                    min={1.0}
                    max={30.0}
                    step={1.0}
                    unit=""
                    onChange={(v) => setGlobalParams(p => ({...p, duration: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>

            <div className="flex gap-2">
                 <ControlSlider
                    label="Glide"
                    value={vocalParams.glide}
                    min={0}
                    max={1}
                    step={0.05}
                    onChange={(v) => setVocalParams(p => ({...p, glide: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
                 <ControlSlider
                    label="Reverb"
                    value={globalParams.reverbMix}
                    min={0}
                    max={0.8}
                    onChange={(v) => setGlobalParams(p => ({...p, reverbMix: v}))}
                    className="flex-1 bg-transparent border-none p-0"
                />
            </div>
          </div>
        </div>

        {/* LYRICS MODAL */}
        {showLyricsModal && (
            <div className="absolute inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
