/**
 * Enhanced Vocal Synthesis with Text Sequencing
 */
export const renderVocals = async (ctx: OfflineAudioContext, params: VocalParams, duration: number, baseFreq: number, startFreq?: number): Promise<AudioBuffer> => {
  // 1. Prepare Text & Phonemes via Parser
  const phonemes = textToPhonemes(params.text);

  // 2. Calculate Timing (Variable Duration based on Phoneme Type)
  let totalUnits = 0;
  const phonemeSequence = phonemes.map(p => {
    const def = PHONEME_LIB[p] || PHONEME_LIB['a'];
    totalUnits += def.durationScale;
    return { char: p, def };
  });

  // If no text, avoid division by zero
  if (totalUnits === 0) totalUnits = 1;

  const unitTime = duration / totalUnits;

  // 3. Load Preset Config & Frequency
  const presetData = VOCAL_PRESETS_DATA[params.preset] || VOCAL_PRESETS_DATA[VocalPreset.MALE_BR];

  // Use user provided baseFreq instead of preset default baseFreq unless mode forces it
  // We apply the preset pitch multiplier if any, but base it on the Global Note.
  const f0 = baseFreq * params.pitch;

  // 4. Build Source Chain
  const master = ctx.createGain();
  master.connect(ctx.destination);

  // Main Oscillator
  const osc = ctx.createOscillator();
  osc.type = presetData.type || 'sawtooth';

  // Pitch Logic (Speech vs Singing) & Automation
  if (startFreq && params.glide > 0) {
      // GLIDE / PORTAMENTO
      // Ramp from startFreq to f0
      osc.frequency.setValueAtTime(startFreq, 0);
      // Glide time is a fraction of note duration or fixed max
      // Map glide 0..1 to approx 0..0.5s max
      const glideTime = Math.min(duration, params.glide * 0.5); 
      // Use exponential ramp for natural slide
      osc.frequency.exponentialRampToValueAtTime(f0, glideTime);
  } else {
      osc.frequency.setValueAtTime(f0, 0);
  }

  // Apply Pitch Bend (Curve) via Detune (Works on top of frequency automation)
  if (params.pitchPoints && params.pitchPoints.length > 0) {
     const sorted = [...params.pitchPoints].sort((a,b) => a.t - b.t);
     if (sorted[0].t > 0) {
         osc.detune.setValueAtTime(0, 0);
     }
     sorted.forEach((pt, i) => {
          const t = pt.t * duration;
          const cents = pt.v * 100; 
          if (t === 0) {
            osc.detune.setValueAtTime(cents, 0);
          } else {
            osc.detune.linearRampToValueAtTime(cents, t);
          }
     });
  }

  // If Speech Mode (TTS), we apply a prosody curve
  // Standard prosody: Slight rise at start, gradual fall at end.
  // Variations on stressed syllables can be added in loop.
  if (params.mode === VocalMode.SPEECH) {
    const startPitch = f0 * 1.1;
    const endPitch = f0 * 0.85;
    osc.frequency.setValueAtTime(startPitch, 0);
    // Add small variations per phoneme in the loop, but general trend is falling
    osc.frequency.exponentialRampToValueAtTime(endPitch, duration);
  }

  // Pitch Modulations (Vibrato / Drift / FM / Flutter)
  if (presetData.vibrato && params.mode !== VocalMode.SPEECH) {
     const lfo = ctx.createOscillator();
     lfo.frequency.value = presetData.vibrato.rate;
     const lfoGain = ctx.createGain();
     // If pitch bending, vibrato applies on top
     lfoGain.gain.value = f0 * presetData.vibrato.depth;
     lfo.connect(lfoGain);
     lfoGain.connect(osc.frequency);
     lfo.start(0);
  }

  // HUMAN INSTABILITY (Slow Drift + Error)
  if (params.humanize > 0) {
    // We use a low freq oscillator to simulate "human error" in holding pitch
    const driftOsc = ctx.createOscillator();
    driftOsc.frequency.value = 0.5 + (Math.random() * 2); // Slow drift 0.5Hz - 2.5Hz
    const driftGain = ctx.createGain();
    // Drifts up to +/- semitone at max humanize
    driftGain.gain.value = f0 * 0.06 * params.humanize; 
    driftOsc.connect(driftGain);
    driftGain.connect(osc.frequency);
    driftOsc.start(0);
  }

  if (presetData.flutter) {
      const flutterOsc = ctx.createOscillator();
      flutterOsc.frequency.value = 0.3;
      const fGain = ctx.createGain();
      fGain.gain.value = 10;
      flutterOsc.connect(fGain);
      fGain.connect(osc.frequency);
      flutterOsc.start(0);
  }

  if (presetData.fm) {
      const fmOsc = ctx.createOscillator();
      fmOsc.frequency.value = presetData.fm.rate;
      const fmGain = ctx.createGain();
      fmGain.gain.value = presetData.fm.depth;
      fmOsc.connect(fmGain);
      fmGain.connect(osc.frequency);
      fmOsc.start(0);
  }

  // OSC GAIN (Controlled by Phoneme Envelope)
  const oscGainNode = ctx.createGain();
  // We will automate this gain
  oscGainNode.gain.setValueAtTime(0, 0); 
  osc.connect(oscGainNode);

  // NOISE SOURCE
  const noiseBuff = ctx.createBuffer(1, ctx.sampleRate * duration, ctx.sampleRate);
  const nd = noiseBuff.getChannelData(0);
  for(let i=0; i<nd.length; i++) nd[i] = (Math.random() * 2 - 1) * 0.5;
  const noiseSrc = ctx.createBufferSource();
  noiseSrc.buffer = noiseBuff;

  // Noise Shaping Filter (for fricatives like 's' vs 'sh')
  const noiseFilter = ctx.createBiquadFilter();
  noiseFilter.type = 'highpass';
  noiseFilter.frequency.value = 1000; // Default
  noiseSrc.connect(noiseFilter);

  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0, 0);
  noiseFilter.connect(noiseGain);

  // Combine Sources
  const sourceSum = ctx.createGain();
  oscGainNode.connect(sourceSum);
  noiseGain.connect(sourceSum);

  // Sub-harmonics
  if (presetData.subHarmonics) {
      const subOsc = ctx.createOscillator();
      subOsc.type = 'square';
      subOsc.frequency.value = f0 / 2;
      const subGain = ctx.createGain();
      subGain.gain.value = 0.5;
      subOsc.connect(subGain);
      subGain.connect(sourceSum);
      subOsc.start(0);
  }

  // 5. Formant Filters (Parallel Bandpass)
  const filterOut = ctx.createGain();

  const filters = [0,1,2].map(i => {
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 4 + i; 
    const g = ctx.createGain();
    g.gain.value = 1.0; 
    sourceSum.connect(f);
    f.connect(g);
    g.connect(filterOut);
    return f;
  });

  // Nasal Branch
  let nasalOut: GainNode | null = null;
  const nasalF = ctx.createBiquadFilter();
  nasalF.type = 'bandpass';
  nasalF.frequency.value = 400;
  nasalF.Q.value = 3;
  nasalOut = ctx.createGain();
  nasalOut.gain.value = 0; // Controlled by sequence
  sourceSum.connect(nasalF);
  nasalF.connect(nasalOut);
  nasalOut.connect(master);

  // 6. Automation Sequencing
  // Word Gap Articulation Gain
  const articulationGain = ctx.createGain();
  articulationGain.gain.value = 1;
  filterOut.connect(articulationGain);

  let currentTime = 0;
  const rampMethod = presetData.steps ? 'setValueAtTime' : 'linearRampToValueAtTime'; // Linear for formants usually better for consonants

  phonemeSequence.forEach((item, idx) => {
    const { char, def } = item;
    const itemDur = def.durationScale * unitTime;
    const endTime = currentTime + itemDur;

    // Pitch automation for Speech Mode (Micro-prosody)
    if (params.mode === VocalMode.SPEECH) {
        // Vowels slightly higher/stable, consonants might drop
        // Random intonation drift based on Humanize
        const variance = (Math.random() * 2 - 1) * 0.1 * params.humanize;
    }

    // -- FORMANTS --
    let [t1, t2, t3] = def.formants;
    const scale = presetData.formantScale || 1.0;
    const shift = params.formantShift || 1.0;
    t1 *= scale * shift;
    t2 *= scale * shift;
    t3 *= scale * shift;

    // Clamp
    t1 = Math.max(50, Math.min(10000, t1));
    t2 = Math.max(50, Math.min(10000, t2));
    t3 = Math.max(50, Math.min(10000, t3));

    // Apply Formants
    if (idx === 0) {
        filters[0].frequency.setValueAtTime(t1, currentTime);
        filters[1].frequency.setValueAtTime(t2, currentTime);
        filters[2].frequency.setValueAtTime(t3, currentTime);
    } else {
        filters[0].frequency[rampMethod](t1, currentTime + (itemDur * 0.5));
        filters[1].frequency[rampMethod](t2, currentTime + (itemDur * 0.5));
        filters[2].frequency[rampMethod](t3, currentTime + (itemDur * 0.5));
    }

    // -- SOURCE MIXING (Osc vs Noise) --
    // Base Osc Level from preset
    const presetOscLevel = presetData.oscGain !== undefined ? presetData.oscGain : (1 - (presetData.breath || 0));
    // Def Osc Level (0 for consonants like p, t, k, s)
    const defOscLevel = def.gain; 
    const finalOscLevel = presetOscLevel * defOscLevel;

    oscGainNode.gain.setTargetAtTime(finalOscLevel, currentTime, 0.01);

    // Noise Level
    const presetBreath = (presetData.breath || 0) + params.breathiness * 0.2;
    // Def Noise Level (High for f, s, sh)
    const defNoiseLevel = def.noise;
    // Max of preset breath or consonant noise
    const finalNoiseLevel = Math.max(presetBreath, defNoiseLevel * 0.8);

    noiseGain.gain.setTargetAtTime(finalNoiseLevel, currentTime, 0.01);

    // Noise Color
    if (def.noiseType === 'highpass') {
        noiseFilter.frequency.setTargetAtTime(4000, currentTime, 0.01);
    } else if (def.noiseType === 'pink') {
        noiseFilter.frequency.setTargetAtTime(1000, currentTime, 0.01);
    } else {
        noiseFilter.frequency.setTargetAtTime(100, currentTime, 0.01); // White/Full
    }

    // -- NASAL MIX --
    const nasalTarget = (char.match(/[ãẽĩõũmnɲ]/)) ? (presetData.nasal || 0.4) : 0;
    nasalOut!.gain.setTargetAtTime(nasalTarget, currentTime, 0.05);

    // -- WORD GAP / PAUSE --
    if (char === ' ') {
        if (params.wordGap > 0) {
           articulationGain.gain.setTargetAtTime(0, currentTime, 0.005);
        }
    } else {
        if (params.wordGap > 0) {
           articulationGain.gain.setTargetAtTime(1, currentTime, 0.01);
        }
    }

    currentTime = endTime;
  });

  // 7. Post-Filter Effects
  let postFx = articulationGain; 
  if (presetData.amRate) {
      const am = ctx.createGain();
      const lfo = ctx.createOscillator();
      lfo.frequency.value = presetData.amRate;
      const lfoG = ctx.createGain();
      lfoG.gain.value = presetData.amDepth;
      const offset = ctx.createConstantSource();
      offset.offset.value = 1;

      lfo.connect(lfoG);
      lfoG.connect(am.gain);
      offset.connect(am.gain);

      articulationGain.disconnect();
      articulationGain.connect(am);
      postFx = am;

      lfo.start(0);
      offset.start(0);
  }

  if (presetData.bandpass) {
      const bpLow = ctx.createBiquadFilter();
      bpLow.type = 'highpass';
      bpLow.frequency.value = presetData.bandpass[0];
      const bpHigh = ctx.createBiquadFilter();
      bpHigh.type = 'lowpass';
      bpHigh.frequency.value = presetData.bandpass[1];

      postFx.connect(bpLow);
      bpLow.connect(bpHigh);
      postFx = bpHigh as unknown as GainNode; 
  }

  postFx.connect(master);

  osc.start(0);
  noiseSrc.start(0);
  osc.stop(duration);
  noiseSrc.stop(duration);

  const rendered = await ctx.startRendering();

  // 8. Buffer Post-Process
  const data = rendered.getChannelData(0);
  const len = data.length;

  if (presetData.roughness || params.jitter > 0) {
      const rAmount = (presetData.roughness || 0) + params.jitter;
      for(let i=0; i<len; i++) {
          data[i] *= 1 + ((Math.random() - 0.5) * rAmount);
      }
  }

  if (presetData.distortion) {
      const k = presetData.distortion;
      for(let i=0; i<len; i++) {
          data[i] = Math.tanh(k * data[i]);
      }
  } else if (presetData.clip) {
      const limit = presetData.clip;
      for(let i=0; i<len; i++) {
          if (data[i] > limit) data[i] = limit;
          if (data[i] < -limit) data[i] = -limit;
      }
  } else {
      for(let i=0; i<len; i++) data[i] = Math.tanh(data[i]);
  }

  return rendered;
};

/**
 * Render a full sequence of notes with lyrics.
 */
export const renderSequence = async (ctx: OfflineAudioContext, notes: SequencerNote[], params: VocalParams): Promise<AudioBuffer> => {
  const master = ctx.createGain();
  master.connect(ctx.destination);
  master.gain.value = 1.0;

  const outputBuffer = ctx.createBuffer(1, ctx.length, ctx.sampleRate);
  const outputData = outputBuffer.getChannelData(0);

  // Sorting essential for glide logic
  const sortedNotes = [...notes].sort((a,b) => a.startTime - b.startTime);

  // Parallel rendering
  const promises = sortedNotes.map(async (note, idx) => {
    // Determine Frequency from MIDI, applying Global Octave Shift
    const shift = (params.octaveShift || 0) * 12;
    const freq = midiToFreq(note.midi + shift);

    // Duration
    const dur = note.duration;

    // Check previous note for Glide (Portamento)
    let startFreq = undefined;
    if (idx > 0 && params.glide > 0) {
       const prev = sortedNotes[idx - 1];
       // Check if legato (close enough)
       // Let's say if gap is less than 0.25 beats (16th note)
       if (note.startTime - (prev.startTime + prev.duration) < 0.25) {
           // We glide FROM previous note frequency
           startFreq = midiToFreq(prev.midi + shift);
       }
    }

    // Create temp context for this note
    const tempCtx = new OfflineAudioContext(1, ctx.sampleRate * dur + 2000, ctx.sampleRate); // + padding

    // Adjust params for this specific note
    const noteParams = { 
        ...params, 
        text: note.lyric || 'la', 
        humanize: 0,
        pitchPoints: note.pitchPoints 
    };

    // Render individual note with potential startFreq for glide
    const noteBuffer = await renderVocals(tempCtx, noteParams, dur, freq, startFreq);

    return { buffer: noteBuffer, startTime: note.startTime };
  });

  const renderedNotes = await Promise.all(promises);

  // Mix into main buffer
  renderedNotes.forEach(({ buffer, startTime }) => {
    const startSample = Math.floor(startTime * ctx.sampleRate);
    const channelData = buffer.getChannelData(0);

    // Simple Mix
    for (let i = 0; i < channelData.length; i++) {
      const pos = startSample + i;
      if (pos < outputData.length) {
        outputData[pos] += channelData[i];
      }
    }
  });

  return outputBuffer;
};

/**
 * Render complete Multi-track Project
 */
export const renderProject = async (ctx: OfflineAudioContext, tracks: SequencerTrack[], bpm: number): Promise<AudioBuffer> => {
    const secondsPerBeat = 60 / bpm;
    const masterBuffer = ctx.createBuffer(1, ctx.length, ctx.sampleRate);
    const masterData = masterBuffer.getChannelData(0);

    const activeTracks = tracks.filter(t => !t.muted);
    // If Solo exists, only render solos
    const soloTracks = activeTracks.filter(t => t.solo);
    const tracksToRender = soloTracks.length > 0 ? soloTracks : activeTracks;

    const trackPromises = tracksToRender.map(async (track) => {
        // Find total duration for this track
        let maxTime = 0;
        track.notes.forEach(n => {
            if (n.startTime + n.duration > maxTime) maxTime = n.startTime + n.duration;
        });

        // Render track specifically
        // We create a buffer that might be smaller than global, but renderSequence handles placement relative to note start time (0 in its context??)
        // Wait, renderSequence uses startTimes in BEATS. We need to pass a context big enough.
        // Actually, renderSequence uses the passed context duration.
        // Let's reuse the logic but effectively render to a separate buffer first.

        // We can just use renderSequence on the MAIN context? No, we need track volume control.
        // So we render track to a buffer, apply gain, then mix.

        const trackCtx = new OfflineAudioContext(1, ctx.length, ctx.sampleRate);
        const secondsNotes = track.notes.map(n => ({
            ...n,
            startTime: n.startTime * secondsPerBeat,
            duration: n.duration * secondsPerBeat
        }));

        const trackBuf = await renderSequence(trackCtx, secondsNotes, track.vocalParams);
        return { buffer: trackBuf, volume: track.volume };
    });

    const results = await Promise.all(trackPromises);

    results.forEach(({ buffer, volume }) => {
        const d = buffer.getChannelData(0);
        for(let i=0; i<masterData.length; i++) {
            if (i < d.length) {
                masterData[i] += d[i] * volume;
            }
        }
    });

    // Master Limiter
    let maxAmp = 0;
    for(let i=0; i<masterData.length; i++) if(Math.abs(masterData[i]) > maxAmp) maxAmp = Math.abs(masterData[i]);
    if (maxAmp > 0.95) {
        const scale = 0.95 / maxAmp;
        for(let i=0; i<masterData.length; i++) masterData[i] *= scale;
    }

    return masterBuffer;
};

import React, { useRef, useState, useEffect } from 'react';
import { SequencerNote, SequencerTrack } from '../types';
import { 
  Pencil, Eraser, Undo, Redo, Trash2, MousePointer2, Hand, 
  ArrowLeftRight, ArrowUp, ArrowDown, ArrowLeft, ArrowRight, TrendingUp
} from 'lucide-react';

interface PianoRollProps {
  notes: SequencerNote[];
  setNotes: React.Dispatch<React.SetStateAction<SequencerNote[]>>;
  ghostTracks?: SequencerTrack[]; // New prop for background notes
  durationBeats: number; // Total beats
  onUndo: () => void;
  onRedo: () => void;
  addToHistory: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onEditPitch?: (noteId: string) => void;
}

const NOTE_HEIGHT = 20; // Compact height
const PIXELS_PER_BEAT = 60; // Zoom level
// Expanded Range: 0 (C-1) to 127 (G9) covers standard MIDI full range (~10.5 octaves)
const MIDI_MIN = 0; 
const MIDI_MAX = 127; 
const TOTAL_KEYS = MIDI_MAX - MIDI_MIN + 1;

type ToolType = 'POINTER' | 'PENCIL' | 'ERASER' | 'HAND';

export const PianoRoll: React.FC<PianoRollProps> = ({ 
  notes, setNotes, ghostTracks = [], durationBeats, onUndo, onRedo, addToHistory, canUndo, canRedo, onEditPitch
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>('POINTER');

  // Interaction State
  const dragRef = useRef<{ 
    type: 'MOVE' | 'RESIZE' | 'PAN' | 'CREATE', 
    noteId?: string, 
    startX: number, 
    startY: number, 
    initialStart?: number, 
    initialMidi?: number, 
    initialDuration?: number,
    initialScrollX?: number,
    initialScrollY?: number
  } | null>(null);

  // Generate Keys Data
  const keys = [];
  for (let i = MIDI_MAX; i >= MIDI_MIN; i--) {
    const isBlack = [1, 3, 6, 8, 10].includes(i % 12);
    // Label Logic: i=0 -> C-1, i=12 -> C0, i=60 -> C4
    keys.push({ midi: i, isBlack, label: i % 12 === 0 ? `C${(i/12)-1}` : '' });
  }

  // Auto-scroll to C4 on mount
  useEffect(() => {
    if (containerRef.current) {
        // Center C4 (Midi 60)
        const c4Midi = 60;
        const topPos = (MIDI_MAX - c4Midi) * NOTE_HEIGHT;
        const containerHeight = containerRef.current.clientHeight;
        // Scroll so C4 is roughly in the middle
        containerRef.current.scrollTop = topPos - (containerHeight / 2) + (NOTE_HEIGHT / 2);
    }
  }, []);

  // --- Helpers ---
  const getNoteAt = (midi: number, beat: number) => {
    return notes.find(n => 
      n.midi === midi && 
      beat >= n.startTime && 
      beat < n.startTime + n.duration
    );
  };

  const snapToGrid = (val: number, step = 0.25) => {
      return Math.round(val / step) * step;
  };

  // --- Handlers ---

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();

    // Coordinates relative to the scroll container content
    // We must account for the sticky header (keys width)
    const KEYS_WIDTH = 48;
    const rawX = e.clientX - rect.left;
    const scrollX = containerRef.current.scrollLeft;
    const scrollY = containerRef.current.scrollTop;

    // Effective Grid Coordinates
    const gridX = rawX + scrollX - KEYS_WIDTH;
    const gridY = e.clientY - rect.top + scrollY;

    // Check bounds (don't click on keys column)
    if (rawX < KEYS_WIDTH && tool !== 'HAND') return;

    const beat = Math.max(0, gridX / PIXELS_PER_BEAT);
    const midi = MIDI_MAX - Math.floor(gridY / NOTE_HEIGHT);

    // --- TOOL LOGIC ---

    if (tool === 'HAND' || (e.button === 1)) { // Middle click or Hand tool
        dragRef.current = {
            type: 'PAN',
            startX: e.clientX,
            startY: e.clientY,
            initialScrollX: scrollX,
            initialScrollY: scrollY
        };
        return;
    }

    if (tool === 'ERASER') {
        const clickedNote = getNoteAt(midi, beat);
        if (clickedNote) {
            addToHistory();
            setNotes(prev => prev.filter(n => n.id !== clickedNote.id));
        }
        return;
    }

    if (tool === 'PENCIL') {
        const existing = getNoteAt(midi, beat);
        if (existing) {
            setSelectedNoteId(existing.id);
        } else {
            // Create
            addToHistory();
            const newNote: SequencerNote = {
                id: Math.random().toString(36).substr(2, 9),
                midi: midi,
                startTime: Math.floor(beat * 4) / 4, // Snap 1/4
                duration: 1.0,
                lyric: 'la',
                pitchPoints: [{t:0,v:0},{t:1,v:0}]
            };
            setNotes(prev => [...prev, newNote]);
            setSelectedNoteId(newNote.id);
            // Immediately start moving/resizing? Maybe just creation for now.
        }
        return;
    }

    if (tool === 'POINTER') {
        // We handle Note Click separately in onMouseDown on the Note element itself usually,
        // but if we clicked Empty Space, Deselect.
        const existing = getNoteAt(midi, beat);
        if (!existing) {
            setSelectedNoteId(null);
        }
    }
  };

  const handleNoteMouseDown = (e: React.MouseEvent, note: SequencerNote, type: 'MOVE' | 'RESIZE') => {
    e.stopPropagation();
    if (tool !== 'POINTER') return; // Only pointer modifies existing notes logic here

    addToHistory();
    setSelectedNoteId(note.id);

    dragRef.current = {
        type: type,
        noteId: note.id,
        startX: e.clientX,
        startY: e.clientY,
        initialStart: note.startTime,
        initialMidi: note.midi,
        initialDuration: note.duration
    };
  };

  const handleGlobalMove = (e: MouseEvent) => {
    if (!dragRef.current) return;
    const { type, startX, startY, noteId, initialStart, initialMidi, initialDuration, initialScrollX, initialScrollY } = dragRef.current;

    if (type === 'PAN' && containerRef.current) {
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;
        containerRef.current.scrollLeft = (initialScrollX || 0) - dx;
        containerRef.current.scrollTop = (initialScrollY || 0) - dy;
        return;
    }

    const deltaX = (e.clientX - startX) / PIXELS_PER_BEAT;
    const deltaY = (e.clientY - startY) / NOTE_HEIGHT;

    if (type === 'MOVE') {
        const newStart = Math.max(0, snapToGrid((initialStart || 0) + deltaX));
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, Math.round((initialMidi || 0) - deltaY)));

        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, startTime: newStart, midi: newMidi } : n));
    }

    if (type === 'RESIZE') {
        const newDur = Math.max(0.125, snapToGrid((initialDuration || 0) + deltaX, 0.125));
        setNotes(prev => prev.map(n => n.id === noteId ? { ...n, duration: newDur } : n));
    }
  };

  const handleGlobalUp = () => {
    dragRef.current = null;
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleGlobalMove);
    window.addEventListener('mouseup', handleGlobalUp);
    return () => {
        window.removeEventListener('mousemove', handleGlobalMove);
        window.removeEventListener('mouseup', handleGlobalUp);
    };
  }, []);

  const updateNoteLyric = (id: string, newLyric: string) => {
    setNotes(notes.map(n => n.id === id ? { ...n, lyric: newLyric } : n));
  };

  const updateNoteDuration = (id: string, newDuration: number) => {
    if (isNaN(newDuration)) return;
    const d = Math.max(0.125, newDuration);
    setNotes(notes.map(n => n.id === id ? { ...n, duration: d } : n));
  };

  const deleteNote = (id: string) => {
      addToHistory();
      setNotes(notes.filter(n => n.id !== id));
      setSelectedNoteId(null);
  };

  const moveSelectedNote = (dt: number, dMidi: number) => {
    if (!selectedNoteId) return;
    addToHistory();
    setNotes(prev => prev.map(n => {
        if (n.id !== selectedNoteId) return n;
        const newStart = Math.max(0, n.startTime + dt);
        const newMidi = Math.min(MIDI_MAX, Math.max(MIDI_MIN, n.midi + dMidi));
        return { ...n, startTime: newStart, midi: newMidi };
    }));
  };

  return (
    <div className="flex flex-col h-[500px] bg-gray-900 border border-synth-grid rounded-xl overflow-hidden select-none shadow-2xl relative group">

      {/* Toolbar */}
      <div className="bg-synth-panel p-2 flex gap-2 items-center border-b border-synth-grid h-12 shrink-0 z-30 relative">
        <span className="text-xs font-bold text-synth-accent mr-2 hidden sm:block">TOOLS</span>

        <div className="flex bg-synth-dark rounded-lg p-0.5 border border-synth-grid">
            <button onClick={() => setTool('POINTER')} className={`p-1.5 rounded-md ${tool === 'POINTER' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Select/Move/Resize">
                <MousePointer2 size={14} />
            </button>
            <button onClick={() => setTool('PENCIL')} className={`p-1.5 rounded-md ${tool === 'PENCIL' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Create">
                <Pencil size={14} />
            </button>
            <button onClick={() => setTool('HAND')} className={`p-1.5 rounded-md ${tool === 'HAND' ? 'bg-synth-accent text-synth-dark' : 'text-slate-400'}`} title="Navigate">
                <Hand size={14} />
            </button>
             <button onClick={() => setTool('ERASER')} className={`p-1.5 rounded-md ${tool === 'ERASER' ? 'bg-synth-pop text-white' : 'text-slate-400'}`} title="Erase">
                <Eraser size={14} />
            </button>
        </div>

        <div className="w-px h-6 bg-synth-grid mx-1"></div>

        <div className="flex gap-1">
             <button onClick={onUndo} disabled={!canUndo} className={`p-1.5 rounded-md ${canUndo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Undo size={14} /></button>
            <button onClick={onRedo} disabled={!canRedo} className={`p-1.5 rounded-md ${canRedo ? 'text-slate-200 hover:bg-slate-700' : 'text-slate-700'}`}><Redo size={14} /></button>
        </div>

        {selectedNoteId && (
            <div className="flex items-center gap-2 ml-auto animate-in fade-in duration-200 border-l border-synth-grid pl-2">
                <button 
                    onClick={() => onEditPitch && onEditPitch(selectedNoteId)}
                    className="flex items-center gap-1 px-2 py-1 bg-synth-dark border border-synth-grid rounded text-[10px] text-synth-pop hover:bg-slate-700"
                    title="Edit Pitch Bend"
                >
                    <TrendingUp size={12} />
                    PITCH
                </button>
                <input 
                    type="text" 
                    className="bg-synth-dark border border-synth-grid rounded px-2 py-1 text-xs text-white w-20 focus:border-synth-pop outline-none text-center"
                    value={notes.find(n => n.id === selectedNoteId)?.lyric || ''}
                    onChange={(e) => updateNoteLyric(selectedNoteId, e.target.value)}
                    onFocus={addToHistory}
                    placeholder="Lyric"
                    title="Lyric"
                />

                {/* Manual Duration Control */}
                <div className="flex items-center bg-synth-dark border border-synth-grid rounded px-1" title="Duration (Beats)">
                    <ArrowLeftRight size={10} className="text-slate-500 mr-1" />
                    <input 
                        type="number"
                        step={0.25}
                        min={0.125}
                        className="bg-transparent text-xs text-white w-10 focus:outline-none text-center font-mono appearance-none"
                        value={notes.find(n => n.id === selectedNoteId)?.duration || 0}
                        onChange={(e) => updateNoteDuration(selectedNoteId, parseFloat(e.target.value))}
                        onFocus={addToHistory}
                    />
                </div>
            </div>
        )}
      </div>

      {/* Main Scroll Container */}
      <div 
        ref={containerRef}
        className={`flex-1 overflow-auto bg-synth-dark relative scroll-smooth ${tool === 'HAND' ? 'cursor-grab active:cursor-grabbing' : 'cursor-default'}`}
        onMouseDown={handleMouseDown}
      >
        <div 
            className="relative flex" 
            style={{ 
                height: `${TOTAL_KEYS * NOTE_HEIGHT}px`, 
                width: `${Math.max(durationBeats * PIXELS_PER_BEAT + 48, 1000)}px` // +48 for keys width
            }}
        >

            {/* STICKY KEYS COLUMN */}
            <div className="w-12 sticky left-0 z-20 bg-white border-r border-gray-300 flex flex-col shrink-0 shadow-lg">
                {keys.map((k) => (
                    <div 
                        key={k.midi} 
                        className={`h-[20px] border-b border-gray-300 text-[9px] flex items-center justify-end pr-1 font-bold ${k.isBlack ? 'bg-black text-white' : 'bg-white text-gray-800'}`}
                        style={{ height: NOTE_HEIGHT }}
                    >
                        {k.label}
                    </div>
                ))}
            </div>

            {/* GRID AREA */}
            <div className="flex-1 relative">

                {/* Background Rows */}
                {keys.map((k, i) => (
                    <div 
                        key={k.midi}
                        className={`absolute w-full border-b border-synth-grid/10 ${k.isBlack ? 'bg-synth-grid/5' : ''}`}
                        style={{ top: i * NOTE_HEIGHT, height: NOTE_HEIGHT }}
                    />
                ))}

                {/* Vertical Beat Lines */}
                {Array.from({ length: Math.ceil(durationBeats) + 1 }).map((_, i) => (
                    <div 
                        key={i} 
                        className={`absolute top-0 bottom-0 w-px ${i % 4 === 0 ? 'bg-synth-grid/60' : 'bg-synth-grid/20'}`}
                        style={{ left: i * PIXELS_PER_BEAT }}
                    >
                        {i % 4 === 0 && <span className="absolute top-0 left-1 text-[8px] text-slate-500 font-mono">{i}</span>}
                    </div>
                ))}

                {/* GHOST NOTES (From other tracks) */}
                {ghostTracks.map(track => 
                    track.muted ? null : track.notes.map(note => {
                        const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                        const left = note.startTime * PIXELS_PER_BEAT;
                        const width = note.duration * PIXELS_PER_BEAT;
                        return (
                            <div
                                key={`ghost-${track.id}-${note.id}`}
                                className="absolute rounded-sm bg-gray-500/20 border border-gray-500/30 pointer-events-none z-0"
                                style={{
                                    top: top + 1,
                                    left: left,
                                    width: Math.max(width - 1, 4),
                                    height: NOTE_HEIGHT - 2,
                                }}
                            />
                        )
                    })
                )}

                {/* ACTIVE NOTES */}
                {notes.map(note => {
                    const top = (MIDI_MAX - note.midi) * NOTE_HEIGHT;
                    const left = note.startTime * PIXELS_PER_BEAT;
                    const width = note.duration * PIXELS_PER_BEAT;
                    const isSelected = selectedNoteId === note.id;

                    // Generate Pitch Curve SVG Path
                    let pitchPath = '';
                    if (note.pitchPoints && note.pitchPoints.length > 0) {
                        const h = NOTE_HEIGHT - 2;
                        const w = Math.max(width - 1, 4);
                        const points = note.pitchPoints.map(p => {
                            const px = p.t * w;
                            const py = (h/2) - (p.v/24)*h; 
                            return `${px},${py}`;
                        });
                        pitchPath = `M ${points.join(' L ')}`;
                    }

                    return (
                        <div
                            key={note.id}
                            onMouseDown={(e) => handleNoteMouseDown(e, note, 'MOVE')}
                            className={`absolute rounded-sm border text-[10px] flex items-center pl-1 overflow-hidden shadow-sm group z-10
                                ${isSelected 
                                    ? 'bg-synth-pop border-white text-white shadow-lg ring-1 ring-white' 
                                    : 'bg-synth-accent/90 border-synth-accent text-synth-dark hover:bg-synth-accent'
                                }`}
                            style={{
                                top: top + 1,
                                left: left,
                                width: Math.max(width - 1, 4),
                                height: NOTE_HEIGHT - 2,
                                cursor: tool === 'POINTER' ? 'move' : 'default'
                            }}
                        >
                            {/* Pitch Curve Overlay */}
                            {pitchPath && (
                                <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-50" viewBox={`0 0 ${Math.max(width-1,4)} ${NOTE_HEIGHT-2}`} preserveAspectRatio="none">
                                    <path d={pitchPath} stroke="white" strokeWidth="2" fill="none" />
                                </svg>
                            )}

                            <span className="truncate w-full pointer-events-none select-none relative z-10 drop-shadow-md">{note.lyric}</span>

                            {/* Resize Handle */}
                            {tool === 'POINTER' && (
                                <div 
                                    className={`absolute right-0 top-0 bottom-0 w-4 cursor-ew-resize z-20 flex items-center justify-center opacity-0 hover:opacity-100 ${isSelected ? 'opacity-100' : ''}`}
                                    onMouseDown={(e) => handleNoteMouseDown(e, note, 'RESIZE')}
                                >
                                    <div className="w-1 h-3 bg-white/60 rounded-full" />
                                </div>
                            )}
                        </div>
                    );
                })}

            </div>
        </div>
      </div>

       {/* Floating Action Controls */}
       {selectedNoteId && (
        <div className="absolute bottom-4 right-4 z-50 flex items-end gap-3 animate-in fade-in slide-in-from-bottom-4 duration-200 pointer-events-auto">
            {/* D-Pad */}
            <div className="bg-synth-panel/95 backdrop-blur border border-synth-grid rounded-2xl p-2 shadow-2xl flex flex-col items-center gap-1">
                <button onClick={() => moveSelectedNote(0, 1)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowUp size={20} /></button>
                <div className="flex gap-1">
                     <button onClick={() => moveSelectedNote(-0.25, 0)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowLeft size={20} /></button>
                     <button onClick={() => moveSelectedNote(0, -1)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowDown size={20} /></button>
                     <button onClick={() => moveSelectedNote(0.25, 0)} className="p-2 hover:bg-synth-accent/20 rounded-lg text-synth-accent transition-colors active:scale-95 bg-white/5"><ArrowRight size={20} /></button>
                </div>
            </div>
            <button onClick={() => deleteNote(selectedNoteId)} className="bg-red-500 hover:bg-red-600 text-white p-4 rounded-2xl shadow-xl active:scale-90 transition-all border border-red-400/50"><Trash2 size={24} /></button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  VowelType, 
  VocalMode, 
  VocalPreset, 
  VocalParams, 
  GlobalParams,
  SequencerNote,
  SequencerTrack
} from './types';
import { 
  renderVocals, 
  renderProject,
  applyReverb,
  bufferToWav,
  getFrequency,
  NOTE_FREQUENCIES
} from './services/audioEngine';
import { parseMidiFile } from './services/midiLoader';
import { ControlSlider } from './components/Knob';
import { PianoRoll } from './components/PianoRoll';
import { 
  Play, Download, Mic, Activity, Settings, Music, Piano, Upload, 
  Save, FileJson, Type, X, Check, TrendingUp, Waves, Plus, Volume2, 
  VolumeX, Layers, Sliders
} from 'lucide-react';

const App: React.FC = () => {
  // --- STATE ---
  const [mode, setMode] = useState<'LIVE' | 'SEQUENCER'>('LIVE');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedBuffer, setGeneratedBuffer] = useState<AudioBuffer | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Global State
  const [globalParams, setGlobalParams] = useState<GlobalParams>({
    bpm: 120,
    duration: 8.0, 
    reverbMix: 0.1,
    reverbDecay: 2.0
  });

  const [selectedNote, setSelectedNote] = useState<string>('C');
  const [selectedOctave, setSelectedOctave] = useState<number>(4);

  // Multi-Track State
  const [tracks, setTracks] = useState<SequencerTrack[]>([
    {
      id: 'track-1',
      name: 'Main Vocal',
      color: '#38bdf8',
      notes: [
         { id: '1', midi: 60, startTime: 0, duration: 1.0, lyric: 'o', pitchPoints: [{t:0,v:0},{t:1,v:0}] },
         { id: '2', midi: 62, startTime: 1.0, duration: 1.0, lyric: 'i', pitchPoints: [{t:0,v:0},{t:1,v:0}] },
         { id: '3', midi: 64, startTime: 2.0, duration: 2.0, lyric: 'e', pitchPoints: [{t:0,v:0},{t:1,v:0}] }
      ],
      volume: 0.8,
      muted: false,
      solo: false,
      vocalParams: {
        text: "OIE",
        preset: VocalPreset.MALE_BR,
        mode: VocalMode.SINGING,
        vowel: VowelType.A,
        jitter: 0.1,
        humanize: 0.1,
        breathiness: 0.2,
        formantShift: 1.0,
        speed: 1.0,
        pitch: 1.0,
        octaveShift: 0,
        glide: 0.1,
        wordGap: 0.05 
      }
    }
  ]);

  const [activeTrackId, setActiveTrackId] = useState<string>('track-1');

  // History Stacks (Track Level history is tricky, doing Project Level snapshot for simplicity)
  const [history, setHistory] = useState<SequencerTrack[][]>([]);
  const [future, setFuture] = useState<SequencerTrack[][]>([]);

  // Modals
  const [showLyricsModal, setShowLyricsModal] = useState(false);
  const [showCustomizer, setShowCustomizer] = useState(false);
  const [lyricsInput, setLyricsInput] = useState("");

  // Pitch Editor State
  const [showPitchModal, setShowPitchModal] = useState(false);
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);
  const [pitchCurve, setPitchCurve] = useState<{t:number, v:number}[]>([]);
  const pitchCanvasRef = useRef<HTMLCanvasElement>(null);

  // Helper getters
  const activeTrack = tracks.find(t => t.id === activeTrackId) || tracks[0];
  const ghostTracks = tracks.filter(t => t.id !== activeTrackId);

  // Function to capture state BEFORE a change
  const addToHistory = useCallback(() => {
    setHistory(prev => [...prev, JSON.parse(JSON.stringify(tracks))]);
    setFuture([]); 
  }, [tracks]);

  const handleUndo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    const newHistory = history.slice(0, -1);
    setFuture(prev => [tracks, ...prev]);
    setTracks(previous);
    setHistory(newHistory);
  }, [history, tracks]);

  const handleRedo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);
    setHistory(prev => [...prev, tracks]);
    setTracks(next);
    setFuture(newFuture);
  }, [future, tracks]);

  // Update ACTIVE TRACK logic
  const updateActiveTrack = (updates: Partial<SequencerTrack> | ((prev: SequencerTrack) => Partial<SequencerTrack>)) => {
      setTracks(prev => prev.map(t => {
          if (t.id !== activeTrackId) return t;
          const newVals = typeof updates === 'function' ? updates(t) : updates;
          return { ...t, ...newVals };
      }));
  };

  const updateActiveTrackParams = (updates: Partial<VocalParams> | ((prev: VocalParams) => Partial<VocalParams>)) => {
      setTracks(prev => prev.map(t => {
          if (t.id !== activeTrackId) return t;
          const currentParams = t.vocalParams;
          const newParams = typeof updates === 'function' ? updates(currentParams) : updates;
          return { ...t, vocalParams: { ...currentParams, ...newParams } };
      }));
  };

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        e.shiftKey ? handleRedo() : handleUndo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo]);


  // Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  // --- HANDLERS ---

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedBuffer(null);

    setTimeout(async () => {
      try {
        const sampleRate = 44100;
        let buffer: AudioBuffer;

        if (mode === 'LIVE') {
             // Live mode uses direct active track params
             const ctx = new OfflineAudioContext(1, sampleRate * globalParams.duration, sampleRate);
             const baseFreq = getFrequency(selectedNote, selectedOctave);
             buffer = await renderVocals(ctx, activeTrack.vocalParams, globalParams.duration, baseFreq);
        } else {
            // SEQUENCER MODE (Multi-Track)
            const secondsPerBeat = 60 / globalParams.bpm;

            // Calculate total duration
            let totalBeats = 16; 
            tracks.forEach(t => {
                if (t.notes.length > 0) {
                     const last = t.notes.reduce((max, curr) => Math.max(max, curr.startTime + curr.duration), 0);
                     if (last + 4 > totalBeats) totalBeats = last + 4;
                }
            });
            const totalSeconds = totalBeats * secondsPerBeat;

            const ctx = new OfflineAudioContext(1, sampleRate * totalSeconds, sampleRate);
            buffer = await renderProject(ctx, tracks, globalParams.bpm);
        }

        // Apply Global Reverb
        if (globalParams.reverbMix > 0) {
            const reverbCtx = new OfflineAudioContext(1, buffer.length, sampleRate);
            buffer = await applyReverb(reverbCtx, buffer, globalParams.reverbMix, globalParams.reverbDecay);
        }

        setGeneratedBuffer(buffer);
        drawWaveform(buffer);
      } catch (e) {
        console.error(e);
        alert("Error generating audio");
      } finally {
        setIsGenerating(false);
      }
    }, 50);
  };

  const handleMidiUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                addToHistory(); 
                const { tracks: newTracks, bpm } = parseMidiFile(ev.target.result as ArrayBuffer);
                setTracks(newTracks);
                if (newTracks.length > 0) setActiveTrackId(newTracks[0].id);
                setGlobalParams(p => ({ ...p, bpm: bpm || 120 })); // Auto BPM
                setMode('SEQUENCER'); 
                alert(`Imported ${newTracks.length} tracks at ${bpm} BPM!`);
            } catch (err) {
                console.error(err);
                alert("Failed to parse file.");
            }
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAddTrack = () => {
      addToHistory();
      const newTrack: SequencerTrack = {
          id: `track-${Date.now()}`,
          name: `Track ${tracks.length + 1}`,
          color: '#38bdf8',
          notes: [],
          volume: 0.8,
          muted: false,
          solo: false,
          vocalParams: { ...activeTrack.vocalParams, preset: VocalPreset.FEMALE_BR } // Default new track to something
      };
      setTracks(prev => [...prev, newTrack]);
      setActiveTrackId(newTrack.id);
  };

  const handleDeleteTrack = (id: string) => {
      if (tracks.length <= 1) return;
      addToHistory();
      const newTracks = tracks.filter(t => t.id !== id);
      setTracks(newTracks);
      if (activeTrackId === id) setActiveTrackId(newTracks[0].id);
  };

  // ... (Existing Lyrics logic modified to use activeTrack)
  const handleApplyLyrics = () => {
      if (!lyricsInput.trim()) { setShowLyricsModal(false); return; }
      addToHistory();
      // ... Syllabify logic ...
      const syllabify = (text: string) => {
        const regex = /[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]*[aeiouyáéíóúãõâêîôûàèìòùäëïöü]+(?:[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]*$|[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ](?=[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]))?/gi;
        return text.match(regex) || [text];
      };
      const rawWords = lyricsInput.replace(/[\n\r]/g, ' ').split(/[\s-]+/).filter(s => s.length > 0);
      let syllables: string[] = [];
      rawWords.forEach(word => word.length > 2 ? syllables.push(...syllabify(word)) : syllables.push(word));
      if (syllables.length === 0) return;

      let tempNotes = [...activeTrack.notes].sort((a, b) => a.startTime - b.startTime);
      // ... (Existing split logic would go here, simplified for brevity in this block, assume straight mapping)
      const finalNotes = tempNotes.map((note, index) => {
          return index < syllables.length ? { ...note, lyric: syllables[index] } : { ...note, lyric: '' };
      });
      updateActiveTrack({ notes: finalNotes });
      setLyricsInput(""); setShowLyricsModal(false);
  };

  // ... (Existing Pitch logic)
  const handleOpenPitchEditor = (noteId: string) => {
      const note = activeTrack.notes.find(n => n.id === noteId);
      if (!note) return;
      setEditingNoteId(noteId);
      setPitchCurve(note.pitchPoints && note.pitchPoints.length > 0 ? note.pitchPoints : [{t:0,v:0}, {t:1,v:0}]);
      setShowPitchModal(true);
  };

  const handlePitchCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
      const canvas = pitchCanvasRef.current; if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const t = (e.clientX - rect.left) / canvas.width;
      const semitones = 12 - ((e.clientY - rect.top) / canvas.height) * 24;
      const newCurve = [...pitchCurve, { t, v: semitones }].sort((a,b) => a.t - b.t);
      setPitchCurve(newCurve);
  };

  const drawPitchCurve = () => {
      const canvas = pitchCanvasRef.current; if (!canvas) return;
      const ctx = canvas.getContext('2d'); if (!ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.strokeStyle = '#334155'; ctx.beginPath(); ctx.moveTo(0, canvas.height/2); ctx.lineTo(canvas.width, canvas.height/2); ctx.stroke();
      ctx.strokeStyle = '#f472b6'; ctx.lineWidth = 3; ctx.beginPath();
      if (pitchCurve.length > 0) {
          const getY = (v: number) => canvas.height/2 - (v/12)*(canvas.height/2);
          pitchCurve.forEach((pt, i) => {
              const x = pt.t * canvas.width; const y = getY(pt.v);
              i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
              ctx.fillStyle = '#fff'; ctx.fillRect(x-2, y-2, 4, 4);
          });
      }
      ctx.stroke();
  };

  useEffect(() => { if (showPitchModal) requestAnimationFrame(drawPitchCurve); }, [pitchCurve, showPitchModal]);

  const handleApplyPitch = () => {
      if (!editingNoteId) return;
      addToHistory();
      const updatedNotes = activeTrack.notes.map(n => n.id === editingNoteId ? { ...n, pitchPoints: pitchCurve } : n);
      updateActiveTrack({ notes: updatedNotes });
      setShowPitchModal(false);
  };

  // ... (Existing Audio Playback/Export)
  const handlePlay = () => {
    if (!generatedBuffer || !audioContextRef.current) audioContextRef.current = new AudioContext();
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') ctx.resume();
    const source = ctx.createBufferSource();
    source.buffer = generatedBuffer;
    source.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);
    setIsPlaying(true);
    source.start();
  };

  const handleDownload = () => {
    if (!generatedBuffer) return;
    const url = URL.createObjectURL(bufferToWav(generatedBuffer));
    const a = document.createElement('a'); a.href = url; a.download = `vocalstudio_${Date.now()}.wav`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  };

  const drawWaveform = (buffer: AudioBuffer) => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    const data = buffer.getChannelData(0);
    const step = Math.ceil(data.length / canvas.width);
    const amp = canvas.height / 2;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath(); ctx.moveTo(0, amp); ctx.strokeStyle = '#38bdf8'; ctx.lineWidth = 2;
    for (let i = 0; i < canvas.width; i++) {
      let min = 1.0; let max = -1.0;
      for (let j = 0; j < step; j++) {
        const datum = data[(i * step) + j]; if (datum < min) min = datum; if (datum > max) max = datum;
      }
      ctx.lineTo(i, (1 + min) * amp); ctx.lineTo(i, (1 + max) * amp);
    }
    ctx.stroke();
  };

  // UI Render Helpers
  const renderTrackItem = (track: SequencerTrack) => (
      <div 
        key={track.id}
        onClick={() => setActiveTrackId(track.id)}
        className={`flex items-center gap-2 p-2 rounded-lg border cursor-pointer transition-all ${
            activeTrackId === track.id ? 'bg-synth-panel border-synth-accent' : 'bg-synth-dark border-synth-grid opacity-70 hover:opacity-100'
        }`}
      >
          <div className="w-2 h-8 rounded-full" style={{backgroundColor: track.color}} />
          <div className="flex-1 min-w-0">
              <div className="text-[10px] font-bold truncate">{track.name}</div>
              <div className="flex items-center gap-1">
                  <input 
                    type="range" min="0" max="1" step="0.1" 
                    value={track.volume}
                    onClick={(e) => e.stopPropagation()}
                    onChange={(e) => {
                        const v = parseFloat(e.target.value);
                        setTracks(prev => prev.map(t => t.id === track.id ? { ...t, volume: v } : t));
                    }}
                    className="w-16 h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-synth-accent"
                  />
              </div>
          </div>
          <button 
            onClick={(e) => { e.stopPropagation(); setTracks(prev => prev.map(t => t.id === track.id ? { ...t, muted: !t.muted } : t)); }}
            className={`p-1 rounded ${track.muted ? 'bg-red-500 text-white' : 'text-slate-500 hover:bg-slate-700'}`}
          >
             {track.muted ? <VolumeX size={12}/> : <Volume2 size={12}/>}
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); setTracks(prev => prev.map(t => t.id === track.id ? { ...t, solo: !t.solo } : t)); }}
            className={`p-1 rounded text-[9px] font-bold ${track.solo ? 'bg-yellow-500 text-black' : 'text-slate-500 hover:bg-slate-700 bg-slate-800'}`}
          >
             S
          </button>
      </div>
  );

  return (
    <div className="min-h-screen bg-synth-dark text-slate-200 pb-40 font-sans">
      <header className="p-4 bg-synth-dark/90 backdrop-blur sticky top-0 z-10 border-b border-synth-grid flex justify-between items-center shadow-lg">
        <div>
          <h1 className="text-xl font-bold bg-gradient-to-r from-synth-accent to-synth-pop bg-clip-text text-transparent flex items-center gap-2">
            <Mic size={24} className="text-synth-accent" />
            VocalStudio
          </h1>
          <p className="text-[10px] text-slate-500 tracking-wide font-mono">DSP RACK</p>
