  [VocalPreset.ALIEN]: { baseFreq: 200, formantScale: 1.0, breath: 0, fm: { depth: 100, rate: 20 }, type: 'sawtooth' },
  [VocalPreset.CHORUS]: { baseFreq: 180, formantScale: 1.0, breath: 0.05, chorus: true, type: 'sawtooth' },
  [VocalPreset.TELEPHONE]: { baseFreq: 180, formantScale: 1.0, breath: 0.1, bandpass: [300, 3400], type: 'sawtooth' },
  [VocalPreset.VHS]: { baseFreq: 170, formantScale: 1.0, breath: 0.2, flutter: 0.3, type: 'sawtooth' },
  [VocalPreset.ETHEREAL]: { baseFreq: 240, formantScale: 1.0, breath: 0.3, longReverb: true, type: 'sine' },
  [VocalPreset.CARTOON]: { baseFreq: 450, formantScale: 0.6, breath: 0.01, type: 'pulse' },
  [VocalPreset.REALISTIC]: { baseFreq: 140, formantScale: 1.0, breath: 0.05, nasal: 0.1, vibrato: { depth: 0.004, rate: 5 }, type: 'sawtooth' },
  // NEW INSTRUMENTS
  [VocalPreset.SYNTH_BELL]: { baseFreq: 200, formantScale: 1.0, type: 'sine', fm: { rate: 2.5, depth: 300 }, oscGain: 0.8 },
  [VocalPreset.E_PIANO]: { baseFreq: 110, formantScale: 1.0, type: 'triangle', fm: { rate: 0.5, depth: 20 }, vibrato: { depth: 0.002, rate: 4 } }
