/**
 * Enhanced Vocal Synthesis with Text Sequencing
 */
export const renderVocals = async (ctx: OfflineAudioContext, params: VocalParams, duration: number, baseFreq: number, startFreq?: number): Promise<AudioBuffer> => {
  // 1. Prepare Text & Phonemes via Parser
  const phonemes = textToPhonemes(params.text);

  // 2. Calculate Timing (Variable Duration based on Phoneme Type)
  let totalUnits = 0;
  const phonemeSequence = phonemes.map(p => {
    const def = PHONEME_LIB[p] || PHONEME_LIB['a'];
    totalUnits += def.durationScale;
    return { char: p, def };
  });

  // If no text, avoid division by zero
  if (totalUnits === 0) totalUnits = 1;

  const unitTime = duration / totalUnits;

  // 3. Load Preset Config & Frequency
  // CHECK FOR CUSTOM DATA
  let presetData = VOCAL_PRESETS_DATA[params.preset];
  if (params.preset === VocalPreset.CUSTOM && params.customData) {
      presetData = params.customData;
  }
  // Fallback
  if (!presetData) presetData = VOCAL_PRESETS_DATA[VocalPreset.MALE_BR];

  // Use user provided baseFreq instead of preset default baseFreq unless mode forces it
  // We apply the preset pitch multiplier if any, but base it on the Global Note.
  const f0 = baseFreq * params.pitch;

  // 4. Build Source Chain
  const master = ctx.createGain();
  master.connect(ctx.destination);

  // Main Oscillator
  const osc = ctx.createOscillator();
  osc.type = presetData.type || 'sawtooth';

  // Pitch Logic (Speech vs Singing) & Automation
  if (startFreq && params.glide > 0) {
      // GLIDE / PORTAMENTO
      // Ramp from startFreq to f0
      osc.frequency.setValueAtTime(startFreq, 0);
      // Glide time is a fraction of note duration or fixed max
      // Map glide 0..1 to approx 0..0.5s max
      const glideTime = Math.min(duration, params.glide * 0.5); 
      // Use exponential ramp for natural slide
      osc.frequency.exponentialRampToValueAtTime(f0, glideTime);
  } else {
      osc.frequency.setValueAtTime(f0, 0);
  }

  // Apply Pitch Bend (Curve) via Detune (Works on top of frequency automation)
  if (params.pitchPoints && params.pitchPoints.length > 0) {
     const sorted = [...params.pitchPoints].sort((a,b) => a.t - b.t);
     if (sorted[0].t > 0) {
         osc.detune.setValueAtTime(0, 0);
     }
     sorted.forEach((pt, i) => {
          const t = pt.t * duration;
          const cents = pt.v * 100; 
          if (t === 0) {
            osc.detune.setValueAtTime(cents, 0);
          } else {
            osc.detune.linearRampToValueAtTime(cents, t);
          }
     });
  }

  // If Speech Mode (TTS), we apply a prosody curve
  // Standard prosody: Slight rise at start, gradual fall at end.
  // Variations on stressed syllables can be added in loop.
  if (params.mode === VocalMode.SPEECH) {
    const startPitch = f0 * 1.1;
    const endPitch = f0 * 0.85;
    osc.frequency.setValueAtTime(startPitch, 0);
    // Add small variations per phoneme in the loop, but general trend is falling
    osc.frequency.exponentialRampToValueAtTime(endPitch, duration);
  }

  // Pitch Modulations (Vibrato / Drift / FM / Flutter)
  if (presetData.vibrato && params.mode !== VocalMode.SPEECH) {
     const lfo = ctx.createOscillator();
     lfo.frequency.value = presetData.vibrato.rate;
     const lfoGain = ctx.createGain();
     // If pitch bending, vibrato applies on top
     lfoGain.gain.value = f0 * presetData.vibrato.depth;
     lfo.connect(lfoGain);
     lfoGain.connect(osc.frequency);
     lfo.start(0);
  }

  // HUMAN INSTABILITY (Slow Drift + Error)
  if (params.humanize > 0) {
    // We use a low freq oscillator to simulate "human error" in holding pitch
    const driftOsc = ctx.createOscillator();
    driftOsc.frequency.value = 0.5 + (Math.random() * 2); // Slow drift 0.5Hz - 2.5Hz
    const driftGain = ctx.createGain();
    // Drifts up to +/- semitone at max humanize
    driftGain.gain.value = f0 * 0.06 * params.humanize; 
    driftOsc.connect(driftGain);
    driftGain.connect(osc.frequency);
    driftOsc.start(0);
  }

  if (presetData.flutter) {
      const flutterOsc = ctx.createOscillator();
      flutterOsc.frequency.value = 0.3;
      const fGain = ctx.createGain();
      fGain.gain.value = 10;
      flutterOsc.connect(fGain);
      fGain.connect(osc.frequency);
      flutterOsc.start(0);
  }

  if (presetData.fm) {
      // FM Synthesis: Modulator Oscillator
      const fmOsc = ctx.createOscillator();
      // FM Rate: Can be absolute or relative (ratio). 
      // For simple bell implementation (prompt), let's assume `rate` is a multiplier if < 20, else absolute Hz.
      const fmRate = presetData.fm.rate; 
      const isRatio = fmRate < 50; 

      if (isRatio) {
          fmOsc.frequency.value = f0 * fmRate;
      } else {
          fmOsc.frequency.value = fmRate;
      }

      const fmGain = ctx.createGain();
      fmGain.gain.value = presetData.fm.depth;

      // Basic envelope for FM to make it percussive (bell-like)
      if (presetData.type === 'custom' || presetData.type === 'sine') {
           // Decay FM amount over time
           fmGain.gain.setValueAtTime(presetData.fm.depth, 0);
           fmGain.gain.exponentialRampToValueAtTime(0.01, duration);
      }

      fmOsc.connect(fmGain);
      fmGain.connect(osc.frequency);
      fmOsc.start(0);
  }

  // OSC GAIN (Controlled by Phoneme Envelope)
  const oscGainNode = ctx.createGain();
  // We will automate this gain
  oscGainNode.gain.setValueAtTime(0, 0); 
  osc.connect(oscGainNode);

  // NOISE SOURCE
  const noiseBuff = ctx.createBuffer(1, ctx.sampleRate * duration, ctx.sampleRate);
  const nd = noiseBuff.getChannelData(0);
  for(let i=0; i<nd.length; i++) nd[i] = (Math.random() * 2 - 1) * 0.5;
  const noiseSrc = ctx.createBufferSource();
  noiseSrc.buffer = noiseBuff;

  // Noise Shaping Filter (for fricatives like 's' vs 'sh')
  const noiseFilter = ctx.createBiquadFilter();
  noiseFilter.type = 'highpass';
  noiseFilter.frequency.value = 1000; // Default
  noiseSrc.connect(noiseFilter);

  const noiseGain = ctx.createGain();
  noiseGain.gain.setValueAtTime(0, 0);
  noiseFilter.connect(noiseGain);

  // Combine Sources
  const sourceSum = ctx.createGain();
  oscGainNode.connect(sourceSum);
  noiseGain.connect(sourceSum);

  // Sub-harmonics
  if (presetData.subHarmonics) {
      const subOsc = ctx.createOscillator();
      subOsc.type = 'square';
      subOsc.frequency.value = f0 / 2;
      const subGain = ctx.createGain();
      subGain.gain.value = 0.5;
      subOsc.connect(subGain);
      subGain.connect(sourceSum);
      subOsc.start(0);
  }

  // 5. Formant Filters (Parallel Bandpass)
  const filterOut = ctx.createGain();

  const filters = [0,1,2].map(i => {
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 4 + i; 
    const g = ctx.createGain();
    g.gain.value = 1.0; 
    sourceSum.connect(f);
    f.connect(g);
    g.connect(filterOut);
    return f;
  });

  // Nasal Branch
  let nasalOut: GainNode | null = null;
  const nasalF = ctx.createBiquadFilter();
  nasalF.type = 'bandpass';
  nasalF.frequency.value = 400;
  nasalF.Q.value = 3;
  nasalOut = ctx.createGain();
  nasalOut.gain.value = 0; // Controlled by sequence
  sourceSum.connect(nasalF);
  nasalF.connect(nasalOut);
  nasalOut.connect(master);

  // 6. Automation Sequencing
  // Word Gap Articulation Gain
  const articulationGain = ctx.createGain();
  articulationGain.gain.value = 1;
  filterOut.connect(articulationGain);

  let currentTime = 0;
  const rampMethod = presetData.steps ? 'setValueAtTime' : 'linearRampToValueAtTime'; // Linear for formants usually better for consonants

  phonemeSequence.forEach((item, idx) => {
    const { char, def } = item;
    const itemDur = def.durationScale * unitTime;
    const endTime = currentTime + itemDur;

    // Pitch automation for Speech Mode (Micro-prosody)
    if (params.mode === VocalMode.SPEECH) {
        // Vowels slightly higher/stable, consonants might drop
        // Random intonation drift based on Humanize
        const variance = (Math.random() * 2 - 1) * 0.1 * params.humanize;
    }

    // -- FORMANTS --
    let [t1, t2, t3] = def.formants;
    const scale = presetData.formantScale || 1.0;
    const shift = params.formantShift || 1.0;
    t1 *= scale * shift;
    t2 *= scale * shift;
    t3 *= scale * shift;

    // Clamp
    t1 = Math.max(50, Math.min(10000, t1));
    t2 = Math.max(50, Math.min(10000, t2));
    t3 = Math.max(50, Math.min(10000, t3));

    // Apply Formants
    if (idx === 0) {
        filters[0].frequency.setValueAtTime(t1, currentTime);
        filters[1].frequency.setValueAtTime(t2, currentTime);
        filters[2].frequency.setValueAtTime(t3, currentTime);
    } else {
        filters[0].frequency[rampMethod](t1, currentTime + (itemDur * 0.5));
        filters[1].frequency[rampMethod](t2, currentTime + (itemDur * 0.5));
        filters[2].frequency[rampMethod](t3, currentTime + (itemDur * 0.5));
    }

    // -- SOURCE MIXING (Osc vs Noise) --
    // Base Osc Level from preset
    const presetOscLevel = presetData.oscGain !== undefined ? presetData.oscGain : (1 - (presetData.breath || 0));
    // Def Osc Level (0 for consonants like p, t, k, s)
    const defOscLevel = def.gain; 
    const finalOscLevel = presetOscLevel * defOscLevel;

    oscGainNode.gain.setTargetAtTime(finalOscLevel, currentTime, 0.01);

    // Noise Level
    const presetBreath = (presetData.breath || 0) + params.breathiness * 0.2;
    // Def Noise Level (High for f, s, sh)
    const defNoiseLevel = def.noise;
    // Max of preset breath or consonant noise
    const finalNoiseLevel = Math.max(presetBreath, defNoiseLevel * 0.8);

    noiseGain.gain.setTargetAtTime(finalNoiseLevel, currentTime, 0.01);

    // Noise Color
    if (def.noiseType === 'highpass') {
        noiseFilter.frequency.setTargetAtTime(4000, currentTime, 0.01);
    } else if (def.noiseType === 'pink') {
        noiseFilter.frequency.setTargetAtTime(1000, currentTime, 0.01);
    } else {
        noiseFilter.frequency.setTargetAtTime(100, currentTime, 0.01); // White/Full
    }

    // -- NASAL MIX --
    const nasalTarget = (char.match(/[ãẽĩõũmnɲ]/)) ? (presetData.nasal || 0.4) : 0;
    nasalOut!.gain.setTargetAtTime(nasalTarget, currentTime, 0.05);

    // -- WORD GAP / PAUSE --
    if (char === ' ') {
        if (params.wordGap > 0) {
           articulationGain.gain.setTargetAtTime(0, currentTime, 0.005);
        }
    } else {
        if (params.wordGap > 0) {
           articulationGain.gain.setTargetAtTime(1, currentTime, 0.01);
        }
    }

    currentTime = endTime;
  });

  // 7. Post-Filter Effects
  let postFx = articulationGain; 
  if (presetData.amRate) {
      const am = ctx.createGain();
      const lfo = ctx.createOscillator();
      lfo.frequency.value = presetData.amRate;
      const lfoG = ctx.createGain();
      lfoG.gain.value = presetData.amDepth;
      const offset = ctx.createConstantSource();
      offset.offset.value = 1;

      lfo.connect(lfoG);
      lfoG.connect(am.gain);
      offset.connect(am.gain);

      articulationGain.disconnect();
      articulationGain.connect(am);
      postFx = am;

      lfo.start(0);
      offset.start(0);
  }

  if (presetData.bandpass) {
      const bpLow = ctx.createBiquadFilter();
      bpLow.type = 'highpass';
      bpLow.frequency.value = presetData.bandpass[0];
      const bpHigh = ctx.createBiquadFilter();
      bpHigh.type = 'lowpass';
      bpHigh.frequency.value = presetData.bandpass[1];

      postFx.connect(bpLow);
      bpLow.connect(bpHigh);
      postFx = bpHigh as unknown as GainNode; 
  }

  postFx.connect(master);

  osc.start(0);
  noiseSrc.start(0);
  osc.stop(duration);
  noiseSrc.stop(duration);

  const rendered = await ctx.startRendering();

  // 8. Buffer Post-Process
  const data = rendered.getChannelData(0);
  const len = data.length;

  if (presetData.roughness || params.jitter > 0) {
      const rAmount = (presetData.roughness || 0) + params.jitter;
      for(let i=0; i<len; i++) {
          data[i] *= 1 + ((Math.random() - 0.5) * rAmount);
      }
  }

  if (presetData.distortion) {
      const k = presetData.distortion;
      for(let i=0; i<len; i++) {
          data[i] = Math.tanh(k * data[i]);
      }
  } else if (presetData.clip) {
      const limit = presetData.clip;
      for(let i=0; i<len; i++) {
          if (data[i] > limit) data[i] = limit;
          if (data[i] < -limit) data[i] = -limit;
      }
  } else {
      for(let i=0; i<len; i++) data[i] = Math.tanh(data[i]);
  }

  return rendered;
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  VowelType, 
  VocalMode, 
  VocalPreset, 
  VocalParams, 
  GlobalParams,
  SequencerNote,
  SequencerTrack,
  AudioPresetDefinition
} from './types';
import { 
  renderVocals, 
  renderProject,
  applyReverb,
  bufferToWav,
  getFrequency,
  NOTE_FREQUENCIES,
  VOCAL_PRESETS_DATA
} from './services/audioEngine';
import { parseMidiFile } from './services/midiLoader';
import { ControlSlider } from './components/Knob';
import { PianoRoll } from './components/PianoRoll';
import { Visualizer } from './components/Visualizer';
import { 
  Play, Download, Mic, Activity, Settings, Music, Piano, Upload, 
  Save, FileJson, Type, X, Check, TrendingUp, Waves, Plus, Volume2, 
  VolumeX, Layers, Sliders, AudioWaveform, SquareActivity, Pause,
  Database, Copy, Calculator, FileCode, ArrowRight, Code, Terminal
} from 'lucide-react';

type Tab = 'COMPOSE' | 'RACK' | 'VOICE' | 'MATH' | 'DATA' | 'CALC';

const App: React.FC = () => {
  // --- STATE ---
  const [activeTab, setActiveTab] = useState<Tab>('COMPOSE');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedBuffer, setGeneratedBuffer] = useState<AudioBuffer | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playbackTime, setPlaybackTime] = useState(0); 

  // Audio Context
  const audioCtxRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const [analyserNode, setAnalyserNode] = useState<AnalyserNode | null>(null);

  // Global
  const [globalParams, setGlobalParams] = useState<GlobalParams>({
    bpm: 120, duration: 8.0, reverbMix: 0.1, reverbDecay: 2.0
  });
  const [selectedNote, setSelectedNote] = useState<string>('C');
  const [selectedOctave, setSelectedOctave] = useState<number>(4);

  // Tracks
  const [tracks, setTracks] = useState<SequencerTrack[]>([
    {
      id: 'track-1',
      name: 'Main Vocal',
      color: '#38bdf8',
      notes: [
         { id: '1', midi: 60, startTime: 0, duration: 1.0, lyric: 'o', pitchPoints: [{t:0,v:0},{t:1,v:0}] },
         { id: '2', midi: 62, startTime: 1.0, duration: 1.0, lyric: 'i', pitchPoints: [{t:0,v:0},{t:1,v:0}] },
         { id: '3', midi: 64, startTime: 2.0, duration: 2.0, lyric: 'e', pitchPoints: [{t:0,v:0},{t:1,v:0}] }
      ],
      volume: 0.8,
      muted: false,
      solo: false,
      vocalParams: {
        text: "OIE",
        preset: VocalPreset.MALE_BR,
        mode: VocalMode.SINGING,
        vowel: VowelType.A,
        jitter: 0.1, humanize: 0.1, breathiness: 0.2, formantShift: 1.0, speed: 1.0, pitch: 1.0, octaveShift: 0, glide: 0.1, wordGap: 0.05 
      }
    }
  ]);

  const [activeTrackId, setActiveTrackId] = useState<string>('track-1');

  // Custom Presets (CALC Tab)
  const [customPresets, setCustomPresets] = useState<Record<string, AudioPresetDefinition>>({});
  const [editorContent, setEditorContent] = useState<string>("");
  const [selectedEditorPreset, setSelectedEditorPreset] = useState<string>("");
  const [editorError, setEditorError] = useState<string | null>(null);

  // History
  const [history, setHistory] = useState<SequencerTrack[][]>([]);
  const [future, setFuture] = useState<SequencerTrack[][]>([]);

  // Modals
  const [showLyricsModal, setShowLyricsModal] = useState(false);
  const [showPitchModal, setShowPitchModal] = useState(false);
  const [lyricsInput, setLyricsInput] = useState("");

  // Pitch Editor
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);
  const [pitchCurve, setPitchCurve] = useState<{t:number, v:number}[]>([]);
  const pitchCanvasRef = useRef<HTMLCanvasElement>(null);

  // Helpers
  const activeTrack = tracks.find(t => t.id === activeTrackId) || tracks[0];
  const ghostTracks = tracks.filter(t => t.id !== activeTrackId);

  // History logic
  const addToHistory = useCallback(() => {
    setHistory(prev => [...prev, JSON.parse(JSON.stringify(tracks))]);
    setFuture([]); 
  }, [tracks]);

  const handleUndo = useCallback(() => {
    if (history.length === 0) return;
    const previous = history[history.length - 1];
    setFuture(prev => [tracks, ...prev]);
    setTracks(previous);
    setHistory(prev => prev.slice(0, -1));
  }, [history, tracks]);

  const handleRedo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    setHistory(prev => [...prev, tracks]);
    setTracks(next);
    setFuture(prev => prev.slice(1));
  }, [future, tracks]);

  const updateActiveTrack = (updates: Partial<SequencerTrack> | ((prev: SequencerTrack) => Partial<SequencerTrack>)) => {
      setTracks(prev => prev.map(t => {
          if (t.id !== activeTrackId) return t;
          const newVals = typeof updates === 'function' ? updates(t) : updates;
          return { ...t, ...newVals };
      }));
  };

  const updateActiveTrackParams = (updates: Partial<VocalParams> | ((prev: VocalParams) => Partial<VocalParams>)) => {
      setTracks(prev => prev.map(t => {
          if (t.id !== activeTrackId) return t;
          const currentParams = t.vocalParams;
          const newParams = typeof updates === 'function' ? updates(currentParams) : updates;
          return { ...t, vocalParams: { ...currentParams, ...newParams } };
      }));
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        e.preventDefault();
        e.shiftKey ? handleRedo() : handleUndo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleUndo, handleRedo]);


  const fileInputRef = useRef<HTMLInputElement>(null);
  const jsonInputRef = useRef<HTMLInputElement>(null);

  // --- AUDIO LOGIC ---

  const handleGenerate = async () => {
    setIsGenerating(true);
    setGeneratedBuffer(null);
    setTimeout(async () => {
      try {
        const sampleRate = 44100;
        let buffer: AudioBuffer;
        const secondsPerBeat = 60 / globalParams.bpm;
        let totalBeats = 16; 
        tracks.forEach(t => {
            if (t.notes.length > 0) {
                  const last = t.notes.reduce((max, curr) => Math.max(max, curr.startTime + curr.duration), 0);
                  if (last + 4 > totalBeats) totalBeats = last + 4;
            }
        });
        const totalSeconds = totalBeats * secondsPerBeat;
        const ctx = new OfflineAudioContext(1, sampleRate * totalSeconds, sampleRate);
        buffer = await renderProject(ctx, tracks, globalParams.bpm);
        if (globalParams.reverbMix > 0) {
            const reverbCtx = new OfflineAudioContext(1, buffer.length, sampleRate);
            buffer = await applyReverb(reverbCtx, buffer, globalParams.reverbMix, globalParams.reverbDecay);
        }
        setGeneratedBuffer(buffer);
      } catch (e) { console.error(e); alert("Error generating audio"); } finally { setIsGenerating(false); }
    }, 50);
  };

  const handleMidiUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                addToHistory(); 
                const { tracks: newTracks, bpm } = parseMidiFile(ev.target.result as ArrayBuffer);
                setTracks(newTracks);
                if (newTracks.length > 0) setActiveTrackId(newTracks[0].id);
                setGlobalParams(p => ({ ...p, bpm: bpm || 120 }));
                alert(`Imported ${newTracks.length} tracks at ${bpm} BPM!`);
            } catch (err) { console.error(err); alert("Failed to parse file."); }
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAddTrack = () => {
      addToHistory();
      const newTrack: SequencerTrack = {
          id: `track-${Date.now()}`,
          name: `Track ${tracks.length + 1}`,
          color: '#38bdf8',
          notes: [],
          volume: 0.8,
          muted: false,
          solo: false,
          vocalParams: { ...activeTrack.vocalParams, preset: VocalPreset.FEMALE_BR } 
      };
      setTracks(prev => [...prev, newTrack]);
      setActiveTrackId(newTrack.id);
  };

  const handleDeleteTrack = (id: string) => {
      if (tracks.length <= 1) return;
      addToHistory();
      const newTracks = tracks.filter(t => t.id !== id);
      setTracks(newTracks);
      if (activeTrackId === id) setActiveTrackId(newTracks[0].id);
  };

  const handleApplyLyrics = () => {
      if (!lyricsInput.trim()) { setShowLyricsModal(false); return; }
      addToHistory();
      const syllabify = (text: string) => {
        const regex = /[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]*[aeiouyáéíóúãõâêîôûàèìòùäëïöü]+(?:[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]*$|[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ](?=[^aeiouyáéíóúãõâêîôûàèìòùäëïöüçñ]))?/gi;
        return text.match(regex) || [text];
      };
      const rawWords = lyricsInput.replace(/[\n\r]/g, ' ').split(/[\s-]+/).filter(s => s.length > 0);
      let syllables: string[] = [];
      rawWords.forEach(word => word.length > 2 ? syllables.push(...syllabify(word)) : syllables.push(word));
      if (syllables.length === 0) return;

      let tempNotes = [...activeTrack.notes].sort((a, b) => a.startTime - b.startTime);
      const finalNotes = tempNotes.map((note, index) => {
          return index < syllables.length ? { ...note, lyric: syllables[index] } : { ...note, lyric: '' };
      });
      updateActiveTrack({ notes: finalNotes });
      setLyricsInput(""); setShowLyricsModal(false);
  };

  const handleOpenPitchEditor = (noteId: string) => {
      const note = activeTrack.notes.find(n => n.id === noteId); if (!note) return;
      setEditingNoteId(noteId);
      setPitchCurve(note.pitchPoints && note.pitchPoints.length > 0 ? note.pitchPoints : [{t:0,v:0}, {t:1,v:0}]);
      setShowPitchModal(true);
  };

  const handlePitchCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
      const canvas = pitchCanvasRef.current; if (!canvas) return;
      const rect = canvas.getBoundingClientRect();
      const t = (e.clientX - rect.left) / canvas.width;
      const semitones = 12 - ((e.clientY - rect.top) / canvas.height) * 24;
      const newCurve = [...pitchCurve, { t, v: semitones }].sort((a,b) => a.t - b.t);
      setPitchCurve(newCurve);
  };

  const drawPitchCurve = () => {
      const canvas = pitchCanvasRef.current; if (!canvas) return;
      const ctx = canvas.getContext('2d'); if (!ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.strokeStyle = '#334155'; ctx.beginPath(); ctx.moveTo(0, canvas.height/2); ctx.lineTo(canvas.width, canvas.height/2); ctx.stroke();
      ctx.strokeStyle = '#f472b6'; ctx.lineWidth = 3; ctx.beginPath();
      if (pitchCurve.length > 0) {
          const getY = (v: number) => canvas.height/2 - (v/12)*(canvas.height/2);
          pitchCurve.forEach((pt, i) => {
              const x = pt.t * canvas.width; const y = getY(pt.v);
              i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
              ctx.fillStyle = '#fff'; ctx.fillRect(x-2, y-2, 4, 4);
          });
      }
      ctx.stroke();
  };
  useEffect(() => { if (showPitchModal) requestAnimationFrame(drawPitchCurve); }, [pitchCurve, showPitchModal]);

  const handleApplyPitch = () => {
      if (!editingNoteId) return;
      addToHistory();
      const updatedNotes = activeTrack.notes.map(n => n.id === editingNoteId ? { ...n, pitchPoints: pitchCurve } : n);
      updateActiveTrack({ notes: updatedNotes });
      setShowPitchModal(false);
  };

  const handlePlay = () => {
    if (!generatedBuffer) return;
    if (!audioCtxRef.current) audioCtxRef.current = new AudioContext();
    const ctx = audioCtxRef.current; if (ctx.state === 'suspended') ctx.resume();
    if (sourceRef.current) try { sourceRef.current.stop(); } catch(e) {}
    const source = ctx.createBufferSource();
    source.buffer = generatedBuffer;
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 2048;
    setAnalyserNode(analyser); 
    source.connect(analyser);
    analyser.connect(ctx.destination);
    source.onended = () => setIsPlaying(false);
    sourceRef.current = source;
    setIsPlaying(true);
    source.start();
  };

  const handleStop = () => {
      if (sourceRef.current) { try { sourceRef.current.stop(); } catch(e){} setIsPlaying(false); }
  };

  const handleDownload = () => {
    if (!generatedBuffer) return;
    const url = URL.createObjectURL(bufferToWav(generatedBuffer));
    const a = document.createElement('a'); a.href = url; a.download = `vocalstudio_${Date.now()}.wav`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  };

  const handleExportJson = () => {
    const data = { version: 1, timestamp: Date.now(), tracks: tracks, globalParams: globalParams };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = `project_${Date.now()}.json`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
  };

  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]; if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
        if (ev.target?.result) {
            try {
                const data = JSON.parse(ev.target.result as string);
                addToHistory();
                if (data.tracks) { setTracks(data.tracks); setActiveTrackId(data.tracks[0].id); }
                if (data.globalParams) setGlobalParams(data.globalParams);
                alert("Project loaded!");
            } catch (err) { console.error(err); alert("Invalid project file."); }
        }
    };
    reader.readAsText(file);
  };

  const copyToClipboard = (data: any) => {
      const txt = JSON.stringify(data, null, 2);
      navigator.clipboard.writeText(txt);
      alert("Copied to clipboard!");
  };

  // --- EDITOR LOGIC (CALC TAB) ---
  const handleEditorSelect = (presetName: string, isCustom: boolean) => {
      setSelectedEditorPreset(presetName);
      if (isCustom) {
          setEditorContent(JSON.stringify(customPresets[presetName], null, 2));
      } else {
          // @ts-ignore
          setEditorContent(JSON.stringify(VOCAL_PRESETS_DATA[presetName], null, 2));
      }
      setEditorError(null);
  };

  const handleSaveCustomPreset = () => {
      try {
          const parsed = JSON.parse(editorContent);
          const name = prompt("Name for this custom calculation:", selectedEditorPreset || "My_Custom_Algo");
          if (!name) return;

          setCustomPresets(prev => ({
              ...prev,
              [name]: parsed
          }));
          setSelectedEditorPreset(name);
          setEditorError(null);
      } catch (e) {
          setEditorError("Invalid JSON syntax.");
      }
  };

  const handleApplyCustomToTrack = () => {
       try {
          const parsed = JSON.parse(editorContent);
          addToHistory();
          updateActiveTrackParams({
              preset: VocalPreset.CUSTOM,
              customData: parsed
          });
          alert("Calculation applied to active track!");
       } catch (e) {
           setEditorError("Cannot apply invalid JSON.");
       }
  };


  return (
    <div className="flex flex-col h-screen bg-synth-dark text-slate-200 font-sans overflow-hidden">

      {/* HEADER */}
      <header className="px-4 py-3 bg-synth-dark/95 border-b border-synth-grid flex justify-between items-center shrink-0 z-20">
        <div className="flex items-center gap-2">
          <Activity size={20} className="text-synth-accent" />
          <div>
            <h1 className="text-sm font-bold tracking-widest bg-gradient-to-r from-synth-accent to-synth-pop bg-clip-text text-transparent">
              VocalStudio
            </h1>
            <p className="text-[9px] text-slate-500 font-mono leading-none">DSP WORKSTATION</p>
          </div>
        </div>

        <div className="flex gap-2">
             <button onClick={handleExportJson} className="p-2 rounded-lg bg-synth-panel border border-synth-grid text-slate-400 hover:text-white transition-colors" title="Save Project"><Save size={14} /></button>
             <button onClick={() => jsonInputRef.current?.click()} className="p-2 rounded-lg bg-synth-panel border border-synth-grid text-slate-400 hover:text-white transition-colors" title="Load Project"><FileJson size={14} /></button>
             <input type="file" accept=".json" className="hidden" ref={jsonInputRef} onChange={handleImportJson}/>
        </div>
      </header>

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden relative p-4 pb-32 scroll-smooth">

        {/* TAB: COMPOSE (Piano Roll) */}
        {activeTab === 'COMPOSE' && (
            <div className="flex flex-col h-full gap-4 animate-in fade-in zoom-in-95 duration-200">
                 {/* Top Toolbar */}
                 <div className="flex justify-between items-center flex-wrap gap-2 bg-synth-panel/50 p-2 rounded-xl border border-synth-grid/50">
                     <div className="flex items-center gap-2">
                        <div className="flex flex-col">
                            <span className="text-[9px] text-synth-accent font-bold uppercase">Octave</span>
                            <div className="flex items-center bg-synth-dark rounded border border-synth-grid">
                                <input type="number" min="-3" max="3" value={activeTrack.vocalParams.octaveShift} onChange={(e) => updateActiveTrackParams({ octaveShift: parseInt(e.target.value) })} className="w-8 text-center bg-transparent text-xs outline-none py-1"/>
                            </div>
                        </div>
                        <div className="flex flex-col">
                             <span className="text-[9px] text-synth-accent font-bold uppercase">Glide</span>
                             <input type="range" min="0" max="1" step="0.05" value={activeTrack.vocalParams.glide} onChange={(e) => updateActiveTrackParams({ glide: parseFloat(e.target.value) })} className="w-16 h-4 accent-synth-pop bg-gray-700 appearance-none rounded-full"/>
                        </div>
                     </div>

                     <div className="flex gap-2">
                         <button onClick={() => setShowLyricsModal(true)} className="text-[10px] bg-synth-dark border border-synth-grid px-3 py-1.5 rounded flex items-center gap-1 hover:bg-slate-700 text-white font-bold"><Type size={12} className="text-synth-accent"/> LYRICS</button>
                         <button onClick={() => fileInputRef.current?.click()} className="text-[10px] bg-synth-dark border border-synth-grid px-3 py-1.5 rounded flex items-center gap-1 hover:bg-slate-700"><Upload size={12} className="text-synth-pop"/> IMPORT MIDI</button>
                         <input type="file" accept=".mid,.midi,.rtx,.txt" className="hidden" ref={fileInputRef} onChange={handleMidiUpload}/>
                     </div>
                 </div>

                 {/* Piano Roll Component */}
                 <div className="flex-1 min-h-[400px]">
                     <PianoRoll 
                        notes={activeTrack.notes}
                        setNotes={(newNotes) => {
                             if (typeof newNotes === 'function') {
                                 setTracks(prev => prev.map(t => t.id === activeTrackId ? { ...t, notes: newNotes(t.notes) } : t));
                             } else {
                                 updateActiveTrack({ notes: newNotes });
                             }
                        }}
                        ghostTracks={ghostTracks}
                        durationBeats={tracks.reduce((max, t) => Math.max(max, t.notes.reduce((m, n) => Math.max(m, n.startTime + n.duration), 0)), 0) + 4}
                        onUndo={handleUndo} onRedo={handleRedo} addToHistory={addToHistory} canUndo={history.length > 0} canRedo={future.length > 0} onEditPitch={handleOpenPitchEditor}
                    />
                 </div>
            </div>
        )}

        {/* TAB: RACK (Mixer) */}
        {activeTab === 'RACK' && (
            <div className="max-w-md mx-auto space-y-4 animate-in slide-in-from-right-8 duration-200">
                <div className="flex justify-between items-end mb-2">
                    <h2 className="text-sm font-bold text-synth-accent flex items-center gap-2"><Layers size={16}/> TRACK MANAGER</h2>
                    <button onClick={handleAddTrack} className="text-[10px] bg-synth-pop hover:bg-pink-600 text-white px-3 py-1 rounded-full font-bold flex items-center gap-1 shadow-lg shadow-pink-900/20"><Plus size={12}/> ADD TRACK</button>
                </div>

                <div className="grid gap-3">
                    {tracks.map(track => (
                        <div key={track.id} onClick={() => setActiveTrackId(track.id)} className={`relative p-3 rounded-xl border transition-all cursor-pointer overflow-hidden group ${activeTrackId === track.id ? 'bg-synth-panel border-synth-accent shadow-lg shadow-sky-900/10' : 'bg-synth-panel/40 border-synth-grid hover:border-slate-500'}`}>
                            <div className="absolute left-0 top-0 bottom-0 w-1.5" style={{backgroundColor: track.color}}/>

                            <div className="flex items-center gap-3 pl-2">
                                <div className="flex-1">
                                    <div className="flex justify-between items-center mb-1">
                                        <span className={`text-xs font-bold ${activeTrackId === track.id ? 'text-white' : 'text-slate-400'}`}>{track.name}</span>
                                        {activeTrackId === track.id && <span className="text-[9px] px-1.5 py-0.5 rounded bg-synth-accent/20 text-synth-accent">ACTIVE</span>}
                                    </div>
                                    <input 
                                        type="range" min="0" max="1" step="0.05" 
                                        value={track.volume}
                                        onClick={(e) => e.stopPropagation()}
                                        onChange={(e) => {
                                            const v = parseFloat(e.target.value);
                                            setTracks(prev => prev.map(t => t.id === track.id ? { ...t, volume: v } : t));
                                        }}
                                        className="w-full h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-synth-accent"
                                    />
                                </div>

                                <div className="flex gap-1">
                                    <button onClick={(e) => { e.stopPropagation(); setTracks(prev => prev.map(t => t.id === track.id ? { ...t, muted: !t.muted } : t)); }} className={`w-8 h-8 rounded flex items-center justify-center transition-colors ${track.muted ? 'bg-red-500 text-white' : 'bg-slate-800 text-slate-500 hover:text-white'}`}>
                                        {track.muted ? <VolumeX size={14}/> : <Volume2 size={14}/>}
                                    </button>
                                    <button onClick={(e) => { e.stopPropagation(); setTracks(prev => prev.map(t => t.id === track.id ? { ...t, solo: !t.solo } : t)); }} className={`w-8 h-8 rounded flex items-center justify-center font-bold text-[10px] transition-colors ${track.solo ? 'bg-yellow-400 text-black' : 'bg-slate-800 text-slate-500 hover:text-white'}`}>S</button>
                                </div>
                            </div>

                            {tracks.length > 1 && (
                                <button onClick={(e) => { e.stopPropagation(); handleDeleteTrack(track.id); }} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity text-slate-600 hover:text-red-400"><X size={12}/></button>
                            )}
                        </div>
                    ))}
                </div>

                <div className="bg-synth-panel/30 p-4 rounded-xl border border-synth-grid mt-6">
                    <h3 className="text-[10px] font-bold text-slate-500 uppercase mb-3">Master Effects</h3>
                    <div className="flex gap-4">
                        <ControlSlider label="BPM" value={globalParams.bpm} min={60} max={200} step={1} onChange={(v) => setGlobalParams(p => ({...p, bpm: v}))} className="flex-1 bg-transparent border-none p-0" />
                        <ControlSlider label="Reverb" value={globalParams.reverbMix} min={0} max={0.8} onChange={(v) => setGlobalParams(p => ({...p, reverbMix: v}))} className="flex-1 bg-transparent border-none p-0" />
                    </div>
                </div>
            </div>
        )}

        {/* TAB: VOICE (Parameters) */}
        {activeTab === 'VOICE' && (
             <div className="max-w-md mx-auto space-y-6 animate-in slide-in-from-right-8 duration-200">
                <div className="flex items-center gap-2 mb-2">
                    <div className="w-2 h-8 rounded-full" style={{backgroundColor: activeTrack.color}} />
                    <div>
                        <h2 className="text-sm font-bold text-white uppercase">{activeTrack.name}</h2>
                        <p className="text-[10px] text-slate-500">VOICE SYNTHESIS PARAMETERS</p>
                    </div>
                </div>

                <div className="bg-synth-panel rounded-xl p-4 border border-synth-grid space-y-4">
                    <div>
                        <label className="text-[10px] font-bold text-synth-accent uppercase mb-1 block">Preset</label>
                        <select value={activeTrack.vocalParams.preset} onChange={(e) => updateActiveTrackParams({ preset: e.target.value as VocalPreset })} className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 text-sm text-white outline-none focus:border-synth-pop">
                            {Object.values(VocalPreset).map(preset => (<option key={preset} value={preset}>{preset}</option>))}
                        </select>
                        {activeTrack.vocalParams.preset === VocalPreset.CUSTOM && (
                             <p className="text-[9px] text-emerald-400 mt-1 italic">Using custom calculation defined in CALC tab.</p>
                        )}
                    </div>

                    <div className="flex bg-slate-800 rounded-lg p-1">
                        {Object.values(VocalMode).map(m => (
                            <button key={m} onClick={() => updateActiveTrackParams({ mode: m as VocalMode })} className={`flex-1 py-2 text-[10px] font-bold rounded uppercase transition-all ${activeTrack.vocalParams.mode === m ? 'bg-synth-pop text-white shadow' : 'text-slate-400 hover:text-white'}`}>{m}</button>
                        ))}
                    </div>
                </div>

                <div className="space-y-3">
                     <h3 className="text-[10px] font-bold text-slate-500 uppercase px-1">Timbre & Formants</h3>
                     <ControlSlider label="Formant Shift" value={activeTrack.vocalParams.formantShift} min={0.5} max={2.0} onChange={(v) => updateActiveTrackParams({ formantShift: v })} unit="x" />
                     <ControlSlider label="Breathiness" value={activeTrack.vocalParams.breathiness} min={0} max={1.0} onChange={(v) => updateActiveTrackParams({ breathiness: v })} />
                     <ControlSlider label="Timbre Jitter" value={activeTrack.vocalParams.jitter} min={0} max={0.5} onChange={(v) => updateActiveTrackParams({ jitter: v })} />
                </div>

                <div className="space-y-3">
                     <h3 className="text-[10px] font-bold text-slate-500 uppercase px-1">Performance</h3>
                     <ControlSlider label="Humanize" value={activeTrack.vocalParams.humanize} min={0} max={1.0} onChange={(v) => updateActiveTrackParams({ humanize: v })} />
                     <ControlSlider label="Pitch Scale" value={activeTrack.vocalParams.pitch} min={0.5} max={2.0} onChange={(v) => updateActiveTrackParams({ pitch: v })} unit="x" />
                </div>
             </div>
        )}

        {/* TAB: MATH / VISUALIZER */}
        {activeTab === 'MATH' && (
            <div className="h-full flex flex-col gap-4 animate-in zoom-in-95 duration-300">
                <div className="flex justify-between items-end px-2">
                    <div>
                        <h2 className="text-sm font-bold text-synth-pop flex items-center gap-2"><SquareActivity size={16}/> LIVE CALCULATIONS</h2>
                        <p className="text-[10px] text-slate-500">REAL-TIME DSP MONITORING</p>
                    </div>
                    {isPlaying && <div className="flex gap-1"><span className="w-1 h-1 bg-green-500 rounded-full animate-ping"/><span className="text-[9px] text-green-500 font-bold">PROCESSING</span></div>}
                </div>

                <div className="flex-1 min-h-[300px] relative">
                    <Visualizer analyser={analyserNode} isPlaying={isPlaying} />
                </div>
            </div>
        )}

        {/* TAB: DATA (Read Only) */}
        {activeTab === 'DATA' && (
            <div className="h-full flex flex-col gap-4 animate-in slide-in-from-right-8 duration-200">
                 <div className="flex items-center gap-2 px-2">
                    <Database size={20} className="text-emerald-400" />
                    <div>
                        <h2 className="text-sm font-bold text-emerald-400 uppercase">CALCULATION DATA</h2>
                        <p className="text-[10px] text-slate-500">RAW ENGINE PARAMETERS</p>
                    </div>
                </div>

                <div className="flex-1 overflow-auto bg-black rounded-xl border border-synth-grid p-4 font-mono text-[10px] space-y-6">
                    <div>
                        <div className="flex justify-between items-center mb-2 border-b border-gray-800 pb-1">
                            <h3 className="text-slate-400 font-bold">ACTIVE CONFIG</h3>
                            <button onClick={() => copyToClipboard(VOCAL_PRESETS_DATA[activeTrack.vocalParams.preset])} className="flex items-center gap-1 text-emerald-500 hover:text-emerald-300"><Copy size={12}/> COPY</button>
                        </div>
                        <pre className="text-emerald-700/80 whitespace-pre-wrap">
                            {JSON.stringify(activeTrack.vocalParams.preset === VocalPreset.CUSTOM ? activeTrack.vocalParams.customData : VOCAL_PRESETS_DATA[activeTrack.vocalParams.preset], null, 2)}
                        </pre>
                    </div>
                </div>
            </div>
        )}

        {/* TAB: CALC (New Editor) */}
        {activeTab === 'CALC' && (
            <div className="h-full flex flex-col gap-4 animate-in zoom-in-95 duration-200">
                <div className="flex justify-between items-end px-2">
                    <div>
                        <h2 className="text-sm font-bold text-orange-400 flex items-center gap-2"><Calculator size={16}/> ALGO EDITOR</h2>
                        <p className="text-[10px] text-slate-500">DEFINE CUSTOM DSP MATHEMATICS</p>
                    </div>
                    <button onClick={handleSaveCustomPreset} className="text-[10px] bg-orange-500/20 text-orange-400 border border-orange-500/50 px-2 py-1 rounded hover:bg-orange-500/40">SAVE AS NEW</button>
                </div>

                <div className="flex-1 flex gap-4 min-h-0">
                    {/* Left: Preset List */}
                    <div className="w-1/3 bg-synth-panel rounded-xl border border-synth-grid overflow-hidden flex flex-col">
                        <div className="p-2 bg-synth-dark border-b border-synth-grid text-[10px] font-bold text-slate-400 uppercase">Library</div>
                        <div className="overflow-y-auto flex-1 p-2 space-y-1">
                            {/* Custom Presets */}
                            {Object.keys(customPresets).length > 0 && (
                                <div className="mb-2">
                                    <div className="text-[9px] text-orange-500 font-bold mb-1">USER</div>
                                    {Object.keys(customPresets).map(name => (
                                        <button 
                                            key={name}
                                            onClick={() => handleEditorSelect(name, true)}
                                            className={`w-full text-left text-[10px] px-2 py-1.5 rounded truncate ${selectedEditorPreset === name ? 'bg-orange-500 text-black font-bold' : 'text-slate-300 hover:bg-slate-700'}`}
                                        >
                                            {name}
                                        </button>
                                    ))}
                                </div>
                            )}

                             {/* Built-in Presets */}
                             <div>
                                <div className="text-[9px] text-synth-accent font-bold mb-1">FACTORY</div>
                                {Object.keys(VOCAL_PRESETS_DATA).filter(k => k !== 'CUSTOM / USER').map(name => (
                                    <button 
                                        key={name}
                                        onClick={() => handleEditorSelect(name, false)}
                                        className={`w-full text-left text-[10px] px-2 py-1.5 rounded truncate ${selectedEditorPreset === name ? 'bg-synth-accent text-black font-bold' : 'text-slate-400 hover:bg-slate-700'}`}
                                    >
                                        {name}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Right: Code Editor */}
                    <div className="flex-1 flex flex-col gap-2">
                        <div className="flex-1 relative group">
                            <textarea 
                                value={editorContent}
