  's': { formants: [500, 4000, 6000], gain: 0.1, noise: 1.0, noiseType: 'highpass', durationScale: 0.4 },
  'z': { formants: [300, 3500, 5500], gain: 0.4, noise: 0.6, noiseType: 'highpass', durationScale: 0.4 },
  'ʃ': { formants: [500, 2500, 4500], gain: 0.1, noise: 1.0, noiseType: 'highpass', durationScale: 0.5 }, // ch/x
  'ʒ': { formants: [300, 2500, 4500], gain: 0.4, noise: 0.6, noiseType: 'highpass', durationScale: 0.5 }, // j/g

  // Nasals
  'm': { formants: [250, 1000, 2500], gain: 0.7, noise: 0.05, durationScale: 0.6 },
  'n': { formants: [250, 1500, 2500], gain: 0.7, noise: 0.05, durationScale: 0.6 },
  'ɲ': { formants: [250, 2000, 3000], gain: 0.7, noise: 0.05, durationScale: 0.6 }, // nh

  // Liquids
  'l': { formants: [400, 1200, 2800], gain: 0.8, noise: 0.0, durationScale: 0.5 },
  'ʎ': { formants: [350, 2000, 3000], gain: 0.8, noise: 0.0, durationScale: 0.5 }, // lh
  'ʁ': { formants: [500, 1500, 2500], gain: 0.3, noise: 0.7, durationScale: 0.4 }, // rr (Gutteral/Fricative R)
  'ɾ': { formants: [400, 1500, 2500], gain: 0.5, noise: 0.1, durationScale: 0.15 }, // r (Flap)

  // Special
  '_': { formants: [500, 1500, 2500], gain: 0.0, noise: 0.0, durationScale: 1.0 }, // Silence/Pause
  ' ': { formants: [500, 1500, 2500], gain: 0.0, noise: 0.0, durationScale: 1.0 }  // Space
};

// 2. Parser Logic
const textToPhonemes = (text: string): string[] => {
  let s = text.toLowerCase();

  // Remove Punctuation but keep spaces
  s = s.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "");

  // 1. Digraphs (Map to internal unique markers to avoid collision)
  s = s.replace(/nh/g, 'ɲ');
  s = s.replace(/lh/g, 'ʎ');
  s = s.replace(/ch/g, 'ʃ');
  s = s.replace(/rr/g, 'ʁ');
  s = s.replace(/ss/g, 's'); 

  // 2. Contextual Consonants
  s = s.replace(/c(?=[eiéí])/g, 's');
  s = s.replace(/c/g, 'k');
  s = s.replace(/qu(?=[eiéí])/g, 'k');
  s = s.replace(/q/g, 'k');
  s = s.replace(/g(?=[eiéí])/g, 'ʒ');
  s = s.replace(/gu(?=[eiéí])/g, 'g'); 

  // S between vowels -> z
  // Simplified Regex: Vowel + s + Vowel
  s = s.replace(/([aeiouáéíóúãẽĩõũ])s([aeiouáéíóúãẽĩõũ])/g, '$1z$2');

  // 3. Nasalization (Vowel + m/n at end of word or before consonant)
  // End of word
  s = s.replace(/am\b/g, 'ã');
  s = s.replace(/em\b/g, 'ẽ');
  s = s.replace(/im\b/g, 'ĩ');
  s = s.replace(/om\b/g, 'õ');
  s = s.replace(/um\b/g, 'ũ');
  s = s.replace(/an\b/g, 'ã');
  s = s.replace(/en\b/g, 'ẽ');
  s = s.replace(/in\b/g, 'ĩ');
  s = s.replace(/on\b/g, 'õ');
  s = s.replace(/un\b/g, 'ũ');

  // 4. R rules
  // Start of word R is strong
  s = s.replace(/^r/, 'ʁ'); 
  // R followed by space (end) -> Flap or Soft? Let's use Flap ɾ for standard singing
  s = s.replace(/r\b/g, 'ɾ'); 
  // Remaining single R's usually flaps
  s = s.replace(/r/g, 'ɾ'); 

  // 5. Explicit Mapping of Remaining Characters
  // Split and filter only what we know
  const tokens = s.split('');
  const output: string[] = [];

  for (const char of tokens) {
    if (PHONEME_LIB[char]) {
      output.push(char);
    } else {
      // Fallback for accents not covered or unknown chars
      if (char === 'á' || char === 'à' || char === 'â') output.push('a');
      else if (char === 'é' || char === 'ê') output.push('e'); // or ɛ
      else if (char === 'í') output.push('i');
      else if (char === 'ó' || char === 'ô') output.push('o'); // or ɔ
      else if (char === 'ú') output.push('u');
      else if (char === 'ç') output.push('s');
      else if (char === 'j') output.push('ʒ');
      else if (char === 'x') output.push('ʃ'); // Simplified X rule
      else if (char === 'h') { /* silent h, skip */ }
      else if (char === ' ') output.push(' ');
      // else skip
    }
  }

  return output;
};


