  [VocalPreset.HAPPY]: { baseFreq: 220, formantScale: 1.05, breath: 0.05, pitchRise: true, vibrato: {depth: 0.006, rate: 6}, type: 'sawtooth' },
  [VocalPreset.ANGRY]: { baseFreq: 160, formantScale: 1.1, breath: 0.1, roughness: 0.3, type: 'sawtooth' },
  [VocalPreset.FALSETTO]: { baseFreq: 400, formantScale: 0.9, breath: 0.6, type: 'sine' },
  [VocalPreset.ANDROGYNOUS]: { baseFreq: 175, formantScale: 1.0, breath: 0.03, type: 'triangle' },
