                                <input type="number" min="-3" max="3" value={activeTrack.vocalParams.octaveShift} onChange={(e) => updateActiveTrackParams({ octaveShift: parseInt(e.target.value) })} className="w-8 text-center bg-transparent text-xs outline-none py-1"/>
                            </div>
                        </div>
                        <div className="flex flex-col">
                             <span className="text-[9px] text-synth-accent font-bold uppercase">Glide</span>
                             <input type="range" min="0" max="1" step="0.05" value={activeTrack.vocalParams.glide} onChange={(e) => updateActiveTrackParams({ glide: parseFloat(e.target.value) })} className="w-16 h-4 accent-synth-pop bg-gray-700 appearance-none rounded-full"/>
                        </div>
                     </div>

                     <div className="flex gap-2">
