                         <button onClick={() => fileInputRef.current?.click()} className="text-[10px] bg-synth-dark border border-synth-grid px-3 py-1.5 rounded flex items-center gap-1 hover:bg-slate-700"><Upload size={12} className="text-synth-pop"/> IMPORT MIDI</button>
                         <input type="file" accept=".mid,.midi,.rtx,.txt" className="hidden" ref={fileInputRef} onChange={handleMidiUpload}/>
                     </div>
                 </div>

                 {/* Piano Roll Component */}
                 <div className="flex-1 min-h-[400px]">
                     <PianoRoll 
