                                <div className="flex gap-1">
                                    <button onClick={(e) => { e.stopPropagation(); setTracks(prev => prev.map(t => t.id === track.id ? { ...t, muted: !t.muted } : t)); }} className={`w-8 h-8 rounded flex items-center justify-center transition-colors ${track.muted ? 'bg-red-500 text-white' : 'bg-slate-800 text-slate-500 hover:text-white'}`}>
                                        {track.muted ? <VolumeX size={14}/> : <Volume2 size={14}/>}
                                    </button>
                                    <button onClick={(e) => { e.stopPropagation(); setTracks(prev => prev.map(t => t.id === track.id ? { ...t, solo: !t.solo } : t)); }} className={`w-8 h-8 rounded flex items-center justify-center font-bold text-[10px] transition-colors ${track.solo ? 'bg-yellow-400 text-black' : 'bg-slate-800 text-slate-500 hover:text-white'}`}>S</button>
                                </div>
                            </div>

                            {tracks.length > 1 && (
                                <button onClick={(e) => { e.stopPropagation(); handleDeleteTrack(track.id); }} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity text-slate-600 hover:text-red-400"><X size={12}/></button>
