                        <div className="overflow-y-auto flex-1 p-2 space-y-1">
                            {/* Custom Presets */}
                            {calcMode === 'ALGO' && (
                                <>
                                    {Object.keys(customPresets).length > 0 && (
                                        <div className="mb-2">
                                            <div className="text-[9px] text-synth-accent font-bold mb-1">USER</div>
                                            {Object.keys(customPresets).map(name => (
                                                <button 
                                                    key={name}
                                                    onClick={() => handleEditorSelect(name, true)}
                                                    className={`w-full text-left text-[10px] px-2 py-1.5 rounded truncate ${selectedEditorPreset === name ? 'bg-synth-accent text-black font-bold' : 'text-slate-300 hover:bg-slate-700'}`}
                                                >
                                                    {name}
