                                            <button 
                                                key={name}
                                                onClick={() => handleEditorSelect(name, false)}
                                                className={`w-full text-left text-[10px] px-2 py-1.5 rounded truncate ${selectedEditorPreset === name ? 'bg-synth-accent text-black font-bold' : 'text-slate-400 hover:bg-slate-700'}`}
                                            >
                                                {name}
                                            </button>
                                        ))}
                                    </div>
                                </>
                            )}

                             {/* Plugin Library */}
                             {calcMode === 'PLUGIN' && (
                                <>
                                    {Object.keys(pluginLibrary).map(name => (
                                        <button 
                                            key={name}
                                            onClick={() => handleEditorSelect(name, true)}
                                            className={`w-full text-left text-[10px] px-2 py-1.5 rounded truncate ${selectedEditorPreset === name ? 'bg-orange-500 text-black font-bold' : 'text-slate-300 hover:bg-slate-700'}`}
                                        >
                                            {name}
                                        </button>
                                    ))}
