                            <button 
                                onClick={handleApplyCustomToTrack}
                                className="flex-1 bg-orange-500 hover:bg-orange-600 text-black font-bold py-3 rounded-xl shadow-lg flex items-center justify-center gap-2 active:scale-95 transition-transform"
                            >
                                <Code size={16}/> APPLY TO ACTIVE TRACK
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}


        <div className="h-20" />
      </main>

      {/* FLOATING ACTION DOCK */}
      <div className="fixed bottom-20 left-0 right-0 z-40 flex justify-center pointer-events-none">
          <div className="bg-synth-dark/90 backdrop-blur-md border border-synth-grid p-2 rounded-2xl shadow-2xl flex items-center gap-3 pointer-events-auto transform transition-transform hover:scale-105">
              <button 
                onClick={isPlaying ? handleStop : handlePlay}
                disabled={!generatedBuffer}
                className={`w-12 h-12 rounded-xl flex items-center justify-center shadow-lg transition-all ${
                    !generatedBuffer ? 'bg-slate-800 text-slate-600' : 
                    isPlaying ? 'bg-red-500 text-white shadow-red-500/30' : 'bg-synth-accent text-synth-dark shadow-cyan-500/30'
                }`}
              >
                  {isPlaying ? <Pause fill="currentColor" size={24}/> : <Play fill="currentColor" size={24} className="ml-1"/>}
              </button>

              <div className="h-8 w-px bg-synth-grid mx-1" />

              <button 
                onClick={handleGenerate} 
                disabled={isGenerating || isPlaying} 
                className={`flex flex-col items-center justify-center px-4 py-1 rounded-lg border transition-all ${
                    isGenerating ? 'bg-slate-800 border-slate-700' : 'bg-synth-panel border-synth-grid hover:bg-slate-700 hover:border-slate-500'
                }`}
              >
                  <Activity size={18} className={`text-synth-pop mb-0.5 ${isGenerating ? 'animate-spin' : ''}`}/>
                  <span className="text-[8px] font-bold text-slate-300 uppercase tracking-wider">{isGenerating ? 'RENDERING...' : 'RENDER'}</span>
              </button>

              {generatedBuffer && (
                  <button onClick={handleDownload} className="p-2.5 rounded-lg bg-synth-panel border border-synth-grid text-slate-400 hover:text-white hover:bg-slate-700">
                      <Download size={18} />
                  </button>
              )}
          </div>
      </div>

      {/* BOTTOM NAV */}
      <nav className="fixed bottom-0 left-0 right-0 bg-synth-dark border-t border-synth-grid h-16 z-50 flex justify-around items-center px-2 safe-area-bottom">
          <button onClick={() => setActiveTab('COMPOSE')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors w-16 ${activeTab === 'COMPOSE' ? 'text-synth-accent' : 'text-slate-500 hover:text-slate-300'}`}>
              <Piano size={20} />
              <span className="text-[9px] font-bold">COMPOSE</span>
          </button>
           <button onClick={() => setActiveTab('RACK')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors w-16 ${activeTab === 'RACK' ? 'text-synth-accent' : 'text-slate-500 hover:text-slate-300'}`}>
              <Layers size={20} />
              <span className="text-[9px] font-bold">RACK</span>
          </button>
           <button onClick={() => setActiveTab('VOICE')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors w-16 ${activeTab === 'VOICE' ? 'text-synth-accent' : 'text-slate-500 hover:text-slate-300'}`}>
              <Sliders size={20} />
              <span className="text-[9px] font-bold">VOICE</span>
          </button>
           <button onClick={() => setActiveTab('MATH')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors w-16 ${activeTab === 'MATH' ? 'text-synth-pop' : 'text-slate-500 hover:text-slate-300'}`}>
              <SquareActivity size={20} />
              <span className="text-[9px] font-bold">MATH</span>
          </button>
           <button onClick={() => setActiveTab('CALC')} className={`flex flex-col items-center gap-1 p-2 rounded-lg transition-colors w-16 ${activeTab === 'CALC' ? 'text-orange-400' : 'text-slate-500 hover:text-slate-300'}`}>
              <Calculator size={20} />
              <span className="text-[9px] font-bold">CALC</span>
          </button>
      </nav>

      {/* MODALS */}
      {showLyricsModal && (
        <div className="absolute inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-synth-panel border border-synth-grid rounded-2xl w-full max-w-sm p-4 shadow-2xl flex flex-col gap-3">
                <div className="flex justify-between items-center border-b border-synth-grid pb-2"><h3 className="text-sm font-bold text-white flex items-center gap-2"><Type size={16} className="text-synth-accent" /> LYRICS</h3><button onClick={() => setShowLyricsModal(false)}><X size={18} className="text-slate-400"/></button></div>
                <textarea className="w-full h-32 bg-synth-dark border border-synth-grid rounded-xl p-3 text-white focus:border-synth-accent outline-none font-mono text-sm" placeholder="Paste lyrics..." value={lyricsInput} onChange={(e) => setLyricsInput(e.target.value)} />
                <button onClick={handleApplyLyrics} className="flex-1 py-2 rounded-xl text-xs font-bold bg-synth-accent text-synth-dark flex items-center justify-center gap-2"><Check size={14} /> APPLY</button>
            </div>
        </div>
      )}

      {showPitchModal && (
        <div className="absolute inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-synth-panel border border-synth-grid rounded-2xl w-full max-w-sm p-4 shadow-2xl flex flex-col gap-3">
                <div className="flex justify-between items-center border-b border-synth-grid pb-2"><h3 className="text-sm font-bold text-white flex items-center gap-2"><TrendingUp size={16} className="text-synth-pop" /> PITCH BEND</h3><button onClick={() => setShowPitchModal(false)}><X size={18} className="text-slate-400"/></button></div>
                <div className="relative w-full h-40 bg-synth-dark rounded-lg border border-synth-grid overflow-hidden cursor-crosshair"><canvas ref={pitchCanvasRef} width={340} height={160} onClick={handlePitchCanvasClick} className="w-full h-full"/><div className="absolute top-1/2 left-0 right-0 h-px bg-slate-600/50 pointer-events-none"/></div>
                <div className="flex gap-2 justify-center"><button onClick={() => setPitchCurve([{t:0,v:0},{t:1,v:0}])} className="text-[10px] px-2 py-1 bg-slate-700 rounded text-slate-300">FLAT</button><button onClick={() => setPitchCurve([{t:0,v:0},{t:1,v:5}])} className="text-[10px] px-2 py-1 bg-slate-700 rounded text-slate-300">RISE</button><button onClick={() => setPitchCurve([{t:0,v:0},{t:1,v:-5}])} className="text-[10px] px-2 py-1 bg-slate-700 rounded text-slate-300">FALL</button></div>
                <button onClick={handleApplyPitch} className="flex-1 py-2 rounded-xl text-xs font-bold bg-synth-pop text-white flex items-center justify-center gap-2"><Check size={14} /> APPLY</button>
            </div>
        </div>
      )}

    </div>
  );
};

export default App;
